            if item_size as f64 > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            if fitting_bins_count > 0 && mean_residual > 0.0 {
                let worst_case = item_size as f64 + mean_residual ;
                if worst_case > cap * 0.95 && progress < 0.7 {
                    score -= 6.0 ;
                }
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            // late stage: strongly prefer existing bins over opening new ones
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1,9] are nearly unusable
    // (items are >= 10 nominally, but interface allows 1..100; treat tiny gaps as waste).
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0; // hard penalty for unusable sliver
    } else if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space (10..=19) is risky: only next items <= gap can use it.
    if post_residual >= 10 && post_residual <= 19 {
        score += 18.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 9.0 {
            score -= 25.0; // chain fit: this placement sets up a near-perfect follow-up
        } else {
            score -= 8.0; // next item at least fits
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 12.0; // next item cannot use the leftover: dead space likely
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Deviation from mean residual: prefer bins whose residual is closest to the item
    // (tightest fit among candidates).
    score += ((bin_residual as f64 - item_size as f64) - mean_residual).abs() * 0.5;

    // New-bin candidate handling: bin_residual == bin_capacity means a fresh empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins would leave bad residue
        // or when open-bin count is low relative to progress.
        let waste_if_forced = if fitting_bins_count >= 1 {
            // approximate waste if we placed into an existing bin: mean residual minus item
            (mean_residual - item_size as f64).max(0.0)
        } else {
            100.0
        };
        score = 55.0
            + waste_if_forced * 0.8
            - 20.0 * (1.0 - progress)
            - (open_bins_count as f64).recip() * 5.0;
        if post_residual == 0 {
            score -= 5.0; // item exactly fills a fresh bin (item_size == capacity)
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect/near-perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    } else if post_residual > 40 {
        // Large dead space is wasteful unless item is huge relative to bin.
        score += 0.15 * (post_residual as f64 - 40.0);
    }

    // Lookahead (k=2): reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 + 0.2 * slack_after_next as f64;
        } else {
            // Next item won't chain here; slight penalty proportional to gap.
            let gap = next_item_size - post_residual.min(next_item_size);
            score += 0.05 * gap as f64;
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 0.3 * fit_ratio * 100.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin's fit would be very poor.
    if bin_residual == bin_capacity {
        let crowdedness = open_bins_count as f64;
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64);
        let poor_fit_elsewhere = (post_residual as f64) > mean_residual;
        let mut new_bin_score = 60.0
            - 8.0 * crowdedness.min(10.0)
            - 40.0 * mean_tight
            - if poor_fit_elsewhere { 20.0 } else { 0.0 };
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= 15.0 * (1.0 - progress);
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            new_bin_score -= 10.0;
        }
        score = score.min(new_bin_score);
    }

    // Mild preference to fill bins with residuals close to the mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Slight global pressure: many open bins -> prefer consolidating into existing ones.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item are heavily penalized. Items range 1..100, but small gaps
    // (< ~15) are statistically unlikely to be filled; treat them as waste.
    let dead_threshold: u32 = 14;
    if post_residual > 0 && post_residual < dead_threshold {
        // Steep quadratic penalty on unusable slivers.
        let gap = (dead_threshold - post_residual) as f64;
        score += 40.0 + 3.0 * gap * gap;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 15.0 / (1.0 + tightness);
    }

    // Coupling with lookahead: if the next item fits the post-residual exactly
    // or well, this placement is part of a good chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + slack);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap: mild penalty scaled by gap size.
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: penalize spreading across many open bins,
    // encouraging consolidation; but relax pressure near stream end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).powf(0.7) * (1.0 - 0.4 * progress);
    score += 0.8 * pressure;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a pointless new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // (large mean residual means existing bins are roomy -> don't open new).
    if bin_residual == bin_capacity {
        let new_bin_bonus = 10.0 + 0.5 * mean_residual - 3.0 * open_bins_count as f64;
        score += new_bin_bonus;
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps bin population homogeneous, easier future packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        // A residual is "dead" if the next item cannot use it.
        let next_fits = next_item_size > 0 && (post_residual as u32) >= next_item_size;
        if !next_fits {
            // Dead space: harsh penalty scaled by how close the gap is to being useless.
            let gap_ratio = post_residual as f64 / 100.0;
            score += 40.0 * (1.0 - gap_ratio) + 15.0;
        } else {
            // Usable gap: mild reward proportional to how well next item nests.
            let snug = 1.0 - ((post_residual as f64 - next_item_size as f64) / 100.0).abs();
            score -= 10.0 * snug;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Lookahead: if next item exactly matches post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open bins pressure: penalize spreading across many bins when residuals are large.
    let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    score += 3.0 * pressure;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Early stream: be greedy with tight fits; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when item barely fits anywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted if many bins are open with small residuals.
        score += 30.0 - 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins that are exactly filled.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize tiny dead space (unusable slivers) superlinearly.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0;
        }
    }

    // 2-step lookahead: reward residuals that exactly fit the next item,
    // penalize residuals that are just barely too small for it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Usable leftover for next item: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize how close we came (wasted opportunity).
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 1.5;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are already
    // "tight"; prefer spreading load so mean residual stays balanced.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Late in the stream, consolidate aggressively into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
