pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose residual falls into
    // "usable" classes (multiples of small denominators) are favored.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 25 == 0 {
        -9.0
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division threshold on post_residual: dead space too small for
    // the smallest plausible follow-up item is penalized.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (chained fit). If next item cannot fit at all,
    // mild penalty for wasting the slot.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin
    // would leave awkward residual relative to item size classes.
    if bin_residual == bin_capacity {
        // harmonic class of item size: items near capacity fractions
        // (e.g. >50% of C) pair well with a fresh bin.
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= 8.0;
        } else {
            score += 12.0;
        }
        // early stream: fewer open bins -> opening is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0 - open_bins_count as f64;
    } else {
        // Prefer tighter bins: scale by fullness
        let fullness = 1.0 - bin_residual as f64 / cap;
        score -= fullness * 8.0;
        // divergence from mean residual: bin far below mean residual is
        // a good target (it is nearly full)
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 64.0;
    } else if post_residual <= 2 {
        score -= 31.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 43.0 + 3.3 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.8 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 17.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        // NEW: exact double-host promise
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 11.0;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 7.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        // Divisible residual — next item tiles it perfectly.
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        // Waste-lock: slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // Slack band just below nxt is a stranded pocket.
        if slack > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 4.0 * band * band * (0.5 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        if slack > 20.0 && pr < mean_residual {
            score += 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
