            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Avoid fresh bins stranding a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Open a fresh bin when the item is large and would strand a big residual elsewhere.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin mean-band alignment.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space: gaps smaller than the minimum
    // plausible item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Soft penalty for small-ish gaps that few item sizes can use.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.1 * post_residual as f64;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into tight fits,
    // making existing bins more attractive vs. the new-bin candidate.
    score -= 1.5 * open_bins_count as f64;

    // Prefer bins whose residual is below average (tighter bins first),
    // leaving looser bins for larger future items.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if the next item would fit exactly into the resulting gap,
    // reward this placement; if the gap is useless for the next item, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Early in the stream, opening new bins is cheaper (flexibility preserved):
    // make the new-bin candidate relatively more attractive early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize post_residual with non-linear polynomial coupling
    let mut score = pr * (1.0 + 0.5 * progress);

    // Smooth polynomial coupling: small post-residuals are valuable, large ones wasteful
    let prn = pr / cap;
    score += 40.0 * prn * prn * (1.0 - prn) * (1.0 + progress);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - prn).powi(3) * 10.0 * (0.5 + progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: favor bins whose post_residual accommodates next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Mean residual deviation: prefer bins whose residual is near mean (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: mild penalty unless existing bins are very fragmented
    if bin_residual == bin_capacity {
        let frag = (open_bins_count as f64) * mean_residual / cap;
        score = 45.0 - 10.0 * frag + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Small gaps (< 10) are dead space; penalize steeply.
        if gap < 10.0 {
            score += (10.0 - gap) * 8.0;
        }
        // Perfect fit gets a strong reward.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Reward tight fits relative to residual (wasted fraction of bin).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Pressure from number of open bins: with many open bins, prefer packing
    // into existing bins (closing bins out) over spreading.
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += bin_pressure * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item cannot fit in post-residual but could fit elsewhere,
    // slight penalty for leaving a gap that traps the next item.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < 10 {
        score += 6.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin should only win when the fit into existing bins is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // If this bin is the only fitting option, opening a new bin is competitive.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

