            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0) ;
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0 ;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: strongly reward near-perfect fits.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    let min_useful = 10u32.min(bin_capacity);
    if post_residual < min_useful {
        score += 60.0;
    } else {
        // Usability of leftover space relative to mean residual pressure.
        let usable = post_residual as f64 / bin_capacity as f64;
        score -= 10.0 * usable;
    }

    // Lookahead (k=2): if the next item fits into post_residual, big reward (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.2 * next_item_size as f64;
        } else if next_item_size > bin_residual {
            // This bin can't take next item anyway; mild reward for keeping big bin free.
            score -= 5.0;
        } else {
            // Next item fits now but not after placement: penalize blocking.
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is costly; only attractive when
    // existing fits are poor or many bins are already open with fragmented space.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if open_bins_count > 0 {
            (mean_residual - post_residual as f64).abs()
        } else { 0.0 };
        // Base cost of a fresh bin, reduced when open bins are fragmented or plentiful.
        score += 50.0
            - 0.5 * open_bins_count as f64
            - 0.3 * fragmentation
            - 20.0 * (1.0 - fill_ratio);
        // Early in stream, slightly discourage hoarding new bins.
        score += 10.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Mild preference for bins with smaller residual (best-fit flavor) modulated by load.
    score += 0.1 * bin_residual as f64 / bin_capacity as f64;

    // Time horizon: late in the stream, close out bins aggressively (avoid spreading).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let nxt = next_item_size as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let is_new_bin = bin_residual == bin_capacity ;
    let cap = bin_capacity as f64 ;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 } ;
    let min_item = if item_size > 0 { item_size as f64 } else { 1.0 } ;
    let stranded = if pr > 0.0 && pr < min_item { 1.0 } else { 0.0 } ;

    if post_residual == 0 {
        score -= 60.0 ;
    } else if post_residual <= 2 {
        score -= 28.0 ;
    } else if post_residual <= 5 {
        score -= 13.0 ;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64 ;
        score += 42.0 + 3.2 * gap * gap ;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0) ;
        score += 4.0 + 0.8 * excess ;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        if slack < 5.0 {
            score -= 46.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 37.0 - 0.6 * slack ;
        } else {
            score -= 29.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
