pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer small post-residual, non-linearly
    let mut score = r * r / cap;

    // Smooth coupling with stream progress: late in the stream, dead space matters more
    let progress_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += progress_weight * rn * rn * cap * 0.5;

    // Penalize residuals that are too small to ever be useful (below min item size)
    let min_item = 1.0f64.min(cap);
    let unusable = (rn * (1.0 - rn)).max(0.0);
    score -= unusable * cap * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap as f64 * 0.75;
    }

    // Lookahead: reward residuals that still fit the next item
    if next_item_size > 0 {
        let fits_next = if (r as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= fits_next * next_item_size as f64 * 0.4;
        // Penalize post-residual just below next item (near-miss dead space)
        let gap = (next_item_size as f64 - r).max(0.0);
        score += gap * gap / cap * 0.2;
    }

    // Mild preference for bins deviating below mean residual (tighter packing)
    score += (mean_residual - r) * 0.05;

    // Slight penalty for proliferation of open bins late in stream
    score += open_bins_count as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in the "hard to reuse" zone
    // (residuals 1..=9 are nearly unusable for items >=10 in classic streams,
    // but with sizes 1..=100 small residuals are still dead weight).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Quantized waste: penalize residual in awkward modulo classes
    let r_mod = post_residual % 10;
    if r_mod != 0 {
        score += (10 - r_mod) as f64 * 0.8;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 20.0 - slack as f64 * 0.5;
    }

    // Penalize leaving a residual just barely below the next item size
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // New-bin candidate: only attractive when current bins are very fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation > 0.5 && open_bins_count > 0 {
            score -= 15.0 + 20.0 * fragmentation;
        } else {
            score += 30.0 * (1.0 - progress);
        }
    }

    // Mild preference for tighter bins overall
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Gaps that cannot fit the next item are also dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward residual that can host the lookahead item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Pressure from number of open bins: prefer existing bins when many are open,
    // but allow opening new bins when few are open (keeps fresh capacity available).
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        score += 20.0 * open_bins_count as f64;
        // New bin looks attractive if existing bins would leave very tight fits.
        let tightness = (bin_residual - item_size) as f64;
        score -= tightness * 0.5;
    } else {
        // Mild penalty proportional to how many bins could fit (prefer best fit).
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
        // Last-chance bin: strongly favor using it to avoid opening a bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Prefer bins whose residual is close to what we consume (tight packing).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Stream progression: early on, tolerate more openness; late, consolidate hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if !is_new_bin {
        score -= 20.0 * progress;
    } else {
        score += 30.0 * progress;
    }

    // Prefer bins below mean residual (more room used already) — consolidation.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let post = post_residual as f64;
    score -= 12.0 * (-post / 8.0).exp();

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (-gap / 6.0).exp();
        if gap == 0.0 {
            score -= 20.0; // exact 2-item chain completion
        }
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize dead space relative to mean residual.
        score += 0.5 * post + 0.3 * (mean_residual - post).abs();
    }

    // Penalize wasting a nearly-full bin on a small item when alternatives exist.
    if post_residual > 0 && post_residual < 5 && fitting_bins_count > 1 {
        score += 8.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: make it unattractive unless it's genuinely better.
    // An empty bin has huge residual; add a fixed opening penalty.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.1 * open_bins_count as f64;
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer small post-residual (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Waste penalty: dead space that cannot fit even the smallest plausible item (<= 10).
    if post_residual < 10 {
        score -= 25.0; // fully packed bin is great (but it's the same bin anyway)
    } else if post_residual < item_size {
        // residual smaller than current item: moderately dead unless next item fits
        if next_item_size == 0 || next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Lookahead coupling: reward if next item fits the post-residual well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 18.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // next item won't fit here after placement; slight penalty for wasting space
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // late in stream, favor filling existing bins even more
        score -= 10.0 * progress;
    } else {
        // New-bin candidate: penalize opening a new bin unless the fit elsewhere
        // would be terrible. Base penalty plus scaling with open bins and progress.
        score += 45.0 + 3.0 * open_bins_count as f64 + 20.0 * progress;
        // If item is huge, a fresh bin is more acceptable.
        if item_size >= 70 {
            score -= 25.0;
        }
        // If next item is small, a fresh bin can host both -> reduce penalty.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual is close to the item (exactness measure).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 40.0 * coupling;

    // Penalize wasted capacity more strongly as the stream progresses (bins become scarcer in value).
    score += (pr_norm * pr_norm) * 30.0 * progress;

    // Reward tight fits: small post residual relative to item size.
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 20.0 / (1.0 + fit_ratio);

    // Lookahead: favor bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * snug * snug;
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Mean residual context: avoid bins far from the mean (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 12.0 * dev * dev;

    // Many open bins: prefer consolidating into existing ones rather than opening new.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 5.0;
    } else {
        // New-bin candidate: penalize mildly, more when progress is high and mean residual is large.
        score += 20.0 + 25.0 * progress + 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit rewards: exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Harmonic class logic: classify post_residual into usable residue classes.
    // Residuals that can host common small items (multiples of 10) are valuable;
    // dead-space residuals that nothing can fill are penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // unusable dead space below the minimum item size
        score += 12.0;
    } else if pr >= 10 && pr < 20 {
        score -= 4.0; // can host the smallest items
    } else if pr % 10 == 0 && pr > 0 {
        score -= 6.0; // perfectly reusable harmonic class
    } else if pr % 10 >= 8 {
        score += 3.0; // awkward residue class
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        } else if next_item_size > post_residual {
            score += 5.0; // next item won't fit here anyway; residual likely stranded
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // use it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate penalty: opening a new bin wastes the residual
    // stranded in existing bins. Only allow it when the best existing fit
    // is truly poor (handled via large post_residual of existing bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 10.0 * (1.0 - progress);
        // A new bin is attractive only if the item is huge relative to capacity
        // and would leave a highly reusable residual class.
        if item_size >= 80 && post_residual % 10 == 0 && post_residual > 0 {
            score -= 14.0;
        }
    }

    // Slight preference for bins whose residual deviates from the mean
    // in the "tighter" direction (consolidate slack).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills (small but usable residual).
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item if it still fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage new bins when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        score += 30.0 + (open_bins_count as f64) * (2.0 + 4.0 * progress);
    } else {
        // Mild reward for using existing bins, stronger later in the stream.
        score -= 1.0 + 2.0 * progress;
    }

    // Prefer bins tighter than average (best-fit style).
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        // Near-perfect match reward, decaying with distance.
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score -= 25.0 * (1.0 - diff / 40.0).max(0.0);
        // Penalize post-residual that can't fit the next item (dead space risk),
        // especially when the gap is large enough that no partial use is likely.
        if post_residual < next_item_size {
            let waste = next_item_size - post_residual;
            score += 0.35 * waste as f64;
        }
    }

    // Penalize very small unusable post-residual (dead space).
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (little slack left relative to capacity).
    score -= 0.2 * (bin_capacity - post_residual) as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Avoid fragmenting bins whose residual is far above mean (keep big bins flexible)
    // unless the fit is excellent.
    if bin_residual as f64 > mean_residual + 15.0 {
        score += (bin_residual as f64 - mean_residual - 15.0) * 0.3;
    }

    // Late in the stream, consolidate: prefer existing bins over new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: squared penalty on wasted space.
    score += 0.9 * post * post / cap;

    // Reward leaving residual that exactly matches the lookahead item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let gap = post - next_item_size as f64;
        score -= 6.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space the next item cannot use.
        score += 4.0 * post / cap;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when good alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / cap;
        score += 8.0 + 10.0 * pressure - 5.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 3.0; // chain large items together in fresh bins
        }
    }

    // Mild penalty for fragmenting many-bin states.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;
    let tight = 1.0 - (pr / cap).powi(2);

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr.powf(1.2) * (1.0 + 0.5 * progress);

    // Reward high fill fraction more as stream progresses (smooth coupling)
    score -= 40.0 * fill * fill * (0.5 + progress);

    // Penalize residual that is close to, but not equal to, useful next-item size
    // (dead space): smooth trough when post_residual matches next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let d = (pr - nxt) / cap;
        score += 15.0 * d * d - 8.0 * (-d * d * 400.0).exp();
    }

    // Penalize leaving residuals below typical item size (unusable dead space),
    // smoothly scaled by stream progress
    let dead = (1.0 - pr / 80.0).max(0.0);
    score += 20.0 * dead * dead * progress;

    // Last-chance bin: strong reward to use it (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + tight);
    }

    // Slight penalty when bin residual deviates far below mean residual
    // (keeps bin pool balanced, smooth quadratic coupling)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: how well it can host future items.
    // Residuals that are multiples of common item sizes are "usable" classes.
    let r = post_residual;
    let mut usable_bonus = 0.0;
    for m in [10u32, 20, 25, 50, 100].iter() {
        if r % m == 0 && r > 0 {
            usable_bonus += 15.0;
        }
    }
    score -= usable_bonus;

    // Penalize residuals too small to host typical small items (dead space).
    if r < 10 {
        score += 60.0;
    } else if r < 20 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 200.0;
        } else if next_item_size < r {
            // Prefer leaving room for the next item, scaled by how snug it is.
            score -= 40.0 * (next_item_size as f64 / r as f64);
            // Harmonic check: residual after the next item also lands in a good class.
            let r2 = r - next_item_size;
            if r2 % 10 == 0 || r2 % 25 == 0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here; penalize slightly so we don't hoard space uselessly.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): penalize unless current open bins are crowded
    // or the fit into open bins is poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / 20.0;
        let fit_penalty = post_residual as f64 / bin_capacity as f64;
        score += 120.0 - 60.0 * crowding - 50.0 * fit_penalty;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
    }

    // Mild preference for filling bins more completely as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Tie-break toward bins with low mean residual across the fleet (balance).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item are heavily penalized. Items range 1..100, but small gaps
    // (< ~15) are statistically unlikely to be filled; treat them as waste.
    let dead_threshold: u32 = 14;
    if post_residual > 0 && post_residual < dead_threshold {
        // Steep quadratic penalty on unusable slivers.
        let gap = (dead_threshold - post_residual) as f64;
        score += 40.0 + 3.0 * gap * gap;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 15.0 / (1.0 + tightness);
    }

    // Coupling with lookahead: if the next item fits the post-residual exactly
    // or well, this placement is part of a good chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + slack);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap: mild penalty scaled by gap size.
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: penalize spreading across many open bins,
    // encouraging consolidation; but relax pressure near stream end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).powf(0.7) * (1.0 - 0.4 * progress);
    score += 0.8 * pressure;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a pointless new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // (large mean residual means existing bins are roomy -> don't open new).
    if bin_residual == bin_capacity {
        let new_bin_bonus = 10.0 + 0.5 * mean_residual - 3.0 * open_bins_count as f64;
        score += new_bin_bonus;
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps bin population homogeneous, easier future packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect two-item packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for tight match, scaled by how big the match is.
        let match_reward = (bin_capacity as f64 - diff) * 0.9;
        score -= match_reward;
        // Extra bonus for exact fit of the next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize dead space that neither the next item nor small items can use.
        if post_residual < next_item_size && post_residual < 10 {
            score += 30.0;
        }
    } else {
        // Last item: prefer minimal residual.
        score += 0.0;
    }

    // Compare post_residual relative to mean residual across open bins:
    // prefer bins whose residual after placement is closer to the mean
    // (keeps bins homogeneous and reusable).
    let post_f = post_residual as f64;
    score += (post_f - mean_residual).abs() * 0.4;

    // Penalize large residual waste relative to capacity.
    score += (post_f / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when no good
    // fit exists (post_residual would be large in existing bins).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; a fresh bin gives full capacity
        // for the next item, which is valuable if lookahead is large.
        let fresh_bonus = if next_item_size > 0 {
            next_item_size as f64 * 0.5
        } else {
            0.0
        };
        score = bin_capacity as f64 * 0.5 - fresh_bonus;
        // Discourage opening new bins when plenty of bins already fit the item.
        if fitting_bins_count > 0 {
            score += 20.0 + 5.0 * fitting_bins_count as f64;
        }
    }

    // Slight preference for using fewer bins overall.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio;

    // Strong reward for near-perfect fill.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 20.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let nfit = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * nfit;
        } else {
            // next item cannot use this residual: penalize large residual a bit
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global state: many open bins -> consolidate, penalize spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * open_pressure * (1.0 - fit_ratio);

    // Compare residual to mean residual: prefer bins tighter than average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate logic: an empty bin should only win if no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so early (amortize over remaining stream).
        let horizon = 1.0 - progress;
        score += 45.0 + 30.0 * horizon;
        // But if item is large and would leave dead space in any bin, new bin is fine.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 50.0;
        }
        // If mean residual across open bins is small (fragmented), new bin attractive.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Time-dependent tightening: as stream progresses, demand tighter fits.
    score -= 15.0 * progress * fit_ratio;

    // Small tie-break noise-free deterministic jitter to break exact ties
    // toward bins with larger residual among equal post_residual.
    score -= 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of residual with stream progress:
    // early on, waste matters less; late, large residuals are costly.
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score *= 1.0 + 0.9 * prog2 + 0.6 * prog3;

    // Reward tight fits: small post_residual relative to capacity.
    let tight = 1.0 - pr / cap;
    score -= 22.0 * tight * tight * tight;

    // Penalize dead space: post_residual too small for the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 30.0 * gap * gap;
        } else {
            // reward leaving room exactly usable by next item
            let fit_gap = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Slight penalty when many bins are open (encourage consolidation).
    score += 0.35 * (open_bins_count as f64).ln().max(0.0);

    // Mean-residual coupling: prefer bins whose residual is below average
    // (fill down the low-residual bins first, keeping big holes open).
    score += 0.12 * (mean_residual - bin_residual as f64);

    // New-bin candidate: mild handicap so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "dead" classes (small but unusable slivers) get penalized.
    let post = post_residual;
    let class = post / 10; // integer division threshold: 0..10
    match class {
        0 => { score -= 40.0; }                      // near-perfect fill
        1 => { score -= 25.0; }                      // excellent
        2 => { score -= 12.0; }                      // good
        3 => { score -= 4.0; }                       // decent
        4 => { score += 6.0; }                       // mediocre
        5 => { score += 14.0; }                      // half-full bin, wasteful
        6 => { score += 20.0; }
        7 => { score += 24.0; }
        8 => { score += 26.0; }
        _ => { score += 28.0; }                      // almost untouched bin
    }

    // Modulo arithmetic: residuals that are multiples of 5 or 10 are more
    // likely to be exactly consumed by future items.
    if post % 10 == 0 {
        score -= 8.0;
    } else if post % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward; if it fits at all, mild reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 35.0;
        } else if next_item_size <= post {
            score -= 10.0;
            let gap = post - next_item_size;
            if gap % 10 == 0 { score -= 5.0; }
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += (post as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly. Make the empty bin's raw score (post == 100)
    // high, but discount it slightly when open-bin pressure is high or the
    // item is large relative to mean residual.
    if bin_residual == bin_capacity {
        // post_residual == capacity here; base score already large.
        let pressure = open_bins_count as f64;
        score += pressure * 3.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // large item followed by larger: keep fresh bin
        } else {
            score += 25.0;
        }
        // early stream: opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer filling bins that are already below mean residual (tightening
    // the residual distribution).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.3;
    } else {
        score += (resid_f - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest conceivable item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Near-dead gaps: hard for future items to use efficiently.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (best-fit core), stronger as fit gets tighter.
    let tightness = (bin_residual - post_residual) as f64 / item_size.max(1) as f64;
    score -= 12.0 * tightness;

    // Reward leaving a gap that the lookahead item could exactly use.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if the lookahead item cannot fit in the post residual (dead pairing).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when
        // existing bins have very poor fits (high mean residual waste).
        score += 55.0 + pressure;
        score -= 0.15 * mean_residual;
    } else {
        // Existing bins get a mild bonus proportional to mean residual mismatch:
        // prefer bins whose residual is far below mean (i.e., nearly full bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild preference to keep filling bins early in the stream.
    score -= 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits comfortably in the remaining space (with slack tolerance).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Prefer bins where next item leaves little dead space too.
        score -= 25.0 - 0.4 * slack;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot follow here: dead space likely, penalize.
        score += 15.0;
    }

    // Compare post residual against mean residual: creating below-average
    // residual means we consumed more of a bin than typical -> good compaction.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent fits exist: new-bin candidate has
    // bin_residual == bin_capacity; its post_residual is large, so add extra.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
        // But if no open bin can fit the item at all, opening is necessary:
        // soften penalty so new bin wins in that case.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early in the stream, be slightly more willing to spread items (future
    // flexibility); late in the stream, compact aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (bin_capacity as f64 - pr) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 14.0 * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize tiny unusable dead space (residual < 10 likely dead).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item won't fit here; slight penalty for leaving awkward space.
            score += 3.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits, or when this
    // bin would leave large unusable space while a fresh bin preserves flexibility.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 60.0; // forced new bin
        } else {
            // Penalize opening a new bin when a decent fit exists elsewhere.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 30.0 + 20.0 * (1.0 - progress);
            // If the best alternative leaves dead space, soften the penalty.
            if post_residual < 10 {
                score -= 22.0;
            }
        }
    }

    // Global state: many open bins with large mean residual -> prefer filling
    // existing bins rather than spreading.
    if bin_residual != bin_capacity {
        score -= 0.08 * open_bins_count as f64;
        score += 0.10 * (mean_residual - post_residual as f64).abs();
    }

    // Prefer bins whose residual is close to item size (minimal waste).
    let waste = (bin_residual - item_size) as f64;
    score += 0.15 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let irn = item_size as f64 / cap;

    // Base: smooth polynomial in normalized post residual, shaped by progress
    let base = pr * (1.0 + 0.8 * progress * prn * prn);

    // Reward tight fits more strongly later in the stream (smooth coupling)
    let tight_bonus = -(1.0 - prn).powi(3) * (20.0 + 30.0 * progress);

    // Penalize dead space that is too small for likely future items (smooth)
    let dead_penalty = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        gap * gap * (10.0 + 40.0 * progress)
    } else { 0.0 };

    // Last-chance bin: smooth reward when few fitting bins
    let scarcity = (fitting_bins_count as f64).recip();
    let last_chance = -scarcity * (8.0 + 12.0 * progress) * (1.0 - prn);

    // Mild preference for bins deviating from mean residual (balance)
    let spread = ((bin_residual as f64 - mean_residual) / cap).abs();
    let balance = 4.0 * spread * (0.5 + progress);

    // Slight penalty on opening new bins when many are open
    let open_bias = if bin_residual == bin_capacity {
        6.0 + 0.3 * open_bins_count as f64 + 10.0 * (1.0 - progress) * (1.0 - irn)
    } else { 0.0 };

    base + tight_bonus + dead_penalty + last_chance + balance + open_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // residue classes (multiples of common item sizes) are more valuable.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward post-residuals that are divisible into common chunk sizes
    // (harmonic classes: 50, 25, 20, 10, 5, 2).
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit: best possible outcome
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -7.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr % 2 == 0 {
        -1.5
    } else {
        2.0 // odd residuals tend to become dead space
    };
    score += harmonic_bonus;

    // Dead-space penalty: small unusable leftovers (1..=9) are waste.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.5;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly prefer this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 - slack * 0.3; // tighter follow-up fit is better
            if (pr - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // next item cannot use this residual; penalize large leftovers
            score += 1.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Fractional capacity logic: filling a bin past half capacity is good;
    // leaving a bin just under a half/quarter boundary is wasteful.
    let fill_fraction = (bin_residual as f64) / cap;
    if fill_fraction > 0.5 && fill_fraction <= 1.0 {
        score -= 4.0 * fill_fraction;
    }

    // Prefer using already-open bins over spreading load; scale with congestion.
    if bin_residual != bin_capacity {
        score -= (open_bins_count.min(20) as f64) * 0.4;
    } else {
        // New-bin candidate: only attractive when existing bins fit badly
        // (very small post residual elsewhere) or stream is early.
        score += 12.0;
