        // extra costly: it forces a fresh bin downstream.
        if fitting_bins_count <= 1 && bin_residual != bin_capacity {
            score += 10.0;
        }
    }

    // Coupling: when the current item leaves residual that pairs with the
    // next item to fill the bin exactly in two steps, prefer strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step <= 2 {
