        let slack = post_residual - next_item_size;
        // Reward if next item fits with a class-1-like or exact leftover.
        if slack == 0 { score -= 20.0; }
        else if slack <= 25 { score -= 12.0; }
        else if slack % 10 == 0 { score -= 6.0; }
        else { score += 3.0; }
    } else if next_item_size > 0 {
        // Next item cannot fit here; mild penalty scaled by how far off we are.
        let gap = next_item_size as f64 - post;
        score += (gap / cap).min(1.0) * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a fresh bin is only good when this bin
    // would be left with dead space (class 0) or the item is large.
    if bin_residual == bin_capacity {
        // Base cost of a new bin: residual 100 is maximally wasteful now.
        score += 20.0;
        // But if the current item is big (> half capacity), a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
