        score -= 40.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward;
    // otherwise penalize slightly (this bin may strand the next item).
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 10.0 + 0.1 * next_item_size as f64;
            // Harmonic alignment: next item exactly divides remaining space
            if post % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            let gap = (next_item_size - post) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // of all open bins; penalize proportionally unless open bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + mean_residual * 0.2 * (open_bins_count as f64).sqrt();
        // Early in stream, slightly cheaper to open bins (build diversity)
        score -= 10.0 * (1.0 - progress);
    } else {
        // Prefer tighter fits among open bins: reward small bin_residual gap
        score += 0.05 * (bin_residual - item_size) as f64;
