        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Modulo threshold on item_size: items in "large class" (>50) should
    // prioritize best-fit tightly to avoid fragmentation
    if item_size > 50 {
        score += 0.1 * post as f64;
    }

    // Mild open-bins pressure: with many open bins, prefer consolidation
    score += 0.3 * open_bins_count as f64;

    score
}

