        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
    }

    // Open-bin pressure: consolidate, relax near stream end.
    let pressure = (open_bins_count as f64).powf(0.7) * (1.0 - 0.4 * progress);
    score += 0.8 * pressure;

    // New-bin candidate logic: open a fresh bin only when no open bin offers
    // a good chained fit for the next item, or early with poor alternatives.
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0; // strongly prefer existing bin with chained fit
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item_size as f64 > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item_size as f64 > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
        }
    }

    // Homogeneity: mild pull toward mean residual.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

