                score -= 5.0;
            }
            if progress > 0.85 && next_item_size > 0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
        }
    }

    // Prefer tighter bins relative to mean residual.
    score -= 0.2 * (mean_residual - pr);

