}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth polynomial coupling: dead-space penalty grows non-linearly with stream progress
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * norm_post * norm_post * progress;
    score += 8.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic mismatch)
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.08 * gap * gap / bin_capacity as f64;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * norm_post;

    // Prefer bins whose residual is close to the mean residual (homogeneity bonus)
    score += 0.3 * (post_residual as f64 - mean_residual).abs() / bin_capacity as f64;

    score
}

