    if post_residual % 20 == 0 { score -= 8.0; }
    if post_residual % 10 == 0 { score -= 4.0; }

    // Penalize tiny dead space that no item (min size 1..10 band) can use well
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // --- Lookahead coupling: does next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits perfectly here: strong reward, scaled by fit tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - tight / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 20.0; // perfect chain
            }
