    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0; // strongly prefer using the only bin that fits
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost plus a term that grows with how many
        // open bins already have large residuals (avoid hoarding empties).
        score = bin_capacity as f64 - 18.0 + 5.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // But if no open bin gives a harmonic fit, new bin is attractive
        if class25 == 0 && class20 == 0 && class10 == 0 && post_residual != bin_capacity {
            score -= 10.0;
        }
    }

    // --- Mean residual coupling: prefer bins near the mean (balanced packing) ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // --- Fill ratio bonus: tighter fit into existing space is better ---
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill;

    // --- Integer-division threshold nudges ---
    if class10 >= 7 { score -= 2.0; }       // residual >= 70 still very usable
    if class20 == 0 && post_residual > 0 { score += 5.0; } // residual < 20 is risky

    score
}

