pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit any plausible future item
    // (min item size 1, but small gaps < ~15 are statistically hard to fill)
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 + (15 - post_residual) as f64 * 3.0;
    }

    // Perfect or near-perfect fit is excellent
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open
    if bin_residual == bin_capacity {
        // brand-new bin candidate
        score += 15.0 + open_bins_count as f64 * 2.0;
        // but if next item won't fit anywhere well, new bin may be fine
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0;
        }
    } else {
        // mild reward for keeping bins consolidated
        score -= open_bins_count as f64 * 0.3;
    }

    // Lookahead: if next item exactly fills the post residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
