pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fits).

    // === Aggressive 2-step lookahead matching ===
    if next_item_size > 0 {
        let next = next_item_size as f64;

        // Perfect 2-step match: post_residual exactly equals next item size.
        if post_residual as f64 == next {
            score -= 60.0;
        }
        // Next item fits exactly into post_residual with small slack: good chain.
        else if next_item_size <= post_residual {
            let slack = post_residual as f64 - next;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // Bonus for near-perfect chained fit.
            if slack <= 5.0 {
                score -= 15.0;
            }
        }
        // Next item does NOT fit after this placement: dead space risk.
        else {
            // Penalize proportionally to how much post_residual is wasted relative to next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * waste;
            // If post_residual becomes unusable dead space (too small for typical min item),
            // the placement is "closed" — that's actually fine if post_residual tiny.
            if post_residual < 10 {
                score -= 20.0; // effectively sealed bin, no fragmentation
            }
        }
    } else {
        // Last item: just minimize post_residual (already done by base).
        score -= 5.0;
    }

    // === Mean residual coupling ===
    // Prefer bins whose post_residual lands near the mean residual of open bins
    // (keeps residual distribution balanced for future items).
    let drift = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * drift;

    // === Last-chance bin pressure ===
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        // This is the only bin that fits; avoid opening a new bin unless fit is terrible.
        score -= 30.0;
        // But if the 2-step lookahead strongly disfavors this bin, soften the last-chance bonus.
        if next_item_size > 0 && next_item_size > post_residual && post_residual >= 10 {
            score += 18.0;
        }
    }

    // === New-bin candidate handling ===
    if bin_residual == bin_capacity {
        // New bin is attractive when current bins would leave large unusable residuals.
        let poor_fit_elsewhere = if next_item_size > 0 {
            (next_item_size as f64 > mean_residual) as f64
        } else {
            0.0
        };
        // Slight penalty so tight existing fits still win; reward new bin when
        // mean residuals are large and next item is big.
        score += 8.0 - 20.0 * poor_fit_elsewhere;
    }

    // === Phase scaling: early in stream, be pickier about tight fits ===
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

