        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 7.0 ;
        }
        // sweet-band slack reward, slightly sharpened
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.5 * (1.0 - slack / 7.0) ;
        }
        // reward leaving slack close to mean residual (likely fillable later)
        if slack > 6.0 && (slack - mean_residual).abs() <= 2.0 {
            score -= 2.0 ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        // tiny residuals the next item can't use: extra penalty
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        // near-miss: next item barely doesn't fit, mild penalty
        if nxt - pr <= 2.0 {
            score += 4.0 ;
        }
    }

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0 ;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item_size as f64 > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            if item_size as f64 > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // fresh bin mid-stream when all fits would strand big residuals
            if progress > 0.4 && progress < 0.85 && fitting_bins_count > 0
                && nxt > 0.0 && mean_residual > 0.0 && pr < mean_residual * 0.6 {
                score += 5.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = fitting_bins_count as f64;

    // Base: prefer minimal post residual (tight fit)
    let mut score = post;

    // Smooth non-linear penalty on wasted space, stronger as stream progresses
    let waste_frac = post / cap;
    let waste_penalty = waste_frac * waste_frac * (1.0 + 40.0 * progress);
    score += waste_penalty;

    // Reward bins whose post residual matches the next item (lookahead coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = (post - nxt) / cap;
        score -= 6.0 * (-match_term * match_term * 8.0).exp();
    }

    // Last-chance bonus: smooth escalation when few fitting bins
    let scarcity = 1.0 / (1.0 + fit);
    score -= 15.0 * scarcity * scarcity;

    // Mild pull toward mean residual state (avoid fragmenting outlier bins)
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize opening new bins mildly, more early on
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Smooth coupling: progress-scaled reward for near-perfect fills
    score -= 10.0 * progress * (-waste_frac * 20.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
