    let stranded = if pr > 0.0 && (item_size as f64) > 0.0 && pr < item_size as f64 { 1.0 } else { 0.0 };

    // Perfect fill reward (strengthened).
    if next_item_size > 0 && post_residual as f64 == nxt {
