    score -= 0.2 * (mean_residual - pr);

    // Late-stream urgency: consolidate, avoid stranding capacity.
    if progress > 0.6 && pr > 0.0 && pr / cap > 0.25 {
        score += 10.0 * (pr / cap) * (progress - 0.6) * 5.0;
    }
    if progress > 0.8 && post_residual > 0 && post_residual < 6 {
        score -= 5.0;
    }
    if post_residual > 0 {
        score += 6.0 * dead * progress;
        if stranded > 0.0 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10 and mod 25.
    let post = post_residual;
    let mod10 = post % 10;
    let mod25 = post % 25;

    // Dead-space penalty: residuals that are small but not zero are wasteful.
    if post > 0 && post < 10 {
        score += 12.0;
    }
    // Perfect fits are golden.
    if post == 0 {
        score -= 40.0;
    }

    // Harmonic bonus: post_residual divisible by 10 (a "harmonic" class) is more reusable
    // since item sizes span 1..100 and many sizes pair well with round residuals.
    if mod10 == 0 && post > 0 {
        score -= 6.0;
    }
    if mod25 == 0 && post > 0 {
        score -= 4.0;
    }
    // Odd, prime-adjacent residues (mod10 in {1,3,7,9}) are hard to fill.
    if post > 0 && (mod10 == 1 || mod10 == 3 || mod10 == 7 || mod10 == 9) {
        score += 3.0;
    }
    // Integer-division threshold: post_residual / 25 gives coarse fill class.
    let quarter = post / 25;
    score -= quarter as f64 * 2.0;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size <= post {
            let nxt_post = post - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 5.0;
            }
            if nxt_post > 0 && nxt_post < 10 {
                score += 6.0;
            }
        } else {
            // Next item won't fit here; small penalty scaled by overflow.
            score += (next_item_size - post) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it's chosen only when
    // open bins offer genuinely poor fits, but keep it competitive for big items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 10.0 * progress;
        // Large items justify fresh bins more readily.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Tight-fit reward: item consuming most of the bin is efficient.
    let fill_frac = item_size as f64 / cap;
    if fill_frac > 0.8 {
        score -= 5.0;
    }

    // Mean-residual coupling: prefer bins deviating below mean (consolidate waste).
    score += (mean_residual - post as f64) * -0.05;

    // Many open bins: encourage closing bins out (favor fuller bins).
    score += (post as f64 / cap) * (open_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

