pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (size 1..100, but items < 10 are rare dead weight)
    // are nearly worthless. Penalize heavily if post_residual is a tiny gap.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Dead space relative to capacity: quadratic waste pressure.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * dead_frac * 30.0;

    // Reward tight fits (waste-free packing).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        }
        // If next item cannot fit in post_residual, mild penalty scaled
        // by the leftover gap size.
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins exist
    // and mean residual across open bins is still ample.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).sqrt() * 2.0 + mean_residual * 0.08;
    score += pressure * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is acceptable only if all open bins are nearly full
        // (tight residuals) or many bins are already open (packing phase done).
        let avg_tightness = mean_residual / bin_capacity as f64;
        if fitting_bins_count > 0 && avg_tightness > 0.25 && open_bins_count < 6 {
            score += 60.0; // keep using existing bins
        } else if fitting_bins_count > 0 && avg_tightness > 0.15 {
            score += 25.0;
        }
        // Otherwise leave score low: fresh bin is fine when nothing fits well.
        // Slight decay with stream progress to consolidate late.
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for bins with small current residual (best-fit flavor).
    score += (bin_residual as f64) * 0.05;

    score
}

