}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (small dead space is disproportionately bad).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 150.0;
            } else {
                // Partial credit proportional to how much of the next item fits,
                // penalizing leftover slack after the hypothetical second placement.
                let second_left = post_residual - next_item_size;
                score -= 60.0 - (second_left as f64).min(60.0);
            }
        } else {
            // Lookahead fails: penalize proportionally to the gap (dead space risk).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor), punish loose bins.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin is a last resort unless the item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 90.0;
        // If the item is big, a fresh bin is more attractive.
        if item_size > bin_capacity / 2 {
            score -= 60.0;
        }
        // If many bins are open and mean residual is small, prefer consolidation.
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score += 50.0;
        }
        // Early in the stream, opening bins is cheap.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 40.0;
        }
    }

    // Slight preference for keeping few open bins when this bin is roomy.
    if open_bins_count > 5 && post_residual > 30 {
        score += 5.0;
    }

    score
}

