    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: mild penalty so we prefer reusing open bins,
    // but relax the penalty late in the stream or when many bins are already open.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 15.0 - 4.0 * openness - 5.0 * t;
        // opening a new bin is attractive if the item is large (poor fit elsewhere)
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        // reward tight fits into existing bins
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 5.0 * tightness;
    }

    // Global state coupling: when mean residual is high, prefer bins with
    // residual close to item_size (reduce fragmentation).
    let diff = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.05 * diff;

    // Slight preference for larger bins late in stream
    score += 0.02 * (bin_residual as f64) * (1.0 - t);

    score
}

