pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early on: prefer tight fits (low post_residual). Late: tolerate larger residuals
    // to keep bins consolidated; interaction term shifts the curvature over time.
    let pr_norm = pr / cap;
    let tightness = pr_norm * pr_norm; // convex penalty for dead space
    let progress_coupling = tightness * (1.0 - 2.0 * progress); // flips sign mid-stream
    score += 18.0 * progress_coupling * cap * 0.01;

    // Cubic smooth term: reward near-perfect fits increasingly with progress.
    let perfect = 1.0 - pr_norm;
    score -= 12.0 * perfect * perfect * perfect * (0.5 + progress);

    // Lookahead: if next item fits the post residual, reward this bin smoothly.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            let fit_quality = 1.0 - (gap / cap);
            score -= 8.0 * fit_quality * (1.0 - progress);
        } else {
            // Smooth penalty for wasted space relative to lookahead item.
            let waste = (-gap / cap).min(1.0);
            score += 6.0 * waste * waste;
        }
    }

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild consolidation pressure when many bins are open.
    let open_norm = (open_bins_count as f64 / (open_bins_count as f64 + 10.0)) - 0.5;
    score += 4.0 * open_norm * pr_norm;

    // Deviation from mean residual: prefer bins whose residual is close to mean
    // (keeps open bins balanced) with a smooth quadratic term.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: penalize slightly so it only wins when fits are poor;
    // relax this penalty as the stream progresses.
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
    }

