    // Harmonic class of post_residual: which capacity fraction band does it land in?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual as u32;

    // Dead-space penalty: residuals in (0, 10) are nearly useless for future items.
    if post > 0 && post < 10 {
        score += 40.0;
