    if post == 0 {
        score -= 60.0; // perfect fit
    } else if post % quarter == 0 {
        score -= 30.0;
    } else if post % eighth == 0 {
        score -= 15.0;
    } else if post % (bin_capacity / 3) == 0 {
        score -= 12.0;
    }

    // Integer-division thresholds: classify residual into usable slots.
    let slot = post / eighth; // 0..=8 harmonic index
    let slot_f = slot as f64;
    // Mid-band residuals (slot 3..5, i.e. ~25%-62% left) are most reusable.
    score -= (slot_f - 4.0).abs().max(2.0) * 3.0;

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Reward tight lookahead fits (next item nearly fills the leftover).
            let tight = (post - next_item_size) as f64;
            score -= 25.0 - tight.min(25.0);
        } else {
            // Penalize residuals just barely below the next item's size (frustrating).
            let gap = (next_item_size - post) as f64;
            if gap <= 10.0 {
                score += 20.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when open bins have poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // If current item is large relative to capacity and few bins fit it, new bin is fine.
        let frac = item_size as f64 / cap;
        if frac > 0.7 {
            score -= 30.0;
