        // Late in the stream, avoid hoarding open bins.
        if open_bins_count as f64 > 8.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64) {
            score -= 15.0;
        }
        // If mean residual is small, existing bins are congested; opening fresh helps.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Mild preference for bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Small reward for placing larger items into fuller bins (best-fit flavor).
    score -= item_size as f64 * 0.05;

    score
