pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10-unit classes.
    let class = post_residual / 10;
    let phase = post_residual % 10;

    // Reward post_residuals in "usable" harmonic classes: multiples of 10 are
    // easy to fill by future items (sizes 1..100, often multiples of 5/10).
    let class_bonus = match class {
        0 => 40.0,                       // dead space <= 9: nearly wasted
        1 | 2 => 18.0,                   // small slivers, hard to reuse
        3 | 4 => 8.0,
        5 | 6 | 7 => 0.0,                // sweet spot: 50..79 reusable
        _ => -6.0,                       // large residual still flexible
    };
    score -= class_bonus;

    // Penalize non-round phases (post_residual % 10 in 1..4): these leave
    // awkward gaps that only very small items can fill.
    if phase > 0 && phase <= 4 {
        score += 6.0;
    } else if phase >= 5 && phase <= 9 {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect harmonic pair
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 10.0 - (gap as f64) * 0.15; // good fit, penalize gap
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer filling it rather than opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
