    // penalize residuals that are just barely too small for it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Usable leftover for next item: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize how close we came (wasted opportunity).
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 1.5;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are already
    // "tight"; prefer spreading load so mean residual stays balanced.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Late in the stream, consolidate aggressively into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.05;

    score
}

