        }
        // Perfect chaining: post_residual exactly fits next item
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Time horizon: early in the stream, prefer consolidating into existing bins;
    // late in the stream, be more willing to spread out / open fresh bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress;

    // Global pressure: many open bins with slack -> prefer filling existing ones.
    if open_bins_count > 1 {
        score += 0.05 * (open_bins_count as f64 - 1.0) * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 1.05 && fitting_bins_count <= 1;
        if next_item_size > 0 && post_residual >= next_item_size && poor_fit_elsewhere {
            score -= 18.0; // open fresh bin to host item + next item
