    // this bin is a perfect two-item chain — strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual - next_item_size < 10 {
            score -= 12.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Next item can't use this residue: dead-end penalty.
        score += 10.0 + post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
