pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when post_residual can host next_item_size exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight 2-step fits: perfect chain fit gets big subtraction.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // Bonus if this bin becomes exactly empty after two placements.
            if slack == 0.0 {
                score -= 25.0;
            }
        } else {
            // next item cannot chain here; penalize small dead space left behind
            let dead = post_residual as f64;
            if dead > 0.0 && dead < 10.0 {
                score += 30.0; // tiny unusable sliver
            } else if dead < 20.0 {
                score += 10.0;
            }
        }
    }

    // Reward tight single-step fits (small post residual relative to capacity)
    score -= 15.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize bins far from mean residual (prefer balanced residual pool),
    // but only mildly so tight fits above still dominate.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Late in the stream, prefer closing bins out: favor emptier bins less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: neutral baseline, chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
