    score += 0.5 * (open_bins_count as f64 / (1.0 + t)) * norm_item;

    // Mean residual deviation: prefer bins close to mean residual (smooth).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    score
}

