                score += 8.0 ;
            }
            // open a fresh bin when the item is large and only poor fits remain
            if item_size as f64 > cap * 0.6 && fitting_bins_count > 0 {
                let worst_gap = fitting_bins_count as f64 ;
                if worst_gap <= 2.0 {
                    score -= 9.0 ;
                }
            }
            // early stream: fresh bins keep residual variance low for future fits
            if progress < 0.15 && item_size as f64 > mr {
                score -= 3.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which "denomination band" does the
    // post-residual fall into? Small residuals in {0,1..5} are near-perfect fills.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fill is gold
    } else if pr <= 5 {
        score -= 18.0;
    } else if pr <= 10 {
        score -= 8.0;
    } else if pr <= 20 {
        score -= 2.0;
    } else if pr <= 30 {
        score += 4.0;
    } else if pr <= 50 {
        score += 10.0;
    } else {
        score += 16.0;
    }

    // Integer-division harmonic classes: leftover divisible into common item
    // denominations (10/20/25/50) is reusable dead-space-avoidance.
    if pr > 0 {
        let reusable = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0) || (pr % 50 == 0);
        if reusable { score -= 6.0; }
        // leftover that cannot hold even the smallest item is pure dead space
        if pr < 10 { score += 12.0; }
    }

    // Lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 && next_item_size <= bin_capacity {
        if next_item_size == pr {
            score -= 30.0; // perfect chain
        } else if pr >= next_item_size {
            score -= 10.0 * (pr as f64 / (next_item_size as f64 + 1.0)).min(2.0);
        } else {
            // next item won't fit here: penalize proportionally to wasted capacity
            let waste_frac = (pr as f64) / cap_f;
            score += 14.0 * waste_frac;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins would leave large ugly leftovers.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // baseline cost of a fresh bin, discounted slightly over time
        score = cap_f * 0.55 - 6.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            // big item followed by big item: a fresh bin can host the pair
            score -= 12.0;
        }
        if fitting_bins_count <= 1 {
            score += 30.0; // don't abandon the sole fitting bin
        }
    }

    // Mild tie-break: prefer fuller bins (small residual) and fewer open bins
    score += 0.05 * mean_residual;
    score += 0.3 * open_bins_count as f64;

    score
}

