pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit is strongly rewarded.
        score -= 80.0;
    } else {
        // Medium gaps that could still fit small future items are mildly rewarded.
        score -= 0.5 * (post_residual as f64).sqrt();
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements that leave a bin nearly empty of utility
    // when many bins are open; encourage filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // New-bin candidate: make empty bin moderately attractive only when the item
    // is large relative to residual alternatives; default slightly penalized.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

