    // good fits into open bins, but available when fits are terrible.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75;
        // If the next item exactly fills the current item's bin, opening new is fine
        if next_item_size > 0 && post_residual == 0 {
            score -= 5.0;
        }
        return score;
    }

    // Perfect closure reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a chained perfect fit -> strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // next item fits with some slack left; mild reward proportional to fit tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize by wasted amount
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
