                score -= 5.0 ;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // fresh bin leaves a full-capacity residual: strong long-term asset early on
            if progress < 0.55 && open_bins_count < 6 {
                score -= 6.0 ;
            }
        }
    }

    score
}

