    // Reward tight fits (small post-residual) more aggressively.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins relative to the fleet's mean residual.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Time horizon: early in the stream, be more willing to open new bins
    // (explore); late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it more as the stream progresses,
        // unless the current bin fit is very poor.
        score += 20.0 + 60.0 * progress;
        if post_residual as f64 > mean_residual {
            score -= 10.0; // a fresh bin keeps healthy residual
        }
    } else if progress < 0.3 {
        score -= 5.0; // mild exploration bonus early on
    }

    // Crowding: when many bins are open, favor consolidation.
    score += 0.3 * open_bins_count as f64;

    score
}

