    let norm_post = post / cap;

    // Smooth polynomial base: reward tight fits with a convex penalty on residual.
    let mut score = 4.0 * norm_post * norm_post - 2.0 * norm_post;

    // Non-linear coupling of residual with stream progress: early on, prefer
    // filling bins loosely; later, demand tighter fits (steeper convexity).
    let progress_coupling = (0.5 + progress) * norm_post * norm_post * cap;
    score += progress_coupling;

    // Dead-space penalty: residual too small to be useful for any plausible item,
    // scaled smoothly by how late in the stream we are.
    let dead_zone = (25.0 - post).max(0.0) / cap;
    score += 3.0 * dead_zone * dead_zone * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 2.0 + 1.5 * progress;
