    // Lookahead coupling: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 1.0 * (1.0 - slack * slack);
        } else {
            let over = (nxt - post) / cap;
            score += 1.5 * over * over;
        }
    }

    // Mild penalty when this bin's residual is far from the mean (imbalance),
    // damped smoothly by open bin count.
    let dev = (post - mean_residual) / cap;
    score += 0.5 * dev * dev * (open_bins_count as f64).ln_1p();

    // Slight preference to keep fewer bins open when early in the stream.
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    score
}

