pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality via modulo classes.
    // Residuals divisible by 10 are "harmonic" (likely reusable by typical items).
    let harm = post_residual % 10;
    score += (10 - harm) as f64 * 0.9; // penalize non-aligned residuals

    // Integer-division thresholds: classify post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 8.0; // roomy bin, keep using it
    } else if frac > 0.2 {
        score += 2.0; // mid zone, mild penalty
    } else if post_residual > 0 {
        score += 12.0; // sliver: near-dead space
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Does next item fit into post_residual? lookahead coupling
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
            // harmonic bonus if next item lands exactly
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else if next_item_size > 0 {
            // next item won't fit here: penalize based on wasted potential
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin logic
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0; // avoid opening a new bin if this is the only fit
    }

    // New-bin candidate: only attractive when residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.35 && open_bins_count > 2 {
            score += 5.0 + 10.0 * fragmentation; // prefer fresh bin when open bins are tight
        } else {
            score += 30.0 + 20.0 * (1.0 - progress); // early stream: reuse open bins
        }
    }

    // Slight preference for tightest existing bin among equals
    score += (bin_residual as f64 - post_residual as f64) * 0.01 * open_bins_count as f64;

    // Mean-residual coupling: penalize deviating far from fleet mean
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

