    // Gaps smaller than the minimum item size (1..=100 unknown, assume <10) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // heavy penalty for creating unusable slivers
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Tight-but-usable fit: post_residual just above small-item threshold.
    if post_residual >= 10 && post_residual <= 25 {
        score -= 12.0;
    }

    // --- Open bins pressure ---
    // Discourage spreading across many bins; favor filling existing ones.
    score += 0.6 * open_bins_count as f64;

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0; // if this is the only fitting open bin, use it
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current item leaves a huge
        // gap in every open bin, or when few bins are open.
        let gap_penalty = if post_residual < 10 { 60.0 } else { 0.0 };
        score += 20.0 + 2.0 * open_bins_count as f64 - gap_penalty;
        // If the next item could fill this fresh bin together with current one,
        // a new bin is appealing.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // --- Lookahead: penalize leaving a gap that fits next item poorly ---
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0; // leave room so next item fits tightly
        } else if post_residual < next_item_size && post_residual >= 10 {
            score += 5.0; // gap blocks next item
        }
    }

    // --- Mean residual coupling ---
    // Prefer bins with residual below the mean (denser bins) for tight packing.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    // --- Stream progression: late in stream, be more conservative ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

