            score -= 46.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 37.0 - 0.6 * slack ;
        } else {
            score -= 29.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 16.0 ;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 12.0 ;
        }
        if post_residual >= 2 * next_item_size && slack <= next_item_size as f64 + 3.0 {
            score -= 10.0 ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 7.0 ;
        }
        // mild reward for slack in the sweet band [1,6]
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0) ;
        }
        // NEW: penalize leaving residual far above mean (dead space accumulation)
        if pr > mean_residual * 2.2 && pr > 8.0 {
            score += 2.5 * (pr - mean_residual * 2.2) / cap * 20.0 ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        // tiny residuals the next item can't use: extra penalty
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        // NEW: near-miss bands — small gaps to next item are salvageable later
        if nxt - pr <= 6.0 && progress < 0.7 {
            score += 2.0 ;
        }
    }

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
