pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose residual falls into
    // "usable" classes (multiples of small denominators) are favored.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 25 == 0 {
        -9.0
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division threshold on post_residual: dead space too small for
    // the smallest plausible follow-up item is penalized.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (chained fit). If next item cannot fit at all,
    // mild penalty for wasting the slot.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin
    // would leave awkward residual relative to item size classes.
    if bin_residual == bin_capacity {
        // harmonic class of item size: items near capacity fractions
        // (e.g. >50% of C) pair well with a fresh bin.
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= 8.0;
        } else {
            score += 12.0;
        }
        // early stream: fewer open bins -> opening is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0 - open_bins_count as f64;
    } else {
        // Prefer tighter bins: scale by fullness
        let fullness = 1.0 - bin_residual as f64 / cap;
        score -= fullness * 8.0;
        // divergence from mean residual: bin far below mean residual is
        // a good target (it is nearly full)
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

