    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host typical future items (>= 10).
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Penalize bins whose residual is much larger than needed (wasteful use of big space).
    let waste = (bin_residual - item_size) as f64;
    score += 0.15 * waste;

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score += 0.4 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., this call is the empty-bin call and mean residual is small or fit is poor).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, softened if many bins open / large item.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If the item is large, a fresh bin is less costly.
        score -= 0.2 * item_size as f64;
        // If mean residual across open bins is large, prefer existing bins.
        score += 0.5 * mean_residual;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item would NOT fit here but would fit elsewhere, mild penalty for hogging space.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Slight early-stream preference for keeping bins tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (1.0 - progress);

    score
}

