        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mr * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 12.0 ;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0 ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 7.0 ;
        }
        // mild reward for slack in the sweet band [1,6]
        if slack >= 1.0 && slack <= 6.0 {
            score -= 3.0 * (1.0 - slack / 7.0) ;
        }
        // NEW: penalize leaving a residual that likely becomes dead space relative to stream mean
        if slack > 12.0 && pr < mr * 0.9 {
            score += 2.5 ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mr * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        // tiny residuals the next item can't use: extra penalty
        if pr < mr * 0.5 {
            score += 6.0 ;
        }
        // NEW: residual just below next item is a near-perfect trap; stronger penalty when rare alternatives
        if nxt - pr <= 3.0 && fitting_bins_count <= 2 {
            score += 5.0 ;
        }
    }

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        // near-miss: next item barely doesn't fit, mild penalty
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0 ;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mr * 0.8 {
            score += 3.0 ;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
