            // late stage: avoid opening a bin whose leftover can't host next item
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // NEW: fresh-bin leftover after placement should be a usable host for the next item
            if nxt > 0.0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
                score -= 4.0 ;
            }
            // NEW: many open bins with healthy residuals make new bins less attractive
            if open_bins_count > 4 && fitting_bins_count > 0 {
                score += 3.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest plausible
    // follow-up item are "dead" — penalize them heavily.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual as f64) * 8.0;
    }

    // Non-linear penalty on medium gaps that few typical items can use.
    if post_residual > 0 && post_residual < 40 {
        score += (40 - post_residual) as f64 * 0.8;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage consolidating into existing residual space.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure; acceptable only if
        // no existing bin offers a good fit.
        score += 25.0 + 10.0 * pressure;
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Reward filling bins that already carry large residual (consolidation).
        let gap = (mean_residual - bin_residual as f64).abs();
        score -= 3.0 * pressure;
        score += gap * 0.15;
    }

    // Lookahead synergy: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score += 5.0; // mildly prefer leaving room shaped for nothing specific
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Early in stream: keep flexibility, mild penalty for very low residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && post_residual > 0 && post_residual < 20 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

