    let stranded = if pr > 0.0 && pr < min_item { 1.0 } else { 0.0 } ;

    if post_residual == 0 {
        score -= 60.0 ;
    } else if post_residual <= 2 {
        score -= 28.0 ;
    } else if post_residual <= 5 {
        score -= 13.0 ;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64 ;
        score += 42.0 + 3.2 * gap * gap ;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0) ;
        score += 4.0 + 0.8 * excess ;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        if slack < 5.0 {
            score -= 46.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 37.0 - 0.6 * slack ;
        } else {
            score -= 29.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 16.0 ;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 12.0 ;
        }
        // two-item lookahead: reward residuals that fit next item twice tightly
        if post_residual >= 2 * next_item_size && slack <= next_item_size as f64 + 3.0 {
