            // fresh bin is extra attractive when item is large relative to mean residual
            if item_size as f64 > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            // large item with few alternatives: prefer a fresh bin
            if item_size as f64 > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            // late stage: avoid opening a bin whose leftover can't host next item
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: post residual, with non-linear penalty on tiny dead space
    let mut score = pr;
    // Quadratic/cubic coupling of residual with stream progress:
    // late in the stream, small residuals are more acceptable (bins are closing out),
    // early on, large residual waste is penalized more.
    let progress_term = progress * (1.0 - progress) * 4.0; // peaks at 1 mid-stream
    score += fit_norm * fit_norm * cap * (1.0 - progress) * 0.35;
    score -= fit_norm * fit_norm * fit_norm * cap * progress * 0.25;

    // Reward tight fits (small post_residual) non-linearly
    if post_residual <= item_size {
        score -= 6.0 + 4.0 * (1.0 - fit_norm);
    }

    // Last-chance bin: strong smooth reward scaled by how full it becomes
    if fitting_bins_count == 1 {
        score -= 5.0 + 8.0 * (1.0 - fit_norm) * (1.0 - fit_norm);
    }

    // Lookahead: if next item fits in post_residual, reward; smooth coupling
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 3.0 * (1.0 - nx / cap) * (1.0 + progress);
        } else {
            score += 2.0 * (nx - pr) / cap * 10.0 * (1.0 - progress);
        }
    }

    // Penalize spreading across many open bins mildly, coupled with mean residual
    score += (open_bins_count as f64).ln().max(0.0) * 0.4;
    score += (mean_residual - pr).abs() * 0.05;

    // New-bin candidate: empty bin has full residual; penalize slightly unless
    // nothing else fits well (high post_residual is already costly).
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress);
    }

    score
}

