    // Residuals that are multiples of common item sizes (10/20/25/50) are
    // more likely to be filled later -> reward them (subtract).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity used by this placement
    let fill = (bin_capacity - post_residual) as f64 / cap;

    // Harmonic classes on post_residual via integer division thresholds
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class_bonus = match post_residual {
        0 => -30.0,                              // perfect fit
        p if p % 10 == 0 => -6.0,                // decade-aligned residual
        p if p % 25 == 0 => -5.0,
        p if p < eighth => 8.0,                  // tiny dead space
        p if p < quarter => 3.0,                 // small residual
        p if p > 3 * quarter => -4.0,            // large residual, very usable
        _ => 0.0,
    };
    score += class_bonus as f64;

