    // if the next item fits exactly or well in the post residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size;
        if nx <= post_residual {
            let slack = post_residual - nx;
            if slack == 0 {
                score -= 12.0;                   // next item perfect fit
            } else if slack % 10 == 0 {
                score -= 5.0;
            } else if slack < eighth {
                score += 4.0;                    // would leave tiny space after next
            }
        } else {
            // next item won't fit here; penalize slightly less if residual is generic
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // Reward high fill ratio, scaled by stream progression
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * fill * (0.5 + 0.5 * progress);

    // Prefer tighter bins relative to mean residual
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        // base cost of opening a bin; offset by how bad alternatives look
        score += 18.0 - 12.0 * fill;
        if post_residual as f64 > 0.6 * cap {
            score -= 10.0; // big item, new bin is natural
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 5.0;
        }
    }

    // Small tie-break noise via deterministic harmonic term
    score += ((step_index % 7) as f64) * 0.01;

    score
}

