}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can't fit even the smallest
    // plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small gaps only usable by tiny items: mild-to-strong penalty.
        score += 20.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    } else {
        // Reward larger usable residuals slightly super-linearly.
        score -= 0.15 * (post_residual as f64 - 20.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading into new bins,
    // favor consolidating into already-open ones.
    score += 0.8 * open_bins_count as f64;

    // If this bin is the brand-new empty candidate, penalize it more when
    // open-bin count is already high; allow it early or when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() <= 1.0 {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
        // Next item won't fit here anyway; residual is effectively dead space
        // for the near future — penalize moderately.
        score += 0.3 * post_residual as f64;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's the "tightest" bin — prefer filling tight bins first.
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Progress: later in the stream, be slightly more conservative about
    // dead space (fewer chances to recover).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

