        if slack == 0.0 {
            score -= 12.0 ;
        }
        // two-item lookahead: reward residuals that fit next item twice tightly
        if post_residual >= 2 * next_item_size && slack <= next_item_size as f64 + 3.0 {
            score -= 10.0 ;
        }
        // triple-fit potential with tight second slack
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 7.0 ;
        }
        // sweet band [1,6]: leftover after next item still highly reusable
