}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: raw post-residual (lower is better fit)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes increasingly costly (superlinear penalty)
    let dead_penalty = norm_pr.powi(2) * (1.0 + 3.0 * progress) * cap * 0.5;
    // but extremely tight fits (tiny post_residual) are rewarded more strongly as stream progresses
    let tight_bonus = (1.0 - norm_pr).powi(3) * cap * (0.15 + 0.45 * progress);

    score += dead_penalty;
    score -= tight_bonus;

    // Lookahead: reward residual that still accommodates the next item smoothly
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = (post_residual - next_item_size) as f64 / cap;
        score -= (1.0 - fit_quality).powi(2) * cap * 0.25;
    } else if next_item_size > 0 {
        // post-residual cannot host next item: penalize proportionally to wasted potential
        score += (next_item_size as f64 - pr).max(0.0) * (0.3 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * 0.6;
    }

    // Compare against mean residual: bins far below mean residual are "loose" targets;
    // slight reward for consolidating into below-mean-residual bins late in stream
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += dev * cap * (0.1 + 0.2 * progress);

    // New-bin candidate: make empty bins mildly unattractive early, more acceptable late
    if bin_residual == bin_capacity {
        score += cap * (0.4 - 0.25 * progress);
    }

    score
}

