pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in "usable" classes (>= ~1/4 of
    // capacity) remain attractive to future items; tiny leftovers are dead space.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // 0..=8 harmonic class

    match class {
        0 => score -= 6.0,                    // 0 leftover: perfect fit, reward heavily
        1 => score += 14.0,                   // tiny sliver: dead space, penalize hard
        2 => score += 8.0,                    // still poor
        3 => score += 2.0,                    // marginal
        _ => {}                               // >= 3/8 capacity left: fine
    }

    // Modulo-style coupling: does the leftover pair well with the lookahead item?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Exact fit with next item -> strong reward; near-fit -> mild reward.
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 10.0;
        } else if gap <= eighth {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this leftover at all: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual < eighth {
            score -= 6.0; // even a sliver fit beats wasting a fresh bin
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it moderately attractive so it wins when open bins fit poorly,
    // but not so attractive that it wins over decent fits.
    if bin_residual == bin_capacity {
        score = post_residual as f64 - 5.0;
        // Late in the stream, prefer consolidating into open bins a bit more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
        // Many open bins with slack -> discourage opening yet another.
        if mean_residual > quarter as f64 && open_bins_count > 2 {
            score += 4.0;
        }
    }

    // Mild preference for filling fuller bins overall (tight packing).
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

