            if item_size as f64 > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            // large item with few alternatives: prefer a fresh bin
            if item_size as f64 > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            // late stage: avoid opening a bin whose leftover can't host next item
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // fresh-bin leftover quality: a new bin is only worth it if its
            // eventual leftover (cap - item) is large enough to stay reusable
            let fresh_left = cap - item_size as f64 ;
            if fresh_left > 0.0 && nxt > 0.0 && fresh_left < nxt as f64
                && fitting_bins_count > 0 {
                score += 6.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling: dead space penalized super-linearly,
    // with intensity growing over stream progress.
    let x = post / cap; // normalized post residual in [0,1)
    let poly = x * x * (1.0 + 1.5 * progress) + 0.5 * x * progress;

    // Base score: super-linear dead-space penalty.
    let mut score = cap * poly;

    // Reward tight fits: small post residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        let fit_quality = next_item_size as f64 / post.max(1.0);
        score -= 8.0 * fit_quality * (1.0 + progress);
    } else if next_item_size > 0 {
        // Post residual likely dead space for next item: penalize smoothly.
        score += 4.0 * (1.0 - post / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, more early in stream, less if open bins are fragmented.
    let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - progress) - 15.0 * fragmentation;
    }

    // Slight preference to keep bins balanced early, consolidate late.
    score += (mean_residual - post) * (0.3 - 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
