pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: divide capacity into 8 classes.
    let class = (post_residual * 8 / bin_capacity.max(1)) as i64;
    // Dead-space classes: residuals that cannot fit even the smallest plausible item.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual < 5 {
        score += 25.0; // tiny unusable sliver
    } else {
        // Reward residuals that exactly fit a "harmonic" fraction of capacity
        // (e.g. 50, 25, 20, 10, 33/34, 12) which pair well with common item sizes.
        let harmonic = post_residual == bin_capacity / 2
            || post_residual == bin_capacity / 4
            || post_residual == bin_capacity / 5
            || post_residual == bin_capacity / 10
            || post_residual == bin_capacity / 3
            || post_residual == bin_capacity / 8;
        if harmonic { score -= 18.0; }
        // Modulo classes: residuals near multiples of 25 are structurally useful.
        let m = post_residual % 25;
        if m == 0 { score -= 10.0; }
        else if m <= 5 { score += 6.0; }
        else if m >= 20 { score += 4.0; }
        // Integer-division threshold: mid-range leftovers are the worst.
        if class >= 3 && class <= 5 { score += 12.0; }
    }

    // Next-item lookahead: post_residual should accommodate next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 { score -= 30.0; }        // chains perfectly
            else if slack < 5 { score -= 12.0; }    // near-perfect chain
            else { score += slack as f64 * 0.15; }  // leftover after chain
        } else {
            // This bin becomes dead after this placement; penalize by gap size.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // If many open bins already, discourage more.
        score += open_bins_count as f64 * 1.5;
    }

    // Prefer bins below mean residual (fill emptier bins first when equal),
    // but only mildly so tight-fit logic dominates.
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

