    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && pr > mean * 2.0 {
                score -= 7.0 ;
            }
            if item_size as f64 > mean * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            if item_size as f64 > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // new-bin residual after placement is (cap - item): prefer sizes leaving compactable leftovers
            let new_pr = cap - item_size as f64 ;
            if new_pr > 0.0 && nxt > 0.0 {
                let nslack = new_pr - nxt ;
                if nslack >= 0.0 && nslack <= 6.0 {
                    score -= 6.0 ;
                } else if nslack > 0.0 && nslack < nxt {
                    score += 4.0 ;
                }
            }
            // mid-stream: opening bins is cheap while many items remain
            if progress < 0.45 && total_items > step_index + open_bins_count * 2 {
                score -= 3.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
