pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match between post_residual and next item
    let pr = post_residual as f64;
    let ns = next_item_size as f64;
    if next_item_size > 0 {
        let diff = (pr - ns).abs();
        // exact match: big reward
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // graded penalty for mismatch, tighter when next item barely fits
            score += diff * 0.8;
            // next item fits exactly into post-residual region => reward proximity
            if ns <= pr {
                score -= (pr - ns) * 0.15;
            } else {
                // next item won't fit here: leftover is dead-ish space, penalize
                score += (ns - pr) * 0.3;
            }
        }
    } else {
        // last item: just minimize leftover
        score -= 20.0;
    }

    // Reward tight fits relative to capacity
    score += (item_size as f64 / bin_capacity as f64) * 5.0;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins below mean residual (keeps residuals balanced)
    score += (pr - mean_residual) * 0.25;

    // New-bin candidate: penalize opening a new bin unless current residuals are all bad
    if bin_residual == bin_capacity {
        score += 25.0;
        // if next item is large and no bin fits well, opening may be fine
        if next_item_size > 0 && (pr - ns).abs() < 1.0 {
            score -= 30.0;
        }
        // early stream: allow more bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Slight preference for fewer open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
