    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.8 * excess;
    }

    // Lookahead: reward placements that leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = pr - nxt;
        if slack < 5.0 {
            score -= 44.0 - 1.5 * slack;
        } else if slack < 12.0 {
