        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
    }

    // Last-chance bonus: only one bin fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // New-bin candidate handling.
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
