    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: penalize leaving a residual that barely fails the next item,
    // reward leaving a residual that exactly accommodates it.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 25.0; // chains perfectly
        } else if gap < 0 && gap > -10 {
            score += 12.0; // near-miss dead space
        } else if gap > 0 && gap < 10 {
            score += 4.0; // small unusable sliver
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless it's genuinely needed.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_penalty = 30.0;
        // More open bins with low mean residual => opening new bins is wasteful.
        if open_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            new_penalty += 15.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        new_penalty += 20.0 * progress;
        // If this bin is the only fitting option, soften the penalty.
        if fitting_bins_count == 0 {
            new_penalty -= 35.0;
        }
        score += new_penalty;
    }

    // Mild preference for filling bins that are already relatively full.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

