pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with a non-linear (quartic) dead-space curve
    let mut score = norm_pr * norm_pr * norm_pr * norm_pr * cap;

    // Tight fits rewarded: smooth coupling of fill fraction squared
    let fill = 1.0 - norm_pr;
    score -= 40.0 * fill * fill;

    // Stream-progress coupling: early on, tolerate slack (keep bins flexible);
    // later, squeeze residual harder via polynomial interaction
    let slack_penalty = (1.0 + 3.0 * progress * progress) * norm_pr * cap * 0.5;
    score += slack_penalty;

    // Interaction: post_residual vs mean_residual — avoid bins far from fleet mean
    let dev = (pr as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * fill;
    }

    // Lookahead: reward if next item fits the post-residual (smooth compatibility term)
    if next_item_size > 0 {
        let compat = (next_item_size as f64 / cap - norm_pr).abs();
        score += 15.0 * compat * compat;
        if (next_item_size as f64) <= pr {
            score -= 10.0;
        }
    }

    // New-bin candidate: must look unattractive unless residual waste is severe
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.4 * progress) + 30.0 * (1.0 - fit_ratio);
        if fitting_bins_count <= 1 {
            score -= 60.0; // opening new bin is fine when nothing else fits well
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
