pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic classes of post_residual (integer division by capacity fractions).
    // Class 0: unusable dead space (< smallest plausible item) -> heavy penalty.
    // Class 1..: progressively better.
    let class = (post_residual / 10).min(10) as f64;
    score -= class * 3.0;

    // Dead space: residual too small for anything useful.
    if post_residual < 10 {
        score += 120.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 60.0;
            // modulo harmony: next item leaves another perfect small class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 40.0;
            }
        } else {
            // next item won't fit here; slightly penalize leaving mid-range gap
            score += 15.0;
        }
    }

    // Last chance bin: must use it or open a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate handling: empty bin gets neutral baseline; prefer it
    // only when this placement into an existing bin would be very wasteful.
    if bin_residual == bin_capacity {
        // baseline for fresh bin: cost of consuming 100 - item
        score = (bin_capacity - item_size) as f64 + 5.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative
        }
        if post_residual < 10 && item_size < 20 {
            score += 50.0; // avoid opening bins for tiny items
        }
    }

    // Prefer bins below mean residual (tighter bins first, best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Early stream: be slightly conservative about fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

