            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // NEW: fresh bin whose post residual is a clean multiple of next item is very attractive
            if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= next_item_size {
                score -= 6.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residual space into capacity eighths
    let post = post_residual;
    let eighth = bin_capacity / 8;
    let class = post / eighth.max(1); // 0..=8 integer class
    // Dead-space penalty: residuals that cannot plausibly fit another item (1..100) are bad
    if post < 10 && post > 0 {
        score += 60.0; // unusable sliver
    }

    // Reward exact harmonic alignment: post_residual divisible by common item sizes
    let harmonic: [u32; 8] = [10, 20, 25, 40, 50, 60, 75, 80];
    let mut best_align = 0.0;
    for h in harmonic.iter() {
        if *h <= post {
            let r = post % h;
            let align = 1.0 - (r as f64) / (h as f64);
            if align > best_align {
                best_align = align;
            }
        }
    }
    score -= 12.0 * best_align;

    // Class-based shaping: mid classes (3..=5) are the most valuable leftover zones
    match class {
        0 => score += 25.0,           // nearly full: excellent, but tiny residual risk handled above
        1 => score -= 20.0,
        2 => score -= 10.0,
        3 | 4 => score -= 18.0,       // sweet spot: fits half-items later
        5 => score -= 6.0,
        6 => score += 8.0,
        _ => score += 0.0,            // near-empty bin: neutral (new-bin case lives here)
    }

    // New-bin candidate handling: empty bin gets a moderate default score,
    // but is favored when no open bin fits well (last-chance logic)
    if bin_residual == bin_capacity {
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing next big item into fresh bin is fine
        }
    } else {
        // Penalize using the last fitting bin unless the fit is tight
        if fitting_bins_count == 1 {
            let tightness = 1.0 - (post as f64) / cap;
            score -= 30.0 * (1.0 - tightness); // tight fit -> strong reward
        }
        // Prefer bins whose residual is close to the item (tight packing)
        let slack = (bin_residual - item_size) as f64;
        score += 0.15 * slack * slack / cap;

        // Lookahead: reward if next item exactly fills the post residual
        if next_item_size > 0 {
            if next_item_size == post {
                score -= 45.0;
            } else if next_item_size < post {
                score -= 0.2 * (post - next_item_size) as f64;
            } else {
                score += 0.1 * (next_item_size - post) as f64;
            }
        }

        // Spread pressure: avoid concentrating residual far from mean
        let dev = (bin_residual as f64) - mean_residual;
        score += 0.05 * dev.abs();

        // Late stream: consolidate into fewer bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress * (post as f64 / cap);
    }

    score
}

