pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Larger usable gaps: mild reward proportional to future usability.
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 80.0;
        } else if slack < 10.0 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap left that cannot host next item: penalize dead space.
        score += (post_residual as f64) * 1.5;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += 15.0 + open_pressure * 4.0;
        // But if no existing bin fits well, new bin may be justified.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: reward more when many bins are open.
        score -= open_pressure * 2.0;
    }

    // Last-chance bin: strongly favor using the final fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Early stream: slightly more willing to open bins; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    } else {
        score += progress * 5.0;
    }

    score
}

