pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits via squared residual penalty.
    score += (post_residual as f64) * (post_residual as f64) / (2.0 * cap);

    // Harmonic classes of post_residual: classify leftover space into
    // capacity-fraction buckets and penalize "dead zone" classes.
    // Classes: (0,10], (10,25], (25,50], (50,100).
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -40.0 // perfect fit, strongly favored
    } else if pr <= 10 {
        -12.0 // near-perfect: likely unusable but tiny waste
    } else if pr <= 25 {
        8.0 // awkward dead space
    } else if pr <= 50 {
        0.0 // mid-range: reusable for medium items
    } else {
        15.0 // large leftover wasted on a small item
    };
    score += class_penalty;

    // Integer-division harmonic ladder on post_residual / 10:
    // each rung of leftover above the smallest useful class adds cost.
    score += ((pr / 10) as f64) * 1.5;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chain fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after chaining matters
            let chain_left = pr - next_item_size;
            score += (chain_left as f64) / cap * 10.0 - 5.0;
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral baseline, but prefer it when the
    // item would leave an awkward class in an existing bin.
    if bin_residual == bin_capacity {
        score = 45.0 + (item_size as f64) * 0.1;
        if class_penalty > 0.0 {
            score -= class_penalty * 2.0; // new bin beats creating dead space
        }
        if fitting_bins_count == 1 {
            score += 25.0; // don't abandon the last fitting bin lightly
        }
    }

    // Mild consolidation pressure: fewer open bins is better late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * progress * 0.3;

    // Nudge toward bins with residual close to mean (balanced packing).
    score -= (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

