pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Residuals below the smallest conceivable useful item are "dead space".
    // Penalize them super-linearly so the search strongly avoids creating them.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Near-perfect fit (gap smaller than any possible item) still excellent.
    else if post_residual <= 5 {
        score -= 25.0;
    }

    // --- Coupling with next item lookahead ---
    // If the next item fits exactly into the post-residual, strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item does NOT fit and post_residual is small-but-nonzero,
    // this bin becomes a dead end: penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + post_residual as f64 * 0.3;
    }

    // --- Last-chance pressure ---
    // If this is the only bin that fits the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    // A brand-new empty bin is only attractive if the current item is large
    // (poor fit elsewhere) or no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced for large items.
        score = (bin_capacity - item_size) as f64 + 20.0;
        if item_size >= 60 {
            score -= 15.0;
        }
        // As the stream progresses, be more willing to open new bins
        // to keep residual diversity high.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 * fitting_bins_count as f64;
        }
    }

    // --- Open-bin pressure: mild penalty for spreading across many bins ---
    // Prefer filling existing bins when the fit is decent.
    score += open_bins_count as f64 * 0.4 * (post_residual as f64 / bin_capacity as f64);

    // --- Mean residual alignment ---
    // Favor bins whose residual is below average (they are "nearly full",
    // close them out), penalize bins with excess slack relative to the mean.
    let res = post_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - res) * 0.15;
    }

    score
}

