                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item_size as f64 > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            if item_size as f64 > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // NEW: open fresh bin when remaining open bins are all near-miss for the next item
            if fitting_bins_count > 0 && nxt > 0.0 {
                let all_tight = fitting_bins_count <= 2 && item_size as f64 > cap * 0.25 ;
                if all_tight {
                    score -= 3.0 ;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "harmonically useful"
    // (small, or aligned with common size classes via modulo arithmetic).
    let pr = post_residual as u32;
    let residue_class = pr % 10;
    if pr == 0 {
        score -= 50.0; // perfect fit: excellent
    } else if pr <= 10 {
        score -= 15.0; // near-perfect, dead space minimal
    } else {
        // penalize residuals in awkward classes (1,2,3 -> unusable slivers)
        if residue_class <= 3 {
            score += 20.0;
        } else if residue_class == 0 {
            score -= 5.0; // multiples of 10 are reusable
        }
        // integer-division threshold: residual in [11..30] is semi-useful
        if pr / 10 >= 1 && pr / 10 <= 3 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let npr = pr - next_item_size;
            score -= 5.0;
            if npr % 10 == 0 || npr <= 5 {
                score -= 10.0;
            } else if npr % 10 <= 3 {
                score += 5.0;
            }
        } else {
            score += 8.0; // next item won't fit here; this bin may become dead
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we prefer
    // existing bins unless the fit is poor or no bin exists.
    if bin_residual == bin_capacity {
        score += 10.0;
        // but if many bins are open and mean residual is high, opening fresh is fine
        if open_bins_count > 0 && mean_residual > cap * 0.45 {
            score -= 15.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // prefer fuller bins: reward closeness of fill ratio to 1
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= 10.0 * fill;
    }

    // Stream progression: later in the stream, be greedier (prefer tight fits,
    // discourage opening new bins since fewer items remain to fill them).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    // Slight preference for bins below mean residual (balancing load).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
