    let is_new_bin = bin_residual == bin_capacity;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item_size as f64 { 1.0 } else { 0.0 };

    // Perfect fit: strongly favor exact fills.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 16 {
        score += 3.0 + 0.8 * (16.0 - pr);
    }

    // 2-step lookahead around next item fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 45.0;
        } else if slack < 5.0 {
            score -= 40.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 32.0 - 0.6 * slack;
        } else {
            score -= 25.0 - 0.15 * slack;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
            if slack <= next_item_size as f64 + 3.0 {
                score -= 8.0;
            }
        }
        if slack >= 1.0 && slack <= 6.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 15.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 18.0 + 0.25 * (nxt - pr);
        if nxt - pr <= 3.0 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 8.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
    }

    // Relative-to-mean coupling: keep residuals balanced.
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    if post_residual > 0 {
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
    }

    // Last-chance bin: avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && !is_new_bin {
        score -= 55.0;
    }

    // New-bin candidate logic.
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size
