            if fitting_bins_count > 0 && mean_residual > 0.0 {
                let worst_case = item_size as f64 + mean_residual ;
                if worst_case > cap * 0.95 && progress < 0.7 {
                    score -= 6.0 ;
                }
            }
            // many open bins with large residuals — discourage adding another
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a perfect chain fit
    // (item now + next item exactly fills the bin).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Post residual can host the next item: mild reward proportional to tightness.
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * tightness;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual cannot host the next item: penalize dead space, worse
        // when the leftover is small-but-unusable.
        let dead = post_residual as f64;
        score += 0.5 * dead * (1.0 - dead / bin_capacity as f64);
    }

    // Compare post_residual against mean residual of open bins:
    // leaving less than average keeps bins tight and balanced.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist, but relax as the
    // stream progresses and open-bin count grows (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 10.0 * progress;
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 15.0;
        }
    }

    // Mild reward for very tight placements overall.
    score -= 0.2 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
