    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (item barely fits open bins) or late in the stream with many bins.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let pressure = (fitting_bins_count as f64).max(0.0) / (open_bins_count as f64).max(1.0);
        score += 45.0
            - 20.0 * fit_ratio
            - 10.0 * progress
            + 15.0 * pressure.min(1.0);
    } else {
        // Mild penalty when this bin's residual is far from the mean residual
        // (keeps residual profile homogeneous for future items).
        let dev = (bin_residual as f64 - mean_residual).abs();
