        score += 0.5 * gap * (1.0 - usable);
    } else {
        score -= 5.0 * norm_pr; // last item: prefer filling bins fully
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
