    score += 0.3 * (open_bins_count as f64).sqrt() * (mean_residual / cap);

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - norm_item) * (0.5 + 0.5 * (1.0 - progress));
