        } else {
            score += 25.0; // next item won't fit here; residual likely wasted
        }
        // Harmonic check: does post_residual divide/align with next item size?
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 30.0;
        }
    }

