    // New-bin candidate logic: an empty bin is a fallback; penalize it mildly so
    // decent fits in open bins win, but allow it when open-bin fits are bad.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.15 * open_bins_count as f64 + 0.3 * mean_residual;
        // If item is large relative to capacity, opening fresh is more attractive.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
