        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        // Near-miss gradient softened when many alternatives exist.
        if nxt - pr <= 2.0 && fitting_bins_count >= 3 {
            score -= 3.0;
        }
        // Near-miss salvage — when the miss is tiny and the item still
        // fits another bin comfortably, a near-miss residual is tolerable;
        // when alternatives are scarce, it is a costly strand.
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        // REFINED: near-miss salvage gradient — grade the salvage by miss size
        // and stream position rather than a flat flip, so tiny misses late in
        // the stream are treated as acceptable waste.
        if nxt - pr > 3.0 && nxt - pr <= 6.0 && progress > 0.5 && fitting_bins_count >= 2 {
