        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        // Residual-density control: residuals hovering near the mean are likeliest to strand.
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        // Global dead-space ratio penalty, sharpened late in the stream.
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        // Stranded-void gradient — residuals just below the next item size
        // are the costliest dead space; penalize proportionally to how close
        // the miss is, strongest when few alternative hosts exist.
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        // Endgame exactness — residuals that cannot host the next item
        // but are tiny (<= 4) are nearly-free waste; reward them late so the
        // packer stops chasing marginal fits and preserves bigger residuals.
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        // REFINED: dead-space budget coupling — when the aggregate dead space
        // implied by the mean residual is already low, tolerate slightly
        // larger leftovers; when it is high, push harder against them.
        if mean_residual > 0.0 && waste_ratio > 0.2 && pr > mean_residual {
            score += 2.5 * (pr - mean_residual) / mean_residual.max(1.0) * (0.5 + progress);
        }
    }

    // New-bin candidate handling.
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item_size as f64 > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item_size as f64 > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress < 0.5 && item_size as f64 > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            // Mid-stream fresh-bin brake: several open bins fit but none tightly —
            // opening a new bin rarely pays unless the item is large.
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item_size as f64 <= cap * 0.35 {
                score += 9.0;
            }
            // Fresh-bin pull when the item nearly exhausts a fresh bin and
            // existing fits would strand more dead space than the new bin would.
            if fitting_bins_count > 0 && item_size as f64 >= cap * 0.85 {
                score -= 6.0;
            }
