        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0) ;
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0) ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64 ;
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0)) ;
        }
        // refined: penalize slack that lands in the "dead band" just below nxt,
        // i.e. residual after hosting next item would be too small for anything else
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt ;
            score += 5.0 * band * band * (0.5 + progress) ;
        }
        // gen60: the residual left AFTER placing the next item may itself be a
        // dead band for the item after that; approximate with mean_residual as
        // a proxy for typical follow-up item size.
        if slack > 0.0 && mean_residual > 0.0 && slack < mean_residual * 0.45 {
            let band2 = 1.0 - slack / (mean_residual * 0.45) ;
            score += 3.0 * band2 * band2 * (0.4 + progress) ;
        }
