        if nxt - pr <= 1.0 {
            score += 6.0 ;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 } ;
        }
        // gen60: if this residual cannot host nxt but the gap is small, and the
        // item could still be split across another bin cheaply, soften penalty
        // when many bins fit and the gap is exactly 1-2 units (near-miss).
