            score -= 4.0 ;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0 ;
        }
        // gen60: near-endgame, residuals that can still host the next item are
        // precious; deepen the existing discount when few bins remain fitting.
        if progress > 0.8 && nxt > 0.0 && pr >= nxt && fitting_bins_count <= 2 {
            score -= 5.0 * (1.0 - (pr - nxt).min(10.0) / 10.0) ;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
