            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 } ;
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt) ;
        }
        // refined: residuals just below the next item that could still hold a
        // plausible smaller follow-up (>= mean_residual * 0.5) are less dead
        if pr >= mean_residual * 0.5 && nxt - pr <= 8.0 {
            score -= 3.5 * (1.0 - (nxt - pr) / 8.0) ;
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64 ;
    score -= 6.0 * fit_ratio ;
    score += 0.3 * open_bins_count as f64 * (pr / cap) ;

