            // strand more than half its space after this item — dead-space
            // avoidance is worth a new bin at any stage
            if fitting_bins_count > 0 && pr > item * 2.0 && pr > nxt.max(1.0) * 1.5 {
                score -= 5.0 ;
            }
        }
    }

    score
}

