            // fitting residual would leave a sub-mean dead sliver
            if fitting_bins_count > 0 && item > cap * 0.5
                && mean_residual > 0.0 && mean_residual < nxt.max(1.0) {
                score -= 4.0 * (1.0 - progress) ;
            }
        }
    }

    score
}

