            // third of their space early in the stream.
            if fitting_bins_count > 0 && progress < 0.45 && mean_residual > cap * 0.45
                && item < mean_residual * 0.5 {
                score -= 3.0;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
