            score += (0.25 + 0.2 * progress) * (slack - 12.0) ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64 ;
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0)) ;
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt ;
            score += 5.0 * band * band * (0.5 + progress) ;
        }
        // refined: reward bins whose post-fit residual is exactly reusable for the
        // next item AND leaves no dead void — tight two-step chains
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress) ;
        }
        // refined: discourage placing into a bin whose remaining slack after next
        // item is a "prime dead zone" (small but unusable for typical items)
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress) ;
        }
        // new: two-step lookahead — prefer bins where residual after placing item
        // AND next item stays a multiple-like fit for the following flow
        if slack >= nxt && (slack - nxt) <= 2.0 {
            score -= 9.0 * (1.0 + progress * 0.5) ;
        }
        // new: avoid leaving a residual that is just below the mean usable size
        if slack > 0.0 && mean_residual > 0.0 && slack < mean_residual * 0.35 && slack > 4.0 {
            score += 3.0 * (1.0 - slack / (mean_residual * 0.35)) ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0 ;
        }
        if nxt - pr <= 1.0 {
            score += 6.0 ;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 } ;
        }
        // refined: a residual that just misses the next item but is large enough
        // to hold a scaled variant is less dead than a tiny residual
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt) ;
        }
        // new: a residual just missing the next item by 1-2 units may become
        // usable if the next-next item is smaller — soften the penalty slightly
        if nxt - pr <= 2.0 && progress > 0.5 && fitting_bins_count <= 3 {
            score -= 3.5 ;
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64 ;
    score -= 6.0 * fit_ratio ;
    score += 0.3 * open_bins_count as f64 * (pr / cap) ;

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0 ;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0 ;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap) ;
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0 ;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress) ;
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3) ;
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0 ;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 } ;
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0) ;
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0 ;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0 ;
        }
        // refined: dead-space targeting — residuals in the 7..15 band waste the
        // most area across long streams; penalize proportionally to progress
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8 ;
        }
        // refined: near-perfect fits (residual within 3 of item size) are gold —
        // deepen the reward as the stream matures
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5) ;
        }
        // new: mid-band residual (16..24) after a fit is still large enough to
        // hold typical items — mild reward scaled by how far above the mean it sits
        if pr >= 16.0 && pr < 24.0 && mean_residual > 0.0 {
            score -= 2.0 * ((pr / mean_residual).min(2.0) - 1.0).max(0.0) ;
        }
        // new: when many bins are open, tighten preference for low post-residuals
        // to consolidate rather than spread waste across bins
        if open_bins_count > 8 && post_residual > 0 {
            score += 0.15 * pr * (1.0 - progress) ;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress < 0.5 && item > mean_residual * 0.9 {
                score -= 4.0 ;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0 ;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0 ;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0 ;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0 ;
            }
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 {
                score -= 5.0 ;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5 ;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0 ;
            }
            // refined: open a fresh bin when every fitting residual would strand
            // more than a third of its space — early too, not just late
            if fitting_bins_count > 0 && progress < 0.45 && mean_residual > cap * 0.45
                && item < mean_residual * 0.5 {
                score -= 3.0 ;
            }
            // new: open a fresh bin when the item is large and the best fitting
            // residual would leave a stranded pocket larger than the next item
            if fitting_bins_count > 0 && nxt > 0.0 && item > cap * 0.55 {
                let best_fit_slack = mean_residual - item ;
                if best_fit_slack > nxt * 1.2 && best_fit_slack < nxt * 2.5 {
                    score -= 4.5 ;
                }
            }
            // new: avoid opening bins too eagerly when the stream is nearly done —
            // a partially-filled fresh bin at the tail is pure waste
            if progress > 0.9 && fitting_bins_count > 0 && item <= mean_residual {
                score += 6.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
