    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // next item can also fit here -> strong reward proportional to tightness
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit -> penalize leftover dead space
            score += 0.5 * gap;
        }
    }

    // Prefer bins with residual below mean (tighter bins first)
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.3 * mean_gap;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are badly fragmented
    if bin_residual == bin_capacity {
        let base = 30.0 + 0.5 * item_size as f64;
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        score += base + fragmentation;
    }

    // Late-stream consolidation: fewer open bins preferred as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    score
}

