pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post-residual (tight fit), with non-linear shaping.
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, waste tolerance is high; late, waste is penalized quadratically.
    let waste_weight = 0.5 + 2.5 * progress * progress;
    score += waste_weight * (post / cap) * (post / cap) * cap * 0.1;

    // Perfect fit reward (smooth, non-piecewise): strong cubic bonus near zero post-residual.
    let fit_frac = 1.0 - (post / cap);
    score -= 30.0 * fit_frac * fit_frac * fit_frac;

    // Penalize bins whose post-residual is just below the next item size (dead space),
    // smoothly weighted by how close the gap is.
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap < 0.0 {
            let severity = (-gap / cap).min(1.0);
            score += 15.0 * severity * severity * (0.3 + 0.7 * progress);
        } else {
            // Reward a bin that can also host the next item snugly.
            score -= 8.0 * (1.0 - gap / cap) * (1.0 - gap / cap) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (smooth in fitting_bins_count).
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 - post / cap);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0) * (post / cap);
    }

    // Mild preference toward fuller bins relative to the fleet average residual.
    score += 0.05 * (mean_residual - post).max(0.0) * (0.5 + progress);

    // New-bin candidate: make an empty bin attractive only when the item is large
    // or post-residual would be very small relative to capacity; otherwise penalize
    // opening new bins mildly, growing with stream progress and bin count.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score += 6.0 + 10.0 * progress + 0.5 * open_bins_count as f64 - 20.0 * large_item * large_item;
    }

    score
}

