                }
            }
            // NEW: late-stage new-bin restraint — fewer fresh bins when near the end
            if progress > 0.9 && fitting_bins_count > 0 && item <= mean_residual.max(1.0) {
                score += 10.0;
            }
        }
    }

    score
}

