            // multiple times exactly is a strong compaction play mid-stream.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.2 && progress < 0.8 {
                let fresh_left = bin_capacity - item_size.min(bin_capacity) ;
                if fresh_left >= 2 * next_item_size && fresh_left % next_item_size.max(1) == 0 {
                    score -= 4.0 * (1.0 - progress) ;
                }
            }
            // NEW: don't open a fresh bin when the item would leave the fresh bin
