                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // NEW: fresh-bin double-host promise — capacity minus item can host the next
            // item twice; strong pull, stronger when hosting bins are scarce.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) as f64 >= 2.0 * nxt {
                score -= if fitting_bins_count <= 2 { 4.0 } else { 1.5 } ;
            }
            // NEW: late-stream fresh-bin guard — refuse new bins near the end unless the
            // item is large enough that no open bin plausibly absorbs it.
            if progress > 0.9 && fitting_bins_count > 0 && item < cap * 0.5 {
                score += 10.0 ;
            }
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
