            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // NEW: fresh-bin that strands a residual exactly equal to next item is perfect — pull hard.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left == nxt {
                    score -= 8.0 ;
                } else if fresh_left >= nxt && fresh_left - nxt <= 4.0 && progress < 0.8 {
                    score -= 3.0 * (1.0 - (fresh_left - nxt) / 5.0) ;
                }
            }
            // NEW: opening fresh bins when mean residual is tiny wastes capacity — resist harder.
            if fitting_bins_count > 0 && mean_residual > 0.0 && mean_residual < nxt.max(1.0) * 0.5 && progress < 0.6 {
                score += 5.0 ;
            }
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
