        }
        // Mid-stream mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25) ;
            }
        }
        // NEW: dead-space-anticipation — if the next item's own leftover (slack) is itself just
        // below the item after next's plausible size (mean residual), the chain stalls; penalize.
        if slack > 0.0 && mean_residual > 0.0 && slack < mean_residual * 0.6 && slack > mean_residual * 0.15 {
            score += 3.0 * (1.0 - (slack - mean_residual * 0.15) / (mean_residual * 0.45)) * (0.4 + progress) ;
        }
        // NEW: reward residuals that can host next item AND leave a near-mean residual afterward.
        if slack >= nxt * 0.5 && mean_residual > 0.0 && ((slack - mean_residual).abs() as u32) <= 3 {
            score -= 4.0 * (1.0 + progress) ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
