                && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // Fresh-bin chain promise — residual can host next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // NEW: fresh-bin waste guard — if the fresh bin would leave a residual smaller
            // than any plausible future item (below mean residual / 3), it is nearly pure
            // waste; prefer an existing bin instead.
            if fitting_bins_count > 0 && mean_residual > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < mean_residual / 3.0 && progress > 0.4 {
                    score += 5.0 * (1.0 - fresh_left / (mean_residual / 3.0).max(1.0)) ;
                }
            }
            // NEW: late-stream fresh-bin lock — after 0.8 progress, opening a new bin almost
            // always wastes space unless the item truly cannot fit anywhere compactly.
            if progress > 0.8 && fitting_bins_count > 0 && item <= mean_residual.max(1.0) {
                score += 14.0 ;
            }
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
