        }
        // NEW: dead-pocket gradient — slack sitting in the "wasteland" band just above
        // half of next item size can neither host nxt again nor close out; penalize.
        if slack > nxt * 0.55 && slack < nxt && progress > 0.35 {
            score += 2.0 * (0.5 + progress) * (slack - nxt * 0.55) / (nxt * 0.45) ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
