            // predicts a perfect follow-up fit.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // fresh-bin chain promise — capacity minus item leaves a residual that can
            // host next item twice with tight second slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // NEW MUTATION: fresh-bin triple-host promise — when the fresh residual can host
            // the next item three times with tight final slack, this is a near-perfect split;
            // pull hard especially when hosting options are scarce.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.2 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= 4.0 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / 5.0) * (0.6 + progress) ;
                }
            }
            // NEW MUTATION: fresh-bin anti-strand guard — if no existing bin can host the next
            // item (fitting_bins_count counts only current-item fits) and mean residual is
            // tiny, a fresh bin's leftover is the only future capacity; soften the pull-back.
            if fitting_bins_count > 0 && mean_residual > 0.0 && mean_residual < nxt * 0.4 && progress > 0.6 {
                score -= 3.0 ;
            }
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
