            }
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 {
                score -= 5.0 ;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5 ;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0 ;
            }
            if fitting_bins_count > 0 && progress < 0.45 && mean_residual > cap * 0.45
                && item < mean_residual * 0.5 {
                score -= 3.0 ;
            }
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0) ;
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0 ;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2 {
                score -= 5.0 ;
            }
            // Fresh-bin divisibility promise — pull harder when few bins can host next item.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight second slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let nxt = next_item_size as f64 ;
    let item = item_size as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let is_new_bin = bin_residual == bin_capacity ;
    let cap = bin_capacity as f64 ;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 } ;
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 } ;
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 } ;

    // Tight-fit ladder: exact and near-exact leftovers strongly rewarded.
    if post_residual == 0 {
        score -= 66.0 ;
    } else if post_residual <= 2 {
        score -= 32.0 ;
    } else if post_residual <= 5 {
        score -= 16.0 ;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64 ;
        score += 44.0 + 3.4 * gap * gap ;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0) ;
        score += 4.0 + 0.85 * excess ;
    }

    // Lookahead: reward leftovers that can host the next item, scaled by slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack ;
        } else {
            score -= 30.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0 ;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0 ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 13.0 ;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0) ;
        }
        // Divisibility bonus: residual exactly divisible by next item promises perfect future reuse.
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0 ;
        }
        // Scarcity coupling: few bins can host the next item — keep hosting capacity alive.
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0) ;
        }
        // Mid-slack dead-space brake, sharpened late in the stream.
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0) ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64 ;
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0)) ;
        }
        // Quasi-perfect slack band: slack just below next item size is nearly a second fit.
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt ;
            score += 5.0 * band * band * (0.5 + progress) ;
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress) ;
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress) ;
        }
        // Penalize large dead-space residuals that the next item cannot use.
        if nxt > pr && dead_ratio > 0.15 && progress > 0.3 {
            score += 9.5 * dead_ratio * dead_ratio * (0.5 + progress) ;
        }
        // Dead-space that survives even after placing the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress) ;
        }
        if slack > 0.0 && nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress) ;
        }
        // Mid-stream mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25) ;
            }
        }
        // slack-harmonic — slack that would leave a second near-perfect host doubly valuable.
        if slack > nxt && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0) ;
        }
        // Penalize slack that strands just under a multiple of nxt (dead pocket).
        if slack > nxt && (slack % nxt.max(1.0)) > nxt.max(1.0) - 3.0 {
            score += 2.5 * ((slack % nxt.max(1.0)) - (nxt.max(1.0) - 3.0)) / 3.0 * (0.5 + progress) ;
        }
        // NEW: scarcity-weighted slack quality — when few bins can host next, small slack is gold.
        if fitting_bins_count <= 2 && slack >= 1.0 && slack <= 3.0 {
            score -= 4.0 * (1.0 - slack / 4.0) * (0.5 + progress) ;
        }
        // NEW: large-slack brake — residuals leaving big unusable slack late in the stream
        // are worse than their size suggests; couple slack to progress and mean_residual.
        if progress > 0.55 && slack > nxt + 8.0 {
            score += 0.35 * (slack - nxt - 8.0) * (progress - 0.55) * 2.0 ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0 ;
        }
        if nxt - pr <= 1.0 {
            score += 6.0 ;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 } ;
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt) ;
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0) ;
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio ;
        }
        // Near-miss dead space is worse when many bins could host the next item instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0) ;
        }
        // Near-miss with a large residual wastes proportionally more absolute space.
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0) ;
        }
        // NEW: tiny-residual near-miss salvage — a residual only 1–2 below nxt may still
        // combine with a future small item; reward it early, penalize late.
        if nxt - pr >= 1.0 && nxt - pr <= 2.0 {
            score += if progress < 0.5 { -3.0 } else { 2.0 } ;
        }
    }

    // Fit tightness reward.
    let fit_ratio = item / bin_residual.max(1) as f64 ;
    score -= 6.0 * fit_ratio ;

    // Open-bin consolidation pressure.
    score += 0.3 * open_bins_count as f64 * (pr / cap) ;

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0 ;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0 ;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap) ;
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0 ;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress) ;
        }
        // Global dead-space ratio penalty, sharpened late in the stream.
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3) ;
        }
        // Stranded-void gradient: residuals just below next item are costliest dead space.
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0 ;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 } ;
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0) ;
        }
        // Late-stage urgency: prefer tighter residuals as stream ends.
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0 ;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0 ;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8 ;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5) ;
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0) ;
            }
        }
        // Endgame squeeze: near the end, prefer bins whose residual stays usable.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0) ;
        }
        // Endgame exact-fit anticipation — residuals within 2 of next item are gold late.
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0 ;
        }
        // Low-variance preference — small residuals waste less absolute space mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5) ;
        }
        // NEW: absolute dead-space floor — any residual that cannot host the next item
        // AND is smaller than half the mean residual is nearly unrecoverable; nudge it up.
        if nxt > 0.0 && pr < nxt && mean_residual > 0.0 && pr < mean_residual * 0.5 && progress > 0.6 {
            score += 2.5 * (1.0 - pr / (mean_residual * 0.5)) ;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0 ;
            }
            // Late stream: prefer keeping existing bins in play.
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0 ;
            }
            // Fresh bin already perfect for next item: strong pull.
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0 ;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0 ;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0 ;
            }
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 {
                score -= 5.0 ;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5 ;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0 ;
            }
            if fitting_bins_count > 0 && progress < 0.45 && mean_residual > cap * 0.45
                && item < mean_residual * 0.5 {
                score -= 3.0 ;
            }
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0) ;
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0 ;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2 {
                score -= 5.0 ;
            }
            // Fresh-bin divisibility promise — capacity minus item divisible by next item
            // predicts a perfect follow-up fit; pull harder when few bins can host next item.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // Fresh-bin chain promise — residual that can host next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // NEW: fresh-bin scarcity gate — when NO open bin can host the next item, a fresh
            // bin whose leftover keeps that item hostable is much more valuable.
            if fitting_bins_count > 0 && nxt > 0.0 && progress < 0.8 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= nxt {
                    score -= 3.0 * (0.5 + progress) ;
                }
            }
            // NEW: fresh-bin waste guard — never open a fresh bin when the item nearly
            // fills the bin and open bins have residuals larger than the item.
            if fitting_bins_count > 0 && item > cap * 0.7 {
                score += 5.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small residuals are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional class of post_residual (capacity fractions).
    let frac = pr / cap;
    if frac <= 0.05 {
        score -= 60.0; // near-perfect fill: excellent
    } else if frac <= 0.10 {
        score -= 40.0;
    } else if frac <= 0.20 {
        score -= 15.0;
    } else if frac <= 0.35 {
        score -= 4.0;
    } else {
        score += 12.0; // leaving a big hole
    }

    // Integer-division thresholds: residual classes of 10 units.
    let class = post_residual / 10;
    score -= match class {
        0 => 25.0,
        1 => 10.0,
        2 => 3.0,
        3 => -2.0,
        _ => 6.0,
    } as f64;

    // Modulo arithmetic: pair residuals with next item size.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits exactly-ish: strong reward.
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 80.0;
        } else if gap <= 5 {
            score -= 45.0;
        } else if gap <= 10 {
            score -= 20.0;
        }
        // Harmonic congruence: residual mod next item small => chainable.
        if post_residual % next_item_size.max(1) <= 3 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize wasting this bin's future.
        score += 8.0;
    }

    // Last-chance bin before opening a new one.
    if fitting_bins_count == 1 && post_residual < item_size + 10 {
        score -= 18.0;
    }

    // New empty bin candidate: penalize moderately so it wins only when
    // all open bins give bad fits (their scores carry dead-space penalties).
    if bin_residual == bin_capacity {
        score += 55.0 + 0.05 * open_bins_count as f64;
    } else {
        // Prefer tighter existing bins slightly.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Mild stream-phase drift: later, favor consolidation.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * phase * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder: exact and near-exact leftovers strongly rewarded.
    if post_residual == 0 {
        score -= 64.0;
    } else if post_residual <= 2 {
        score -= 31.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 43.0 + 3.3 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.8 * excess;
    }

    // Lookahead: reward leftovers that can host the next item, scaled by slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        // Divisibility bonus: residual exactly divisible by next item promises perfect future reuse.
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        // Scarcity coupling: few bins can host the next item — keep hosting capacity alive.
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        // Mid-slack dead-space brake, sharpened late in the stream.
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        // Quasi-perfect slack band: slack just below next item is nearly a second fit.
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        // Penalize large dead-space residuals that the next item cannot use.
        if nxt > pr && dead_ratio > 0.15 && progress > 0.3 {
            score += 9.5 * dead_ratio * dead_ratio * (0.5 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mid-stream mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic: slack that would leave a second near-perfect host for the item
        // after next is doubly valuable; approximate via divisibility of slack by nxt.
        if slack > nxt && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Penalize slack that strands just under a multiple of nxt (dead pocket).
        if slack > nxt && (slack % nxt.max(1.0)) > nxt.max(1.0) - 3.0 {
            score += 2.5 * ((slack % nxt.max(1.0)) - (nxt.max(1.0) - 3.0)) / 3.0 * (0.5 + progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        // Near-miss dead space is worse when many bins could host the next item instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        // Near-miss with a large residual wastes proportionally more absolute space.
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
    }

    // Fit tightness reward.
    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;

    // Open-bin consolidation pressure.
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        // Global dead-space ratio penalty, sharpened late in the stream.
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        // Stranded-void gradient: residuals just below next item are costliest dead space.
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        // Late-stage urgency: prefer tighter residuals as stream ends.
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: near the end, prefer bins whose residual stays usable.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — small residuals waste less absolute space mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
    }

    // New-bin candidate handling.
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            // Fresh-bin divisibility promise — capacity minus item divisible by next item
            // predicts a perfect follow-up fit; pull harder when few bins can host next item.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual that can host next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) as f64 > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh bin whose leftover exactly equals next item: strong pull.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.4 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if (fresh_left - nxt).abs() <= 1.0 {
                    score -= 6.0;
                }
            }
            // Mid-stream brake refined: only resist fresh bins when alternatives are decent.
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2
                && item <= cap * 0.35 && mean_residual >= item * 1.1 {
                score += 6.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps that few items can fit into.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize mildly so it is chosen only when fits are bad,
    // but less so when many bins are open and mean residual is fragmented.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * mean_residual;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 8.0;
    }

    score
}

