        // item yet larger than a trivial remainder are pure future waste; penalize with a
        // smooth ramp scaled by how many bins could still host the next item.
        if nxt > 0.0 && pr < nxt && pr > nxt * 0.35 && fitting_bins_count > 1 {
            score += 2.0 * (1.0 - pr / nxt) * (0.4 + progress) ;
        }
    }

