            // predicts a perfect follow-up fit; pull harder when few bins can host next item.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // fresh-bin chain promise — capacity minus item leaves a residual that can
            // host next item twice with tight second slack; pull toward such splits.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // NEW (gen 76): fresh-bin fragment guard — refuse a fresh bin whose leftover
            // would be a stranded fragment (usable by nothing plausible); stronger late.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.4 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && fresh_left > nxt * 0.4 {
                    score += 3.5 * (1.0 - fresh_left / nxt) * progress ;
                }
            }
            // NEW (gen 76): fresh-bin triple-split promise — leftover hosting next item
            // three times with a tight tail is a strong opening move early in the stream.
            if fitting_bins_count > 0 && nxt > 0.0 && progress < 0.5 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt {
                    score -= 3.0 * (1.0 - progress * 1.6) ;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mean_norm = mean_residual / cap;

    // Base: penalize wasted space, weighted non-linearly by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial coupling: tight fits rewarded more as stream progresses
    let tight = 1.0 - norm_pr;
    score -= 12.0 * tight * tight * (0.5 + progress);

    // Penalize residuals too small for the lookahead item (smooth quadratic dead-space term)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        let dead = if gap < 0.0 { -gap } else { 0.0 };
        score += 9.0 * dead * dead * cap;
        // Reward residuals that exactly (or nearly) accommodate the next item
        let fit_next = 1.0 / (1.0 + (gap.abs() * 6.0) * (gap.abs() * 6.0));
        score -= 6.0 * fit_next * (1.0 - progress);
    }

    // Last-chance bonus: smooth, stronger later in the stream
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 8.0 * last_chance * (0.4 + 0.6 * progress);

    // Penalize bins whose residual deviates far below the mean (fragmentation signal)
    let dev = norm_pr - mean_norm;
    score += 4.0 * dev * dev * cap;

    // Mild penalty on opening new bins when many are open and stream is early
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (2.0 + 6.0 * (1.0 - progress)) + new_bin * norm_item * 4.0 * (1.0 - progress);

    // Reward using bins with large residual when item is large (avoid stranding big items)
    score -= 3.0 * norm_item * norm_pr;

    score
}

