pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score *= 0.85 + 0.3 * p2 - 0.15 * p3;

    // Reward tight fits: quadratic penalty on wasted fraction
    let waste = norm_post * norm_post;
    score += 40.0 * waste * (0.5 + progress);

    // Dead-space penalty: residuals too small for typical items
    if post < next_item_size as f64 && next_item_size > 0 {
        score += 12.0 * (next_item_size as f64 - post) / cap * (1.0 + 2.0 * progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a new bin early or when fit is poor
    if bin_residual == bin_capacity {
        score = cap * (1.0 - progress) + 20.0 * waste * cap;
    }

    // Mild pressure against spreading across many bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

