        // NEW: scarcity-amplified tight slack — when the next item has few hosts,
        // preserving the tightest slack is critical for avoiding a fresh bin later.
        if fitting_bins_count <= 2 && slack > 0.0 && slack <= nxt * 0.5 {
            score -= 2.5 * (1.0 - slack / (nxt * 0.5).max(1.0)) * (0.6 + progress) ;
        }
        // NEW: mean-harmonic slack — slack near the running mean residual suggests the
        // bin will blend into the residual population and stay reusable.
        if mean_residual > 0.0 && slack > 0.0 {
            let sdev = ((slack - mean_residual) / mean_residual.max(1.0)).abs() ;
            if sdev < 0.15 && progress > 0.25 {
                score -= 2.0 * (1.0 - sdev / 0.15) * (1.0 - progress) ;
