        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0 ;
        }
        // NEW: endgame exact-fill ladder — when the stream is nearly done, residuals
        // that the current item fills exactly deserve a stronger pull.
        if progress > 0.8 && post_residual == item_size {
