        }
        // REFINED: absolute dead-space floor — large residuals that the next item cannot
        // fully consume waste proportional space; scale by dead_ratio and scarcity.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0) ;
        }
        // NEW: triple-fit chain bonus — residuals hosting nxt three times with tight final
        // slack are exceptionally valuable when open bins are few.
        if post_residual >= 3 * next_item_size && fitting_bins_count <= 3 {
            let tail = ((post_residual - 3 * next_item_size) as f64) ;
            if tail <= nxt {
