pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post-residual that is too small to be useful.
    let dead_zone = 8.0;
    if (post_residual as f64) < dead_zone {
        score -= 20.0 * (dead_zone - post_residual as f64);
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits in post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.5 * (next_item_size as f64);
        } else {
            // Penalize blocking the next item only slightly; new bins absorb it.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With multiple candidates, prefer fuller bins (smaller residual).
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Prefer compacting into bins that are already fairly full.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Time horizon: early in the stream, be more willing to open new bins
    // (many items remain); late in the stream, pack tightly into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 25.0 * progress + 0.5 * open_bins_count as f64;
        // Allow new bin early if mean residual is low (open bins are tight).
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    } else {
        // Late stream: reward using existing bins more aggressively.
        score -= 10.0 * progress;
    }

    // Global pressure: many open bins with high mean residual -> discourage
    // opening new bins and encourage spreading into existing ones.
    if open_bins_count > 4 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

