        if slack > nxt && (slack % nxt.max(1.0)) > nxt.max(1.0) - 3.0 {
            score += 2.5 * ((slack % nxt.max(1.0)) - (nxt.max(1.0) - 3.0)) / 3.0 * (0.5 + progress) ;
