pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, waste tolerance is high; late, waste is punished harder.
    let waste_penalty = post * post / cap * (0.5 + 1.5 * progress * progress);
    score += waste_penalty;

    // Perfect-fit reward (smooth, polynomial).
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= 6.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 2.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild crowding penalty among many candidates
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // Penalize bins whose residual deviates from the mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed.
    if bin_residual == bin_capacity {
        let open_bonus = if open_bins_count > 0 { 8.0 + 12.0 * progress } else { -5.0 };
        score += open_bonus;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

