                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover strands
            // just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor() ;
                    let pocket = fresh_left - m * nxt ;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0 ;
                    }
                }
            }
            // Many open bins with large residuals — discourage adding another.
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits (tight packing).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // If the next item fits exactly in the post residual, reward strongly (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: the dead space is likely permanent.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Pressure from many open bins: discourage spreading, prefer filling existing bins.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current residual is very small.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0; // existing bins still have room on average
        }
    }

    // Late in the stream, prefer closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

