pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Reward tight fits: non-linear decay of the fit bonus with post_residual
    let fit_ratio = 1.0 - (pr / cap);
    score -= 30.0 * fit_ratio.powi(4);

    // Penalize dead space that grows quadratically for mid-range residuals
    let dead = pr / cap;
    score += 8.0 * dead * dead;

    // Lookahead coupling: bonus if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - slack).powi(3);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Stream progress: later in stream, prefer consolidating into existing bins
    score -= 12.0 * progress * (1.0 - dead);

    // Scarcity: if this is the last fitting bin, reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin, more so with many open bins
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // but if mean residual is high, opening is less attractive
        score += mean_residual / cap * 5.0;
    } else {
        // Align with mean residual: bins above mean are slightly favored to fill
        score -= 3.0 * ((bin_residual as f64 - mean_residual) / cap);
    }

    score
}

