pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod 10 buckets
    let class = post_residual % 10;
    // Dead-space penalty grows superlinearly for awkward residual classes
    // Classes 1..9 (non-multiples of 10) create harder-to-fill gaps
    let dead_penalty: f64 = match class {
        0 => -6.0,                       // perfect decade residual: very reusable
        1 | 2 => 14.0,                   // tiny slivers: nearly dead space
        3 | 4 | 6 | 7 => 5.0,            // medium awkwardness
        5 => 0.0,                        // half-decade: pairs with 5s
        8 | 9 => 2.0,                    // fillable by small items
        _ => 0.0,
    };
    score += dead_penalty;

    // Integer-division threshold: post_residual in [1,10] is a "sliver zone"
    if post_residual > 0 && post_residual <= 10 {
        score += 18.0;
    }
    // post_residual in (50, 100] is a half-empty bin: highly desirable
    if post_residual > 50 {
        score -= 8.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chaining: next item also fits here
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 10.0 + 0.15 * chain_fit;
        } else {
            // Penalize blocking the next item
            score += 6.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer tighter fits: relative fill ratio of this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Coupling with mean residual: placing into a bin far below mean residual
    // (i.e., this bin is unusually full) is good consolidation
    let residual_gap = mean_residual - post_residual as f64;
    score -= 0.1 * residual_gap;

    // Progress modulation: early in stream, be picky; late, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // New-bin candidate: opening a new bin is only good if item is large
    // or all open bins are too full (fitting_bins_count small)
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        // Large items start fresh bins cheaply; small items should reuse
        let large_item_bonus = if item_size >= 60 { 6.0 } else { 0.0 };
        score = 55.0 - 30.0 * openness - large_item_bonus + 0.2 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
    }

    score
}

