pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes of 10 (classic waste bands)
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.8; // penalize residuals not near multiples of 10

    // Dead-space band: residuals in (0,10] are nearly unusable for min size 1... but small items exist
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure reward
    }

    // Integer-division threshold: post_residual / 10 buckets
    let bucket = post_residual / 10;
    score -= bucket as f64 * 2.0; // larger usable buckets preferred

    // Harmonic coupling with next item: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // check harmonic alignment: next_item_size % 10 classes
            let nclass = (next_item_size % 10) as f64;
            score -= 12.0 + nclass * 0.3; // reward chains
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // last item: prefer any bin, close it out
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it gives a great fit
    if bin_residual == bin_capacity {
        // new bin: post_residual == cap - item; reward only for large items
        score += 15.0 + (80.0f64.min(item_size as f64)).max(0.0) * 0.0;
        score -= if item_size >= 50 { 25.0 } else { 0.0 };
        score += mean_residual * 0.15; // opening new bins more costly when mean residual high
    }

    // Fraction of capacity used by this placement
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 10.0;

    // Stream progression: late in stream, be more aggressive closing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (post_residual == 0) as i32 as f64;

    // Crowding: many open bins -> prefer filling existing ones
    score += open_bins_count as f64 * 0.4;
    if bin_residual != bin_capacity {
        score -= 3.0; // small bonus for reusing an existing bin
    }

    score
}

