                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor() ;
                    let pocket = fresh_left - m * nxt ;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0 ;
                    }
                }
            }
            // NEW: fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2 {
                score -= 5.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is already the base).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.8 {
        score -= 12.0 * fit_ratio;
    } else if fit_ratio > 0.5 {
        score -= 5.0 * fit_ratio;
    }

    // Penalize dead space that can never be used by typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // nearly perfect fill
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 2.0; // awkward leftover zone
    }

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let combo = next_item_size as f64 / post_residual as f64;
        score -= 10.0 + 8.0 * combo;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize wasting residual capacity
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins with high mean residual: encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread = mean_residual - post_residual as f64;
    score += 0.05 * open_bins_count as f64;
    score -= 0.3 * spread * progress;

    // New empty bin candidate: penalize opening new bins unless fit is poor
    // or no existing bin is a good last-chance option.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Allow new bin when item is huge relative to capacity (poor fits everywhere)
        // or late in stream with many bins already open.
        if item_size >= 70 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if progress > 0.8 && open_bins_count > 3 {
            score -= 8.0;
        }
    }

    score
}

