                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let item = item_size as f64;

    // Base: penalize wasted space, quadratically coupled with progress
    // (dead space matters more as the stream nears its end).
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Smooth non-linear coupling of post-residual with item size:
    // small post_residual relative to item size is a good tight fit.
    let tightness = pr / (item + 1.0);
    score -= 12.0 * (-tightness).exp();

    // Penalize post_residual that is too large (bin left too open = poor packing),
    // with a smooth cubic term in normalized post_residual.
    let prn = pr / cap;
    score += 20.0 * prn * prn * prn;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how well the item fits).
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - prn);
    }

    // Lookahead: reward if next item fits into the resulting post_residual,
    // penalize if next item is larger than remaining space (smoothly).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (nx <= pr) as i32 as f64;
        let gap = ((nx - pr).abs()) / cap;
        score -= 8.0 * fits_next * (1.0 - gap);
        score += 4.0 * (1.0 - fits_next) * (1.0 - gap);
    }

    // Mild penalty for spreading across many open bins: prefer consolidation
    // when mean residual is high, smoothly coupled with progress.
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap) * (1.0 - progress);

    // New-bin candidate handling: an empty bin has large post_residual;
    // the cubic term already penalizes it, but add a smooth extra term so
    // a new bin is only chosen when existing fits are very poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 10.0 * (1.0 - item / cap);
    }

    score
}

