            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Fresh-bin pull when the only fitting bin would strand near the next item.
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        if nxt > pr && dead_ratio > 0.15 && progress > 0.3 {
            score += 9.5 * dead_ratio * dead_ratio * (0.5 + progress);
        }
        // Dead-space that survives even after placing the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        if slack > 0.0 && nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack that would leave a second near-perfect host is doubly valuable.
        if slack > nxt && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // NEW: exact-fill chain — residuals that the next item consumes to exactly zero
        // are the strongest possible compaction signal; deepen the reward when scarce.
        if slack == 0.0 && fitting_bins_count <= 2 {
            score -= 9.0;
        }
        // NEW: penalize slack that leaves a residual just below the next item after
        // placement — this dead pocket is stranded for the immediate future.
        if slack > 0.0 && slack < nxt && nxt - slack <= 4.0 {
            score += 5.0 * (1.0 - (nxt - slack) / 5.0) * (0.6 + progress);
        }
        // NEW: reward residuals that can host the next item AND leave a multiple of it.
        if nxt > 0.0 && slack >= nxt && (slack as u32) % next_item_size.max(1) == 0 {
            score -= 3.0 * (1.0 + progress * 0.5);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        // Near-miss dead space is worse when many bins could host the next item instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss residual when few
        // other bins can host the next item is doubly costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // NEW: near-miss that becomes usable after the item after next — soften the
        // penalty when the residual is exactly a small divisor of the next item.
        if nxt - pr > 0.0 && nxt - pr <= 3.0 && nxt > 4.0
            && (nxt as u32) % (nxt - pr) as u32 == 0 {
            score -= 3.0;
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // NEW: dead-space compounding — residuals that are dead for the next item AND
        // large relative to the mean are prime candidates to avoid mid-stream.
        if progress > 0.4 && nxt > 0.0 && pr < nxt && pr > mean_residual * 1.5 {
            score += 2.5 * (pr / mean_residual.max(1.0) - 1.5).min(2.0);
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 {
                score -= 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // NEW: fresh-bin exact-fit promise — residual after placement is exactly
            // the next item size, enabling a perfect fill on the following step.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.25 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if (fresh_left - nxt).abs() <= 1.0 {
                    score -= 5.0 * (1.0 - progress * 0.4);
                }
            }
            // NEW: fresh-bin scarcity override — when every fitting bin would strand
            // a near-miss residual, opening fresh is cheaper than wasting capacity.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.4 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let min_near_miss = fresh_left < nxt && nxt - fresh_left <= 3.0;
                if min_near_miss && item <= cap * 0.5 {
                    score -= 4.0;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize waste relative to capacity.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Penalize small unusable leftovers (< 10 can never fit any item).
    if post_residual < 10 {
        score -= 8.0; // perfect fill is great
    } else if post_residual <= 15 {
        score += 6.0; // awkward dead space
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, bonus; if it would fit
    // this bin better than current item, slight penalty for wasting space.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 5.0;
        }
        if next_item_size as u32 > post_residual && (next_item_size as u32) <= bin_residual {
            score += 4.0;
        }
    }

    // New-bin candidate: prefer it only when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / (bin_capacity as f64);
        // High average fill means open bins are well used -> opening new bin is fine.
        let pressure = if open_bins_count == 0 { 0.0 } else { (open_bins_count as f64).ln() };
        score = score.max(0.0) + 20.0 - 25.0 * avg_fill - 6.0 * pressure + 10.0 * progress;
        // If the item fits very tightly in an existing bin, make new bin less attractive.
        if tightness > 0.9 && bin_residual == bin_capacity {
            score += 10.0;
        }
    }

    // Mild preference for filling bins with larger residual when many bins open.
    score += 0.02 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder (refined: deeper reward for exact/near-exact closure).
    if post_residual == 0 {
        score -= 70.0;
    } else if post_residual <= 2 {
        score -= 34.0;
    } else if post_residual <= 5 {
        score -= 17.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 50.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        if nxt > pr && dead_ratio > 0.15 && progress > 0.3 {
            score += 9.5 * dead_ratio * dead_ratio * (0.5 + progress);
        }
        // Dead-space that survives even after placing the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        if slack > 0.0 && nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack that would leave a second near-perfect host is doubly valuable.
        if slack > nxt && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // NEW: triple-host chain — residual hosting nxt three times with tight remainder
        // compounds the chain-lookahead promise; reward scaled by scarcity.
        if nxt >= 1.0 && post_residual >= 3 * next_item_size {
            let rem3 = (post_residual - 3 * next_item_size) as f64;
            if rem3 <= nxt {
                score -= 2.5 * (1.0 - rem3 / nxt) * (0.5 + progress)
                    + if fitting_bins_count <= 2 { 2.0 } else { 0.0 };
            }
        }
        // NEW: large-slack penalty sharpening — slack far above nxt but below 2*nxt
        // wastes more when many bins remain open (fragmentation pressure).
        if slack > nxt * 1.2 && slack < nxt * 2.0 && open_bins_count > 4 {
            score += 1.2 * (slack / nxt - 1.2) * (0.5 + progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        // Near-miss dead space is worse when many bins could host the next item instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss residual when few
        // other bins can host the next item is doubly costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // NEW: near-miss recoverability — if the deficit (nxt - pr) is small AND
        // other open bins hold residuals near that deficit, this strand may be
        // merged later; soften the penalty slightly in that case.
        if nxt - pr > 0.0 && nxt - pr <= 10.0 && mean_residual > (nxt - pr) * 0.8
            && mean_residual < (nxt - pr) * 2.5 && progress > 0.4 {
            score -= 2.0 * (1.0 - (nxt - pr) / 11.0);
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // NEW: mid-stream waste gradient — residuals above 40% of capacity that the
        // next item cannot reach accumulate dead space; penalize progressively.
        if progress > 0.45 && nxt > 0.0 && pr > cap * 0.4 && pr < nxt {
            score += 2.5 * (pr / cap) * (progress - 0.45) * 2.0;
        }
        // NEW: tiny-residual sweep — residuals of 1–2 units mid-stream are nearly
        // free wins; reward slightly harder so they get consumed, not stranded.
        if pr >= 1.0 && pr <= 2.0 && progress > 0.3 && nxt > pr {
            score -= 2.0 * (1.0 - progress * 0.4);
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 {
                score -= 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // NEW: fresh-bin exact-tiling promise — residual exactly divisible by nxt
            // with zero remainder is a perfect chain; strengthen the pull when the
            // stream is mid-flight and few bins can host the next item.
            if fitting_bins_count > 0 && nxt >= 2.0 && progress > 0.4 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt && fresh_left % nxt == 0.0 && fresh_left / nxt <= 4.0 {
                    score -= 3.0 * (1.0 - fresh_left / (4.0 * nxt)) * (0.5 + progress);
                }
            }
            // NEW: fragmentation brake — when many bins are already open with healthy
            // residuals, resist opening fresh bins unless the item is large.
            if fitting_bins_count > 0 && open_bins_count > 5 && item < cap * 0.3
                && mean_residual > item * 1.5 {
                score += 3.0 * (open_bins_count as f64 / 10.0).min(1.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, damped by non-linear polynomial in progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth coupling: small post-residual penalized more as stream progresses
    score += 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);

    // Reward tight fit when it's the only fitting bin (last chance)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr) * (1.0 - progress);
    }

    // Dead-space penalty for residuals too small for typical future items
    score += 15.0 * norm_pr * norm_pr * (1.0 - norm_pr);

    // Lookahead: favor bins where next item also fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 6.0 * progress;
    }

    // Prefer filling bins with above-mean residual (balance avoidance)
    score -= 5.0 * (bin_residual as f64 - mean_residual) / cap;

    // Mild penalty for opening new bins early
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        if nxt > pr && dead_ratio > 0.15 && progress > 0.3 {
            score += 9.5 * dead_ratio * dead_ratio * (0.5 + progress);
        }
        // Dead-space that survives even after placing the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        if slack > 0.0 && nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack that would leave a second near-perfect host is doubly valuable.
        if slack > nxt && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // NEW: triple-host promise — residuals hosting nxt three times with tight remainder.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // NEW: residual-fragmentation guard — residuals in the awkward mid-band
        // (too big to strand, too small to double-host) are the top dead-space source.
        if slack > nxt * 0.6 && slack < nxt * 1.4 && dead_ratio > 0.15 {
            score += 2.5 * dead_ratio * (1.0 - ((slack / nxt) - 1.0).abs() / 0.4) * (0.6 + progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        // Near-miss dead space is worse when many bins could host the next item instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss residual when few
        // other bins can host the next item is doubly costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // NEW: near-miss salvage value — a residual just below nxt can still pair
        // with a small future item; penalize less when mean_residual is small.
        if nxt - pr > 6.0 && nxt - pr <= 12.0 && mean_residual > 0.0 && mean_residual < pr * 0.5 {
            score += 2.0 * (1.0 - (nxt - pr) / 13.0);
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // NEW: exact-fill chase — residuals that the item fills to within 1 unit
        // of a clean small remainder deserve an extra nudge at all stages.
        if pr <= 4 && pr > 0 && item <= bin_residual as f64 {
            score -= 2.0 * (1.0 - pr / 5.0) * (0.5 + progress);
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 {
                score -= 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // NEW: fresh-bin exact-complement promise — a fresh bin whose leftover
            // after this item is an exact small multiple of nxt is nearly free capacity.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.25 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left % nxt == 0.0 && fresh_left / nxt <= 5.0 {
                    score -= 4.5 * (1.0 - fresh_left / (nxt * 6.0)) * (0.4 + progress);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let q = post_residual / (bin_capacity / 4);
    let r = post_residual % (bin_capacity / 4);
    // Penalize residuals in awkward harmonic classes (small odd remainders)
    score += (r as f64) * 0.35;
    score += match q {
        0 => 6.0,   // nearly full: good, reward
        1 => 2.0,
        2 => 0.0,
        _ => 3.0,   // half-empty bins less urgent
    };
    score -= 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(2));

    // Dead-space penalty: residual too small for typical items
    if post_residual < 10 {
        score += 8.0; // effectively sealed bin
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 3.0; // next item won't chain here
        } else {
            score -= 2.5;
            // harmonic pairing: next item complements to a quarter boundary
            let combo = post_residual - next_item_size;
            if combo % (bin_capacity / 4) == 0 && combo > 0 {
                score -= 3.0;
            }
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: make it unattractive unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if stream is early and mean residual is low, fresh bins are fine
        if open_bins_count == 0 {
            score -= 20.0;
        }
        if mean_residual < 8.0 && open_bins_count > 0 {
            score -= 6.0;
        }
    }

    // Progression: prefer tightening bins later in stream
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * (bin_residual - post_residual) as f64 * 0.1;

    // Spread-awareness: many open bins -> consolidate
    score += (open_bins_count as f64) * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let nxt = next_item_size as f64 ;
    let item = item_size as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let is_new_bin = bin_residual == bin_capacity ;
    let cap = bin_capacity as f64 ;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 } ;
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 } ;
    let min_item = if item_size > 0 { item_size as f64 } else { 1.0 } ;
    let stranded = if pr > 0.0 && pr < min_item { 1.0 } else { 0.0 } ;

    // Tight-fit ladder (fine-grained residual fitting).
    if post_residual == 0 {
        score -= 66.0 ;
    } else if post_residual <= 2 {
        score -= 32.0 ;
    } else if post_residual <= 5 {
        score -= 16.0 ;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64 ;
        score += 44.0 + 3.4 * gap * gap ;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0) ;
        score += 4.0 + 0.85 * excess ;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack ;
        } else {
            score -= 30.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0 ;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0 ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 13.0 ;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0) ;
        }
        // Chain-lookahead: residual hosts next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress) ;
        }
        // Slack-harmonic: slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0) ;
        }
        // Dead-pocket gradient: penalize slack just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor() ;
            let pocket = slack - m * nxt ;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress) ;
            }
        }
        // Mean-band harmony: residuals near mean keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25) ;
            }
        }
        // Absolute dead-space floor: large residuals next item cannot consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0) ;
        }
        // Penalize unusably large slack relative to mean residual.
        if slack > mean_residual * 2.5 && slack > 14.0 {
            score += 0.35 * (slack - mean_residual * 2.5) ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        if pr < mean_residual * 0.35 && progress > 0.4 {
            score += 4.0 ;
        }
        if nxt - pr <= 1.0 {
            score += 6.0 ;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 } ;
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0) ;
        }
        // Near-miss scarcity coupling.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress) ;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0 ;
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64 ;
    score -= 6.0 * fit_ratio ;

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0 ;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0 ;
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0 ;
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3) ;
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0 ;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 } ;
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0 ;
        }
        // Endgame squeeze: prefer residuals that stay usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0) ;
        }
        // Usable-capacity guard: residuals below next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0 ;
        }
        // Mid-stream consolidation toward the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0) ;
            }
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0 ;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Avoid fresh bins whose leftover strands just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // Fresh-bin chain promise: leftover hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor() ;
                    let pocket = fresh_left - m * nxt ;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0 ;
                    }
                }
            }
            // Fresh-bin pull when placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0) ;
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0 ;
                }
            }
            // Worst-case guard: fitting bins would leave large dead space.
            if fitting_bins_count > 0 && mean_residual > 0.0 && item + mean_residual > cap * 0.95 && progress < 0.7 {
                score -= 6.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder: exact and near-exact leftovers are strongly rewarded.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    // Lookahead: reward leftovers that can host the next item, scaled by slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if slack > nxt * 1.5 && slack < mean_residual * 0.5 {
            score += 5.0;
        }
        // Divisibility bonus: residual exactly divisible by next item promises perfect future reuse.
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        // Scarcity coupling: when few bins can host the next item, keeping hosting capacity alive is doubly valuable.
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        // Slack-band curvature: slack just under a multiple of nxt is a dead pocket.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Slack-band harmony: slack that leaves a second near-perfect host.
        if slack > nxt && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Absolute dead-space floor: large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Slack just below nxt is a stranded near-miss.
        if slack > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
            if dead_ratio > 0.1 {
                score += 4.0 * dead_ratio * (1.0 + progress);
            }
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        // Near-miss gradient softened when many alternatives exist.
        if nxt - pr <= 2.0 && fitting_bins_count >= 3 {
            score -= 3.0;
        }
        // Near-miss scarcity coupling: stranding a near-miss when few bins can host next is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss dead space worse when many alternatives exist.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
    }

    // Fit tightness reward.
    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;

    // Open-bin consolidation pressure.
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    // Late-stage waste avoidance and dead-space control.
    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        // Residual-density control: residuals hovering near the mean are likeliest to strand.
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        // Large waste penalty scaling with progress.
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        // Near-miss closeness with scarcity.
        if nxt > 0.0 && pr < nxt && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        // Endgame squeeze: keep residuals usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) as f64 / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Usable-capacity guard: residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 && nxt > 0.0 && pr < nxt {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
    }

    // New-bin candidate handling.
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            // Mid-stream fresh-bin brake.
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Fresh-bin chain promise: leftover hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin pull for large items that would strand a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Fresh bin when placement elsewhere strands a large residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) as f64 > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are unusable dead space.
    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 12.0;
    } else if post_residual <= 35 {
        score += 4.0;
    } else {
        // Larger usable gaps are mildly attractive.
        score -= 3.0;
    }

    // Reward tight fits (post_residual near zero but not dead space is already penalized;
    // exact fill is perfect).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.5 + 2.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0 + 5.0 * (open_bins_count as f64);
        // If next item could combine with current item in a fresh bin, encourage it.
        if next_item_size > 0 {
            let combined = item_size + next_item_size;
            if combined <= bin_capacity && (bin_capacity - combined) <= 10 {
                score -= 20.0;
            }
        }
        // Late in stream, opening bins is less attractive.
        score += 20.0 * progress;
    }

    // Prefer bins below mean residual slightly (balanced packing).
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        // Next item can't use this bin; leftover gap value drops.
        score += 3.0;
    }

    score
}

