}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize post_residual with non-linear polynomial coupling
    let mut score = pr * (1.0 + 0.5 * progress);

    // Smooth polynomial coupling: small post-residuals are valuable, large ones wasteful
    let prn = pr / cap;
    score += 40.0 * prn * prn * (1.0 - prn) * (1.0 + progress);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - prn).powi(3) * 10.0 * (0.5 + progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: favor bins whose post_residual accommodates next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Mean residual deviation: prefer bins whose residual is near mean (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: mild penalty unless existing bins are very fragmented
    if bin_residual == bin_capacity {
        let frag = (open_bins_count as f64) * mean_residual / cap;
        score = 45.0 - 10.0 * frag + 15.0 * (1.0 - progress);
    }

    score
}

