    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 } ;
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 } ;
    // NEW: quadratic dead-space pressure — waste grows superlinearly with residual size.
    let dead_pressure = dead_ratio * dead_ratio * (0.6 + 0.8 * progress) ;

