                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs() ;
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2) ;
                }
            }
            // NEW: fresh-bin dead-space sweep — prefer opening a new bin when every
            // existing host would leave a large stranded chunk relative to capacity.
            if fitting_bins_count > 0 && progress > 0.3 && dead_ratio > 0.3 {
                score -= 6.0 * dead_ratio * (0.5 + progress) ;
            }
            // NEW: fresh-bin perfect-divisibility seed — a leftover exactly divisible
            // by the next item late in the stream is a strong compaction anchor.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress >= 0.6 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > nxt && fresh_left % nxt.max(1.0) == 0.0 {
                    score -= 4.0 * (1.0 - (fresh_left / nxt).min(6.0) / 6.0) ;
                }
            }
        }
    }

    score
}

