        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        if nxt > pr && dead_ratio > 0.15 && progress > 0.3 {
            score += 9.5 * dead_ratio * dead_ratio * (0.5 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: k-host divisibility ladder — residuals that can absorb nxt k times exactly
        // (or within 1 unit) are premium compaction targets at any k up to 5.
        if nxt >= 1.0 {
            let k = (post_residual as f64 / nxt).floor();
            if k >= 1.0 && k <= 5.0 {
                let rem = (post_residual as f64 - k * nxt).abs();
                if rem <= 1.0 {
                    score -= 4.0 * (1.0 - rem) * (0.4 + 0.6 * progress);
                }
            }
        }
        // NEW: slack-scarcity coupling — when few bins can host nxt, prefer the one
        // whose post-placement slack is smallest (kills avoidable fragmentation).
        if fitting_bins_count <= 3 && slack > 0.0 && slack < nxt {
            score += (4.0 - fitting_bins_count as f64) * (slack / nxt) * 2.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        // Near-miss dead space is worse when many bins could host the next item instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: strand-size gradient — a residual that misses nxt by a lot is nearly
        // worthless; scale the penalty with the miss distance, not just a flat bump.
        if nxt - pr > 3.0 {
            let miss = nxt - pr;
            score += (miss / nxt).min(2.0) * (1.5 + 2.5 * progress);
        }
        // NEW: pair-completion credit — residual within 2 of half of nxt can be
        // paired with a future small item to still close the gap.
        if pr >= nxt * 0.45 && pr < nxt * 0.55 && progress < 0.8 {
            score -= 2.5 * (1.0 - (pr - nxt * 0.45).abs() / (nxt * 0.05).max(1.0)).max(0.0);
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: two-step lookahead — a residual that fits item + nxt with tiny leftover
        // is a perfect seal; a residual leaving item+nxt with a mid-sized hole is worse.
        if nxt > 0.0 && pr >= item + nxt {
            let hole = pr - item - nxt;
            if hole <= 2.0 {
                score -= 6.0 * (1.0 - hole / 3.0);
            } else if hole > nxt * 0.6 {
                score += 2.0 * (hole / nxt).min(2.0);
            }
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin only-if-large trigger — when the item is big and every
            // open bin would strand >30% of its residual, a fresh bin seals better.
            if fitting_bins_count > 0 && progress > 0.55 && item > cap * 0.55 {
                let avg_strand = (mean_residual - item).max(0.0) / mean_residual.max(1.0);
                if avg_strand > 0.3 {
                    score -= 4.0 * avg_strand.min(1.0);
                }
            }
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let nxt = next_item_size as f64 ;
    let item = item_size as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let is_new_bin = bin_residual == bin_capacity ;
    let cap = bin_capacity as f64 ;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 } ;
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 } ;
    let min_item = if item_size > 0 { item_size as f64 } else { 1.0 } ;
    let stranded = if pr > 0.0 && pr < min_item { 1.0 } else { 0.0 } ;

    if post_residual == 0 {
        score -= 66.0 ;
    } else if post_residual <= 2 {
        score -= 30.0 ;
    } else if post_residual <= 5 {
        score -= 15.0 ;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64 ;
        score += 43.0 + 3.3 * gap * gap ;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0) ;
        score += 4.0 + 0.8 * excess ;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        if slack < 5.0 {
            score -= 47.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 37.0 - 0.6 * slack ;
        } else {
            score -= 29.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 17.0 ;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 13.0 ;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0 ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0 ;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0) ;
        }
        if slack > 4.0 && mean_residual > 1.0 && slack >= mean_residual * 0.9 {
            score -= 2.5 ;
        }
        if slack > mean_residual * 2.5 && slack > 14.0 {
            score += 0.35 * (slack - mean_residual * 2.5) ;
        }
        // Chain-lookahead: residual hosting nxt twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress) ;
        }
        // Dead-pocket gradient: slack just below a small multiple of nxt is wasted.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor() ;
            let pocket = slack - m * nxt ;
            if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress) ;
            }
        }
        // Waste-lock: slack neither tight nor reusable mid-stream becomes dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0) ;
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 } ;
        }
        // Mean-band harmony: residuals near mean keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25) ;
            }
        }
        // Small-slack urgency scaled by progress.
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress) ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        if pr < mean_residual * 0.35 && progress > 0.4 {
            score += 4.0 ;
        }
        // Near-miss scarcity: stranding a near-miss with few hosts is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress) ;
        }
        // Near-miss recovery value: stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress) ;
        }
        // Near-miss dead space is worse when many bins can host nxt instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0) ;
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64 ;
    score -= 6.0 * fit_ratio ;
    score += 0.3 * open_bins_count as f64 * (pr / cap) ;

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0 ;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0 ;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap) ;
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3) ;
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0 ;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 } ;
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0 ;
        }
        // Endgame squeeze: residual consumed by nxt to within a few units.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) as f64 / 5.0) ;
        }
        // Exact-fill dividend late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress) ;
        }
        // Usable-capacity guard: residuals below nxt late are pure loss.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 3.0 * (pr / nxt.max(1.0)) * (progress - 0.55) ;
        }
        // Mid-stream consolidation toward the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0) ;
            }
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Avoid fresh bins stranding a residual just below nxt.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // Fresh-bin chain promise: leftover hosts nxt twice tightly.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor() ;
                    let pocket = fresh_left - m * nxt ;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0 ;
                    }
                }
            }
            // Fresh-bin triple-promise.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0)) ;
                }
            }
            // Mean-residual alignment of fresh leftovers.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs() ;
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2) ;
                }
            }
            // Fresh-bin pull for large items that would strand a big dead chunk elsewhere.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0) ;
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0 ;
                }
            }
            // Open fresh when the item is large and would strand a huge residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) as f64 > nxt.max(20.0) * 2.0 {
                score -= 5.0 ;
            }
            // Many open bins with large residuals — discourage adding another.
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            // Late-stage: avoid fresh bin whose leftover can't host next item.
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 8.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        if nxt > pr && dead_ratio > 0.15 && progress > 0.3 {
            score += 9.5 * dead_ratio * dead_ratio * (0.5 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: two-step lookahead — after hosting nxt, the leftover should still host the
        // current item class (item + nxt chains) or land in the tight zero-slack zone.
        if slack >= item && progress > 0.2 {
            let tail = slack - item;
            if tail <= 2.0 {
                score -= 4.0 * (1.0 - tail / 3.0) * (0.5 + progress);
            } else if tail < nxt * 0.5 {
                score += 2.0 * (1.0 - tail / (nxt * 0.5).max(1.0)) * progress;
            }
        }
        // NEW: near-exact triple-fill — residual consumed almost perfectly by nxt twice.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= 1.0 {
            score -= 7.0 * (1.0 - 0.3 * progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        // Near-miss dead space is worse when many bins could host the next item instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin two-step promise — leftover after item should host nxt
            // with the remainder landing in the tight zero-slack zone.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.3 && progress < 0.85 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= nxt {
                    let tail = fresh_left - nxt;
                    if tail <= 2.0 {
                        score -= 5.0 * (1.0 - tail / 3.0) * (0.6 + progress);
                    }
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        if nxt > pr && dead_ratio > 0.15 && progress > 0.3 {
            score += 9.5 * dead_ratio * dead_ratio * (0.5 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: mid-band slack sweet spot — residuals leaving slack in the 8..14 window
        // while plenty of hosts exist are mildly wasteful; push toward tighter hosts.
        if slack >= 8.0 && slack <= 14.0 && fitting_bins_count >= 3 && progress > 0.3 {
            score += 1.2 * (1.0 - (slack - 8.0) / 6.0) * (0.5 + progress);
        }
        // NEW: perfect double-host dividend — residual exactly two next-items wide.
        if post_residual == 2 * next_item_size {
            score -= 6.0 * (0.6 + progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        // Near-miss dead space is worse when many bins could host the next item instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: tiny orphan residuals (1..4) that nothing will ever fill — penalize harder late.
        if pr <= 4.0 && progress > 0.4 {
            score += 2.5 * (1.0 - pr / 5.0) * progress;
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: global waste ramp — quadratic pressure against large unusable residuals,
        // scaled by how many hosts already exist for the next item.
        if nxt > 0.0 && pr < nxt && fitting_bins_count >= 2 {
            score += (0.8 + 2.5 * progress) * (pr / nxt.max(1.0));
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin exact-multiple promise — leftover is an exact multiple of nxt,
            // meaning zero dead space through the lookahead horizon.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= nxt && (fresh_left % nxt) < 1.0 {
                    score -= 4.5 * (0.5 + progress);
                }
            }
            // NEW: refuse fresh bins late when a mediocre-but-usable host exists —
            // opening bins at the end almost always wastes capacity.
            if fitting_bins_count > 0 && progress > 0.8 && item <= cap * 0.5 {
                score += 10.0 * (progress - 0.8) * 5.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder: exact and near-exact leftovers are strongly rewarded.
    if post_residual == 0 {
        score -= 64.0;
    } else if post_residual <= 2 {
        score -= 31.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 43.0 + 3.3 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.8 * excess;
    }

    // Lookahead: reward leftovers that can host the next item, scaled by slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 47.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 37.0 - 0.6 * slack;
        } else {
            score -= 29.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 12.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        // Divisibility bonus: residual exactly divisible by next item promises perfect future reuse.
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        // Scarcity coupling: when few bins can host the next item, keeping hosting capacity alive is doubly valuable.
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Slack-harmony band — small positive slack under nxt keeps options open.
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        if nxt > pr && dead_ratio > 0.15 && progress > 0.3 {
            score += 9.5 * dead_ratio * dead_ratio * (0.5 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        // Near-miss dead space is worse when many bins could host the next item instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
    }

    // Fit tightness reward.
    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;

    // Open-bin consolidation pressure.
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    // Late-stage waste avoidance and dead-space control.
    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        // Residual-density control: residuals hovering near the mean are likeliest to strand.
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
    }

    // New-bin candidate handling.
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            // Mid-stream fresh-bin brake: several open bins fit but none tightly —
            // opening a new bin rarely pays unless the item is large.
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        if nxt > pr && dead_ratio > 0.15 && progress > 0.3 {
            score += 9.5 * dead_ratio * dead_ratio * (0.5 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: dead-space minimization — residual that shrinks to a tiny sliver after nxt
        // is nearly perfect compaction; reward it progressively harder mid-to-late stream.
        if slack > 0.0 && slack <= 4.0 && progress > 0.35 {
            score -= (2.0 + 3.0 * progress) * (1.0 - slack / 5.0);
        }
        // NEW: residual exactly matching the mean residual is the stream's natural rhythm —
        // such bins are easiest to fill with future items of the same distribution.
        if progress > 0.4 && mean_residual > 1.0 && slack > 0.0 {
            let rhythm = ((slack - mean_residual) / mean_residual.max(1.0)).abs();
            if rhythm < 0.15 {
                score -= 2.0 * (1.0 - rhythm / 0.15) * (0.5 + progress);
            }
        }
        // NEW: penalize leaving slack that is a near-miss for the item AFTER next
        // (two-step lookahead on the slack itself: slack - nxt barely misses typical sizes).
        if slack > nxt * 2.0 && progress > 0.5 && mean_residual > 0.0 {
            let two_step = slack - nxt;
            if two_step < mean_residual * 0.7 && mean_residual * 0.7 - two_step <= 3.0 {
                score += 2.5 * (1.0 - (mean_residual * 0.7 - two_step) / 4.0) * progress;
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        // Near-miss dead space is worse when many bins could host the next item instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: a stranded residual slightly below nxt is salvageable if a future item of
        // mean size could combine with it (residual + small item = nxt band).
        if pr >= 2.0 && pr < nxt && progress > 0.4 && mean_residual > 0.0 {
            let gap = nxt - pr;
            if gap <= mean_residual && nxt - gap >= 1.0 {
                score -= 1.8 * (1.0 - gap / nxt.max(1.0)) * (1.0 - progress);
            }
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: total dead-space budget — in the final stretch every unit of residual
        // left over counts directly against the score, scaled by how little room remains.
        if progress > 0.75 && nxt > 0.0 {
            score += (pr / nxt.max(1.0)) * (progress - 0.75) * 6.0 * if pr < nxt { 1.0 } else { 0.35 };
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin leftover rhythm — prefer fresh bins whose leftover after
            // the item lands within a tight band of the mean residual, since the
            // stream's own item sizes are the best filler for such residuals.
            if fitting_bins_count > 0 && mean_residual > 1.0 && progress > 0.3 && progress < 0.8 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 {
                    let rhythm = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                    if rhythm < 0.1 {
                        score -= 2.5 * (1.0 - rhythm / 0.1);
                    }
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder (slightly tightened: near-perfect fills are the top compaction lever).
    if post_residual == 0 {
        score -= 68.0;
    } else if post_residual <= 2 {
        score -= 34.0;
    } else if post_residual <= 5 {
        score -= 17.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 46.0 + 3.6 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 50.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 13.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 9.0;
        }
        if slack == 0.0 {
            score -= 14.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        if nxt > pr && dead_ratio > 0.15 && progress > 0.3 {
            score += 9.5 * dead_ratio * dead_ratio * (0.5 + progress);
        }
        // Dead-space surviving after the next item is pure waste (strengthened with scarcity coupling).
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += (4.0 + if fitting_bins_count <= 2 { 2.0 } else { 0.0 })
                * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.5 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.5 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: residual-homogenization — post-placement residual that matches the
        // fleet-wide mean keeps future items packable everywhere (variance control).
        if mean_residual > 0.0 && slack > 0.0 && progress > 0.25 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev < 0.15 {
                score -= 2.0 * (1.0 - dev / 0.15) * (0.5 + progress);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        // Near-miss dead space is worse when many bins could host the next item instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: residual below the smallest plausible future item is dead weight —
        // penalize proportionally to how much of the bin it wastes.
        if nxt - pr > 10.0 && dead_ratio > 0.12 && progress > 0.4 {
            score += 3.0 * dead_ratio * (1.0 + progress);
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.5 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin quadruple promise — for small next items, a leftover
            // hosting nxt four times with near-zero remainder is a compaction engine.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 && progress < 0.8 && nxt < cap * 0.15 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 4.0 * nxt && fresh_left - 4.0 * nxt <= nxt * 0.35 {
                    score -= 5.5 * (1.0 - (fresh_left - 4.0 * nxt) / (nxt * 0.35).max(1.0));
                }
            }
            // NEW: fresh-bin preference when the item barely fits anywhere — a
            // near-exact single fit elsewhere leaves a sliver; a fresh bin wastes nothing.
            if fitting_bins_count > 0 && nxt > 0.0 && item > cap * 0.7 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left < nxt * 0.4 {
                    score -= 4.0 * (1.0 - fresh_left / (nxt * 0.4).max(1.0));
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder: exact and near-exact leftovers are strongly rewarded.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    // Lookahead: reward leftovers that can host the next item, scaled by slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
