                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                } else if fresh_left > 0.0 && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 are
    // "harmonic" (likely to be exactly filled by future items).
    let post = post_residual;
    let class = post % 10;
    if class == 0 {
        score -= 6.0; // perfectly harmonic residual, very attractive
    } else if class <= 2 {
        score += 4.0; // nearly-full sliver, dead space
    } else if class >= 8 {
        score += 2.5;
    }

    // Integer-division thresholds: post_residual bucketed by quarters of capacity.
    let quarter = bin_capacity / 4;
    if post < quarter {
        score += 8.0; // tiny residual, bin almost sealed
    } else if post < 2 * quarter {
        score -= 2.0;
    } else if post < 3 * quarter {
        score -= 3.5; // sweet spot: half-filled bin
    }

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            let gap = post - next_item_size;
            if gap % 10 == 0 {
                score -= 7.0; // next item closes bin to harmonic residual
            } else if gap <= 2 {
                score -= 5.0; // next item nearly seals the bin
            } else {
                score -= gap as f64 * 0.15;
            }
        } else {
            score += 3.0; // next item won't fit here at all
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing decent fits,
    // but allow opening when all open residuals are poor (high mean residual
    // relative to item) or the fit is bad.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0;
        }
        if post_residual % 10 == 0 {
            score -= 3.0;
        }
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Progression-aware mild pressure: as stream advances, favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 1.5 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
