                }
            }
            // New: fresh-bin brake when the fresh leftover would strand just below the next item
            // while an open bin already hosts nxt tightly.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt * 0.9 {
                    score += 2.0 + 3.0 * (1.0 - fresh_left / (nxt * 0.9).max(1.0));
                }
            }
        }
    }

