            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect lookahead chain
        } else if post_residual >= next_item_size {
            // Next item fits: reward tighter leftover after the pair.
            let pair_left = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * pair_left;
        } else {
            // Next item cannot use this residual: penalize dead space growth.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Reward tight fits relative to capacity (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize residuals that become unusable slivers (below typical min size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead sliver
    }

    // Compare against mean residual: prefer using bins with more space than average.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Late in the stream, consolidation matters more: penalize spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (open_bins_count as f64).sqrt() * 0.1;

    // Mild penalty for opening a brand-new bin when other bins could fit.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (fitting_bins_count as f64);
    }

    score
}

