        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        if pr < mean_residual * 0.35 && progress > 0.4 {
            score += 4.0 ;
        }
        // Near-miss scarcity: stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress) ;
        }
        // Near-miss recovery value: a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress) ;
        }
    }

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0 ;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0 ;
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0 ;
        }
        // Endgame squeeze: near-perfect hosts late are gold.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0) ;
        }
        // Usable-capacity guard: residuals below nxt late are pure loss.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0 ;
        }
        // Exact-fill dividend.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress) ;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            if fitting_bins_count > 0 && mean_residual > 0.0 {
                let worst_case = item + mean_residual ;
                if worst_case > cap * 0.95 && progress < 0.7 {
                    score -= 6.0 ;
                }
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            // Fresh-bin chain promise: leftover hosts nxt twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // Fresh-bin dead-pocket guard: refuse fresh bins whose leftover strands
            // just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor() ;
                    let pocket = fresh_left - m * nxt ;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0 ;
                    }
                }
            }
            // Fresh-bin triple-promise: leftover fits nxt three times tightly.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0)) ;
                }
            }
            // Mean-residual alignment: keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs() ;
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2) ;
                }
            }
            // Avoid fresh bins whose leftover strands just below nxt.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // A gap is "dead" if it cannot fit the next item (or the smallest plausible item ~10).
    let min_useful = if next_item_size > 0 { next_item_size.min(60) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        // Dead space: amplify penalty quadratically relative to gap smallness.
        let gap = min_useful - post_residual;
        score += 3.0 * (gap as f64) * (gap as f64) / (min_useful as f64);
    }

    // Perfect / near-perfect fits get strong reward (subtract).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Reward tightness relative to bin size: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac;

    // Deviation from mean residual: prefer bins whose residual is close to item_size
    // (best-fit flavor), penalize bins far above/below the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Open bins pressure: with many open bins, discourage spreading; favor consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * (open_bins_count as f64) * (1.0 - 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by open-bin pressure.
        score = 55.0 + 1.2 * (open_bins_count as f64);
        // If the next item could pair with this item in a fresh bin, slight discount.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
        // Early in stream, new bins are cheaper; late, expensive.
        score += 20.0 * (1.0 - progress);
    }

    // Lookahead: if placing here leaves exactly room for the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let nxt = next_item_size as f64 ;
    let item = item_size as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let is_new_bin = bin_residual == bin_capacity ;
    let cap = bin_capacity as f64 ;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 } ;
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 } ;
    let stranded = if pr > 0.0 && pr < item_size as f64 { 1.0 } else { 0.0 } ;

    // Tight-fit ladder: exact and near-exact leftovers strongly rewarded.
    if post_residual == 0 {
        score -= 66.0 ;
    } else if post_residual <= 2 {
