    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 66.0 + 10.0 * progress;
    } else if post_residual <= 2 {
        score -= 32.0 + 6.0 * progress;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: perfect-consumption ladder — residual that the next item eats to within
        // a couple of units is worth extra, scaled by scarcity of hosts.
        if slack <= 2.0 && fitting_bins_count >= 1 {
            score -= 2.0 * (1.0 - slack / 3.0) * (1.0 + 0.5 * open_bins_count as f64 / 8.0);
        }
        // NEW: pair-promise — residual that exactly hosts nxt twice leaves zero waste.
        if post_residual == 2 * next_item_size {
            score -= 9.0 * (0.5 + progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: near-miss dead-weight — residual just below nxt is heavier waste when it
        // also exceeds the mean residual (unlikely to be consumed by small items).
        if nxt - pr <= 12.0 && pr > mean_residual * 1.15 {
            score += 3.5 * (1.0 - (nxt - pr) / 13.0) * (0.3 + progress);
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) <= 2 {
            score -= 3.0;
        }
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: early-stream fill bias — early on, prefer consuming bins whose residual
        // stays above the next item so future fits remain possible.
        if progress < 0.2 && nxt > 0.0 && pr >= nxt && (pr - nxt) as f64 > nxt * 0.5 {
            score += 2.0;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin exact-quadruple promise — a fresh leftover hosting nxt four
            // times with near-zero slack is an ideal compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 && progress < 0.85 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 4.0 * nxt && fresh_left - 4.0 * nxt <= 2.0 {
                    score -= 6.0 * (1.0 - (fresh_left - 4.0 * nxt) / 3.0);
                }
            }
            // NEW: refuse fresh bins when the item itself is small and open bins are few —
            // small items should consolidate, not spawn bins.
            if fitting_bins_count > 0 && item < cap * 0.2 && open_bins_count <= 3 && progress < 0.5 {
                score += 5.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder (refined mid-band).
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: quad-host magnet — residual fitting nxt four times tightly is a compaction chain.
        if post_residual >= 4 * next_item_size && (post_residual - 4 * next_item_size) as f64 <= nxt * 0.3 {
            score -= 4.0 * (1.0 - (post_residual - 4 * next_item_size) as f64 / (nxt * 0.3).max(1.0)) * (0.4 + progress);
        }
        // NEW: scarcity multiplier — tight slack worth more when few bins can host nxt.
        if fitting_bins_count <= 2 && slack <= nxt.max(1.0) * 0.5 {
            score -= 3.0 * (1.0 - slack / (nxt.max(1.0) * 0.5)) * (0.5 + progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: near-miss salvage — a residual just below nxt may absorb a later smaller item.
        if nxt - pr > 2.0 && nxt - pr <= 8.0 && pr <= mean_residual.max(1.0) * 0.7 {
            score -= 1.5 * (1.0 - (nxt - pr) / 9.0) * progress;
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: near-perfect endgame fill — residual consumed by nxt to within 2 units.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 2.0 && progress > 0.75 {
            score -= 3.0;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin scarcity — prefer opening a new bin when all open hosts strand nxt barely.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= nxt && (mean_residual < nxt || mean_residual - item < 0.0) {
                    score -= 2.5 * (0.5 + progress);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (too small
    // for the smallest plausible item) is heavily penalized.
    let min_item = 1.0f64;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < min_item + 9.0 {
        score += 60.0; // unusable sliver of space
    }

    // Reward tight fits: waste relative to perfect fill.
    let waste = (bin_residual - item_size) as f64;
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;
    score += waste * 0.15;

    // Non-linear penalty on large leftover gaps (dead space avoidance).
    if post_residual > 0 {
        let r = post_residual as f64 / bin_capacity as f64;
        score += r * r * 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size > post_residual {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Open-bin pressure: discourage spawning many bins early; encourage
    // consolidation when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // New-bin candidate: only attractive when current bin would leave a bad gap
    // or nothing fits well. Fresh bin starts with full residual.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; slightly penalized so real fits win,
        // but relieved when open bins are very full/fragmented.
        score += 12.0 - (mean_residual / bin_capacity as f64) * 30.0;
    } else {
        // Reward bins whose residual is near the mean (keep pool balanced).
        score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder (refined: sharper near-perfect rewards, smoother mid band).
    if post_residual == 0 {
        score -= 70.0;
    } else if post_residual <= 2 {
        score -= 34.0;
    } else if post_residual <= 5 {
        score -= 17.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 50.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 14.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.5 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: exact-multiple dividend — residual consumed exactly by nxt multiples with zero remainder.
        if nxt >= 1.0 && slack >= nxt && slack % nxt.max(1.0) == 0.0 && slack <= nxt * 4.0 {
            score -= 4.0 * (1.0 - slack / (nxt * 4.0)) * (0.4 + 0.6 * progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: dead-pair coupling — residual that pairs with another open residual to host nxt.
        if mean_residual > 0.0 && pr + mean_residual >= nxt && pr + mean_residual - nxt <= 3.0 && progress > 0.3 {
            score += 2.0 * (1.0 - (pr + mean_residual - nxt) / 4.0);
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) as f64 / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: tiny-residual sink — residuals below 4 that nxt cannot use are near-dead; prefer them late.
        if progress > 0.5 && pr > 0.0 && pr < 4.0 && nxt > pr {
            score -= 3.0 * (1.0 - pr / 4.0) * (progress - 0.5) * 2.0;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin perfect-multiple seed — leftover exactly divisible into nxt multiples.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.25 && progress < 0.8 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity));
                if fresh_left % next_item_size.max(1) == 0 && fresh_left >= next_item_size * 2 {
                    score -= if fitting_bins_count <= 2 { 5.0 } else { 2.5 };
                }
            }
            // NEW: resist fresh bins when many open bins can host nxt afterwards.
            if fitting_bins_count > 3 && nxt > 0.0 && item <= mean_residual * 1.1 && progress > 0.4 {
                score += 6.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let nxt = next_item_size as f64 ;
    let item = item_size as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let is_new_bin = bin_residual == bin_capacity ;
    let cap = bin_capacity as f64 ;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 } ;
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 } ;
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 } ;

    // Tight-fit ladder: exact and near-exact leftovers strongly rewarded.
    if post_residual == 0 {
        score -= 66.0 ;
    } else if post_residual <= 2 {
        score -= 32.0 ;
    } else if post_residual <= 5 {
        score -= 16.0 ;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64 ;
        score += 44.0 + 3.4 * gap * gap ;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0) ;
        score += 4.0 + 0.85 * excess ;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack ;
        } else {
            score -= 30.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0 ;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0 ;
        }
        // COMBINED: double-host with open-bin-aware brake (from best).
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64 ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 13.0 ;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0) ;
        }
        // Divisibility bonus: residual exactly divisible by next item promises perfect future reuse.
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0 ;
        }
        // COMBINED: near-divisible residual keeps future options open early on.
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0) ;
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0) ;
        }
        // Quasi-perfect slack band: slack just below next item size is nearly a second fit.
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt ;
            score += 5.0 * band * band * (0.5 + progress) ;
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress) ;
        }
        // COMBINED: mid-slack dead-space brake with nxt-aware softening.
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress) ;
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress) ;
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress) ;
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25) ;
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0) ;
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor() ;
            let pocket = slack - m * nxt ;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress) ;
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot consume waste space.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0) ;
        }
        // Triple-host chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress) ;
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0) ;
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 } ;
        }
        // Residual-density control: residuals near the mean are likeliest to strand.
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0)) ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0 ;
        }
        // COMBINED: sharper near-miss tiers.
        if nxt - pr <= 1.0 {
            score += 6.0 ;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 } ;
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt) ;
        }
        // Near-miss with dead space wastes proportionally more absolute space.
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0) ;
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio ;
        }
        // Near-miss gradient softened when many alternatives exist.
        if nxt - pr <= 2.0 && fitting_bins_count >= 3 {
            score -= 3.0 ;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0) ;
        }
        // Near-miss with a large residual wastes proportionally more absolute space.
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0) ;
        }
        // Near-miss scarcity coupling — almost no other bin can host the next item.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress) ;
        }
        if pr < mean_residual * 0.35 && progress > 0.4 {
            score += 4.0 ;
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress) ;
        }
    }

    // Fit tightness reward.
    let fit_ratio = item / bin_residual.max(1) as f64 ;
    score -= 6.0 * fit_ratio ;

    // Open-bin consolidation pressure.
    score += 0.3 * open_bins_count as f64 * (pr / cap) ;

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0 ;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0 ;
        }
        // COMBINED: large unusable residuals mid-stream are heavy loss.
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap) ;
        }
        // Late-stage urgency: prefer tighter residuals as stream ends.
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0 ;
        }
        // Global dead-space ratio penalty, sharpened late in the stream.
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3) ;
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0 ;
        }
        // Stranded-void gradient: residuals just below next item are costliest dead space.
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0 ;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 } ;
        }
        // COMBINED: mean-band residual harmony early.
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress) ;
        }
        // COMBINED: endgame micro-fit squeeze.
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0) ;
        }
        // Endgame squeeze: prefer bins whose residual stays usable.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0) ;
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0 ;
        }
        // COMBINED: big stranded residual with many alternatives — pull away gently.
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0 ;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress) ;
        }
        // Usable-capacity guard — residuals below the smallest plausible next item are pure loss.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0 ;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5) ;
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0) ;
            }
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            // Large item with few alternatives: prefer a fresh bin.
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            // Very large item nearly exhausts a fresh bin: pull toward it.
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0 ;
            }
            // Late stage: avoid opening a bin whose leftover can't host next item.
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // COMBINED: perfect fresh leftover with no alternatives is a strong pull.
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0 ;
            }
            // COMBINED: fresh bin when item exceeds mean residual early.
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0 ;
            }
            // Late stream: prefer keeping existing bins in play.
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0 ;
            }
            // Mid-stream fresh-bin brake.
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0 ;
            }
            // COMBINED: fresh bin when item is large and mean residual can't take it.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0 ;
            }
            // COMBINED: opening fresh when the only fitting bin would strand a near-miss.
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0 ;
                if would_strand {
                    score -= 3.0 + 4.0 * progress ;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0) ;
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0 ;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0 ;
            }
            // Many open bins with large residuals — discourage adding another.
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            // Fresh-bin divisibility promise (perfect reuse of the fresh leftover).
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0)) ;
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor() ;
                    let pocket = fresh_left - m * nxt ;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0 ;
                    }
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs() ;
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2) ;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post-residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that cannot hold the next item (lookahead-aware).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin; shrinks as stream progresses (sunk bins matter less).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 14.0 + 10.0 * (1.0 - progress);
        // If item is large, a fresh bin gives more future room.
        new_bin_cost -= 0.08 * item_size as f64;
        // If many bins are open with high mean residual, prefer reusing them.
        new_bin_cost += 0.25 * open_bins_count as f64 * (mean_residual / 100.0);
        // If no other bin fits (fitting_bins_count==1 means only this new bin), discount cost.
        if bin_residual == bin_capacity && fitting_bins_count <= 1 {
            new_bin_cost -= 30.0;
        }
        score += new_bin_cost;
    }

    // Mild pressure to consolidate into bins below mean residual (balance residuals).
    if !is_new_bin {
        let dev = (post_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 3.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: residual exactly equal to a tight multiple of nxt is a future-perfect host.
        if nxt >= 1.0 && post_residual >= 2 * next_item_size
            && post_residual % next_item_size.max(1) == 0
            && post_residual / next_item_size.max(1) <= 4 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: slack just below the next-next usable band — dead space that can never host nxt again.
        if slack > nxt && slack < 2.0 * nxt && progress > 0.5 && fitting_bins_count <= 3 {
            score += 2.0 * (1.0 - (2.0 * nxt - slack) / nxt.max(1.0)) * progress;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: stranded residual close to mean residual could merge with future small items.
        if nxt - pr > 4.0 && mean_residual > 0.0 && (pr - mean_residual).abs() < 3.0 && progress < 0.6 {
            score -= 2.5 * (1.0 - (pr - mean_residual).abs() / 3.0);
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: double-strand penalty — residual unusable by both current and next item mid-stream.
        if progress > 0.4 && nxt > 0.0 && pr < nxt && pr < item && pr > 2.0 {
            score += 3.0 * (1.0 - pr / nxt.max(1.0)) * (0.5 + progress);
        }
        // NEW: reward residuals that remain exact multiples of nxt after placement.
        if nxt >= 1.0 && post_residual >= nxt && post_residual % next_item_size.max(1) == 0 && progress > 0.3 {
            score -= 2.0 * (1.0 - progress) * (post_residual / next_item_size.max(1)).min(3) as f64;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin quadruple promise — small items tiling a fresh bin perfectly.
            if fitting_bins_count > 0 && nxt >= 1.0 && item <= cap * 0.25 && progress > 0.3 && progress < 0.8 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 4.0 * nxt && fresh_left - 4.0 * nxt <= 2.0 {
                    score -= 6.0 * (1.0 - (fresh_left - 4.0 * nxt) / 3.0);
                }
            }
            // NEW: prefer fresh bin when every open host would strand a near-miss of nxt.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= nxt && mean_residual > 0.0 && mean_residual < nxt
                    && nxt - mean_residual <= 4.0 && fresh_left % next_item_size.max(1) == 0 {
                    score -= 4.0;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: fractional dead-pocket refinement — penalize slack that leaves a remainder
        // just under the next item size even for large multiples, scaled by scarcity.
        if slack > nxt * 3.0 && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > 0.0 && pocket < nxt {
                let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
                score += (1.0 + 1.5 * progress) * scarcity * (pocket / nxt.max(1.0));
            }
        }
        // NEW: reward residuals whose slack is an exact multiple of nxt (chain-fill promise).
        if slack > nxt && nxt >= 1.0 && (slack % nxt.max(1.0)).abs() < f64::EPSILON
            && post_residual >= 2 * next_item_size {
            score -= 2.0 + 1.5 * progress;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: near-miss dead-space coupling — a stranded residual whose size is close
        // to mean residual wastes less future capacity than an outlier residual.
        if mean_residual > 0.0 && (pr - mean_residual).abs() / mean_residual.max(1.0) < 0.15 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) <= 2 {
            score -= 3.0;
        }
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: dead-space variance squeeze — residuals well above the mean that the
        // next item cannot use are progressively penalized mid-to-late stream.
        if progress > 0.4 && mean_residual > 0.0 && nxt > 0.0 && pr < nxt
            && pr > mean_residual * 1.5 {
            score += 2.5 * ((pr / mean_residual) - 1.5).min(1.5) * (progress - 0.4);
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin scarcity guard — when many bins can host the item, only
            // open a new bin if the fresh leftover promises multi-use for nxt.
            if fitting_bins_count > 3 && progress > 0.5 && nxt >= 1.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left < nxt {
                    score += 3.0 * (1.0 - fresh_left / nxt.max(1.0));
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly;

    // Reward tight fits, more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (20.0 + 30.0 * progress);

    // Last-chance bonus: strongly favor using this bin when it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving residual close to next item size mismatch; reward exact-ish match
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.3 * diff;
        // reward if next item fits exactly in the post residual
        if next_item_size as f64 <= pr {
            score -= 8.0 * (1.0 - diff / cap);
        }
    } else {
        // last item: pure tightness matters most
        score -= 10.0 * tightness;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * (open_bins_count as f64) * progress;

    // Align with mean residual: bins deviating from mean get penalized
    score += 0.2 * (pr - mean_residual).abs();

    // Discourage opening new bins unless residual is unusable
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let nxt = next_item_size as f64 ;
    let item = item_size as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let is_new_bin = bin_residual == bin_capacity ;
    let cap = bin_capacity as f64 ;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 } ;
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 } ;
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 } ;

    // Tight-fit ladder: exact and near-exact leftovers strongly rewarded.
    if post_residual == 0 {
        score -= 66.0 ;
    } else if post_residual <= 2 {
        score -= 32.0 ;
    } else if post_residual <= 5 {
        score -= 16.0 ;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64 ;
        score += 44.0 + 3.4 * gap * gap ;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0) ;
        score += 4.0 + 0.85 * excess ;
    }

    // Lookahead: reward leftovers that can host the next item, scaled by slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack ;
        } else {
            score -= 30.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0 ;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64 ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 13.0 ;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0) ;
        }
        // Divisibility bonus: residual exactly divisible by next item promises perfect future reuse.
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0 ;
        }
        // Near-divisibility bonus, stronger early when consolidation matters most.
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // Scarcity coupling: few bins can host the next item — keep hosting capacity alive.
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0) ;
        }
        // Mid-slack dead-space brake, sharpened late in the stream.
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0) ;
        }
        // Host-tightness pull: a large residual that barely hosts nxt is precious.
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0)) ;
        }
        // Quasi-perfect slack band: slack just below next item size is nearly a second fit.
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt ;
            score += 5.0 * band * band * (0.5 + progress) ;
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress) ;
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress) ;
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress) ;
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress) ;
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25) ;
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0) ;
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor() ;
            let pocket = slack - m * nxt ;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress) ;
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot consume waste space.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0) ;
        }
        // Triple-host chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress) ;
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0) ;
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 } ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0 ;
        }
        if nxt - pr <= 1.0 {
            score += 6.0 ;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 } ;
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt) ;
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0) ;
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio ;
        }
        // Near-miss dead space is worse when many bins could host the next item instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0) ;
        }
        // Near-miss with a large residual wastes proportionally more absolute space.
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0) ;
        }
        // Near-miss scarcity coupling — almost no other bin can host the next item.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress) ;
        }
        if pr < mean_residual * 0.35 && progress > 0.4 {
            score += 4.0 ;
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress) ;
        }
    }

    // Fit tightness reward.
    let fit_ratio = item / bin_residual.max(1) as f64 ;
    score -= 6.0 * fit_ratio ;

    // Open-bin consolidation pressure.
    score += 0.3 * open_bins_count as f64 * (pr / cap) ;

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0 ;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0 ;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap) ;
        }
        // Late-stage urgency: prefer tighter residuals as stream ends.
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0 ;
        }
        // Global dead-space ratio penalty, sharpened late in the stream.
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3) ;
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0 ;
        }
        // Stranded-void gradient: residuals just below next item are costliest dead space.
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0 ;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 } ;
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0) ;
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0) ;
            }
        }
        // Endgame squeeze: near the end, prefer bins whose residual stays usable.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0) ;
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0 ;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress) ;
        }
        // Usable-capacity guard — residuals below the smallest plausible next item are pure loss.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0 ;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5) ;
        }
        // Mid-band harmony — residuals near mean keep homogeneous packing options open.
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress) ;
        }
        // Large-but-stranded residual with many alternatives — deprioritize it.
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0 ;
        }
        // Awkward mid-range residual — mild penalty, sharper late.
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8 ;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5) ;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
            // Perfect-fill alternative exists: opening a new bin is clearly worse.
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0 ;
            }
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            // Large item with few alternatives: prefer a fresh bin.
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            // Very large item nearly exhausts a fresh bin: pull toward it.
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0 ;
            }
            // Late stage: avoid opening a bin whose leftover can't host next item.
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // Opening fresh bin is fine when all fitting bins would leave large dead space.
            if fitting_bins_count > 0 && mean_residual > 0.0 {
                let worst_case = item + mean_residual ;
                if worst_case > cap * 0.95 && progress < 0.7 {
                    score -= 6.0 ;
                }
            }
            // Many open bins with large residuals — discourage adding another.
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            // Mid-stream fresh-bin brake.
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0 ;
            }
            // Late stream: prefer keeping existing bins in play.
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0 ;
            }
            // Early stream: fresh bin fine when item above mean residual band.
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0 ;
            }
            // Fresh-bin divisibility promise (perfect reuse of the fresh leftover).
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0)) ;
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor() ;
                    let pocket = fresh_left - m * nxt ;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0 ;
                    }
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs() ;
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2) ;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0) ;
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0 ;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0 ;
            }
            // Fresh-bin pull when mean residual nearly matches nxt (harmonious host exists).
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5 ;
            }
            // Fresh-bin pull when mean residual cannot host the item at all.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0 ;
            }
            // Single alternative that would strand just below nxt: fresh bin is safer.
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0 ;
                if would_strand {
                    score -= 3.0 + 4.0 * progress ;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-residual (capacity fractions) ----
    // Residuals divisible into clean capacity fractions are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Harmonic classes: quarters / thirds / halves of capacity are "harmonic" residuals.
    let harmonic_bonus = if post_residual == 0 {
        -500.0 // perfect fit: overwhelmingly favored
    } else if post_residual == 50 || post_residual == 25 || post_residual == 75 {
        -40.0 // half / quarter residuals are highly reusable
    } else if post_residual % 10 == 0 {
        -15.0 // decade-aligned residuals fit typical item grids
    } else {
        0.0
    };
    score += harmonic_bonus;

    // ---- Modulo arithmetic on post_residual: prime / awkward leftovers penalized ----
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space: nothing (>=1) may still fit usefully
    }
    if post_residual > 0 && post_residual < 20 {
        // small odd non-decade leftovers are near-dead
        if post_residual % 2 == 1 && post_residual % 10 != 5 {
            score += 12.0;
        }
    }

    // ---- Integer-division threshold coupling with next_item_size ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead item fits here: strong reward, scaled by tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 45.0 + 35.0 * tight;
        } else {
            // lookahead does NOT fit: penalize if we consumed most of the bin
            // leaving a gap smaller than any plausible item
            if post_residual < next_item_size && post_residual < 25 {
                score += 20.0; // creates stranded gap
            }
        }
    } else {
        // last item of the stream: just pack as tightly as possible
        score -= 30.0;
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // this is the only bin that fits; opening a new bin is wasteful
        score -= 55.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // fresh bin baseline: attractive when current bins are crowded or fit is poor,
        // unattractive when an open bin would take the item cleanly.
        let crowded = (open_bins_count as f64).ln1p();
        score = 100.0 + 8.0 * crowded - 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin also serves the next item
        }
        if fitting_bins_count == 1 {
            score += 80.0; // don't abandon the only fitting open bin
        }
        if frac == 0.0 && item_size >= 90 {
            score -= 20.0; // huge items prefer virgin bins
        }
    }

    // ---- Mild pressure to consolidate: prefer fuller bins early-to-mid stream ----
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill_ratio = 1.0 - frac;
    score -= fill_ratio * (10.0 + 20.0 * progress);

    // ---- Prefer bins whose residual is close to the mean (balance residuals) ----
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder (refined mid-band penalty).
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        // Dead-space surviving after the next item is pure waste (sharpened).
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 5.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.5 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: exact-multiple dividend — slack that is a near-exact multiple of nxt keeps the bin fully harvestable.
        if slack > nxt && nxt >= 1.0 {
            let rem = slack % nxt.max(1.0);
            if rem < 1.0 {
                score -= 2.5 * (1.0 - progress * 0.5);
            }
        }
        // NEW: quad-host magnet — residuals hosting nxt four times tightly are rare seeds worth chasing.
        if post_residual >= 4 * next_item_size && (post_residual - 4 * next_item_size) as f64 <= nxt * 0.3 {
            score -= 4.0 * (1.0 - (post_residual - 4 * next_item_size) as f64 / (nxt * 0.3).max(1.0)) * (0.4 + progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: stranded-residual salvage — a small stranded residual is a cheaper loss than a large one.
        if progress > 0.5 && nxt - pr > 3.0 {
            score += 0.6 * pr * (progress - 0.5);
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: late-stage harvest bonus — bins whose residual exactly equals nxt become guaranteed zero-waste fills.
        if progress > 0.75 && nxt > 0.0 && pr == nxt {
            score -= 6.0;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 6;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin harvest guarantee — a fresh bin left with exactly nxt is a zero-waste seed.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.55 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if (fresh_left - nxt).abs() < 0.5 {
                    score -= 5.0 * (0.5 + progress);
                }
            }
            // NEW: fresh-bin guard — never open a new bin when a near-perfect fit already exists elsewhere.
            if fitting_bins_count > 0 && nxt > 0.0 && post_residual >= nxt
                && (post_residual - next_item_size) <= 3 {
                score += 10.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual that is tiny (can never fit a future item of size >= 1 meaningfully,
    // i.e., gaps below the typical small-item scale) is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Gaps in the "awkward" mid range (10..30) are semi-dead: few items fit.
    if post_residual >= 10 && post_residual < 30 {
        score += 18.0 * (30.0 - post_residual as f64) / 20.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0; // exact lookahead fit
        } else if post_residual >= next_item_size {
            score -= 8.0; // lookahead still fits
        } else {
            score += 12.0; // lookahead blocked by this placement
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.35 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Coupling with mean residual: penalize bins far below the mean residual
    // when the fit is loose (wasting space relative to fleet state).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio < 0.5 {
        score += 10.0 * (mean_residual - post_residual as f64).abs() * 0.05;
    } else {
        score -= 6.0 * fit_ratio; // tight fit reward
    }

    // New-bin candidate: only attractive when current fit is terrible or no good option.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // But if this item would leave an awkward gap everywhere else, new bin is fine.
        if post_residual >= 40 || (fitting_bins_count <= 1 && bin_residual < bin_capacity) {
            score -= 20.0;
        }
        // Early in stream with few bins, opening is cheaper.
        if progress < 0.2 && open_bins_count < 5 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: sub-perfect slack that strands a residual just below nxt is a near-miss trap.
        if slack > 0.0 && slack < nxt && nxt - slack <= 3.0 && progress > 0.3 {
            score += 2.0 * (1.0 - (nxt - slack) / 4.0) * (0.5 + progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: micro-residual bonus — residuals of 1-2 units after placement are effectively closed bins.
        if pr >= 1 && pr <= 2 && fitting_bins_count <= 3 {
            score -= 2.0 + 2.0 * progress;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin exact-fill promise — leftover exactly matching nxt yields a zero-waste chain.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.25 && progress < 0.8 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left % nxt.max(1.0) == 0.0 && fresh_left <= nxt * 4.0 {
                    score -= 4.5 * (1.0 - progress * 0.4);
                }
            }
            // NEW: discourage fresh bins when many open bins already sit near the mean residual band.
            if fitting_bins_count >= 3 && mean_residual > 0.0 && progress > 0.4 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band > 0.6 {
                    score += 3.0 * (band - 0.6).min(1.0);
                }
            }
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let nxt = next_item_size as f64 ;
    let item = item_size as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let is_new_bin = bin_residual == bin_capacity ;
    let cap = bin_capacity as f64 ;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 } ;
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 } ;
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 } ;

    // Tight-fit ladder: exact and near-exact leftovers strongly rewarded.
    if post_residual == 0 {
        score -= 66.0 ;
    } else if post_residual <= 2 {
        score -= 32.0 ;
    } else if post_residual <= 5 {
        score -= 16.0 ;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64 ;
        score += 44.0 + 3.4 * gap * gap ;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0) ;
        score += 4.0 + 0.85 * excess ;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack ;
        } else {
            score -= 30.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0 ;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64 ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 13.0 ;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0) ;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0 ;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0) ;
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0) ;
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0)) ;
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt ;
            score += 5.0 * band * band * (0.5 + progress) ;
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress) ;
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress) ;
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress) ;
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress) ;
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25) ;
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0) ;
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor() ;
            let pocket = slack - m * nxt ;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress) ;
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0) ;
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress) ;
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0) ;
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 } ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0 ;
        }
        if nxt - pr <= 1.0 {
            score += 6.0 ;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 } ;
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt) ;
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0) ;
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio ;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0) ;
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0) ;
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress) ;
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress) ;
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64 ;
    score -= 6.0 * fit_ratio ;
    score += 0.3 * open_bins_count as f64 * (pr / cap) ;

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0 ;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0 ;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap) ;
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0 ;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress) ;
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3) ;
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0 ;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 } ;
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0) ;
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0 ;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0 ;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8 ;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5) ;
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0) ;
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0) ;
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0 ;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5) ;
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0 ;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress) ;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // Fresh bin with an exact fill elsewhere is clearly worse.
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0 ;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0 ;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0 ;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0 ;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5 ;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0 ;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0 ;
                if would_strand {
                    score -= 3.0 + 4.0 * progress ;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0) ;
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0 ;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0 ;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor() ;
                    let pocket = fresh_left - m * nxt ;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0 ;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0)) ;
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs() ;
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2) ;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            // next item fits exactly into leftover: strong reward, tighter match = better
            let diff = pr - nxt;
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space, worse when pr < capacity/2
            let half = bin_capacity as f64 / 2.0;
            if pr < half {
                score += 15.0 * (1.0 - pr / half);
            }
        }
    } else {
        // Last item: prefer minimal leftover
        score += 0.0;
    }

    // Relative-to-mean residual: prefer bins already below average residual (denser bins)
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / bin_capacity as f64;
        score += 20.0 * rel;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are terrible
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 10.0;
        // less costly to open a new bin late in the stream or with many open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress;
        // if item leaves exactly post_residual 0, perfect fresh-bin fill
        if post_residual == 0 {
            score -= 50.0;
        }
        // discourage new bin if it wastes more than half capacity immediately
        if post_residual > bin_capacity / 2 {
            score += 25.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Slight preference for tighter bins overall
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: quad-host promise — residual hosting nxt four times tightly is a deep compaction seed.
        if post_residual >= 4 * next_item_size && (post_residual - 4 * next_item_size) as f64 <= nxt * 0.3 {
            score -= 4.0 * (1.0 - (post_residual - 4 * next_item_size) as f64 / (nxt * 0.3).max(1.0)) * (0.4 + progress);
        }
        // NEW: exact-multiple dividend — slack that is a whole multiple of nxt leaves zero future waste.
        if slack >= nxt && nxt >= 1.0 && slack % nxt.max(1.0) == 0.0 {
            score -= 2.5 * (1.0 - progress * 0.5);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: stranding severity scaling — bigger near-miss gaps cost more when the stream is long.
        if nxt - pr > 10.0 && progress > 0.5 {
            score += 0.6 * ((nxt - pr) - 10.0).min(15.0) * progress;
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: small-residual harvest — tiny leftovers become free space for small items late.
        if progress > 0.65 && pr >= 1.0 && pr <= nxt * 0.35 && nxt >= 2.0 {
            score -= 2.0 * (1.0 - pr / (nxt * 0.35)) * (progress - 0.65) * 2.0;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin zero-waste target — favor openings whose leftover is an exact multiple of nxt.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.3 && progress < 0.8 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= nxt && fresh_left % nxt.max(1.0) == 0.0 {
                    score -= 3.0 * (1.0 - progress * 0.4);
                }
            }
            // NEW: fresh-bin pull when no open bin can even host the item tightly and the mean residual
            // would be shattered into a large dead chunk by this placement.
            if fitting_bins_count > 0 && progress > 0.55 && mean_residual > 0.0 {
                let after = (mean_residual - item).max(0.0);
                if after > 0.0 && after < nxt && nxt - after <= 4.0 {
                    score += 5.0 * (1.0 - (nxt - after) / 5.0);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring post_residual amplifies penalty for wasteful placements.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Reward leaving a residual that exactly matches the lookahead item (perfect chain).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (1.0 - gap / bin_capacity as f64) * 12.0;
        // Penalize residuals too small for the next item (dead space).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.8;

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Time horizon: early in stream, be conservative (prefer new bins for flexibility);
    // late in stream, fill existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;
    score += (1.0 - progress) * 5.0;

    // Prefer bins with small current residual (best-fit flavor) beyond raw post_residual.
    score += (bin_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let nxt = next_item_size as f64 ;
    let item = item_size as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let is_new_bin = bin_residual == bin_capacity ;
    let cap = bin_capacity as f64 ;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 } ;
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 } ;
    let stranded = if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 } ;

    // Tight-fit ladder: exact and near-exact leftovers strongly rewarded.
    if post_residual == 0 {
        score -= 66.0 ;
    } else if post_residual <= 2 {
        score -= 32.0 ;
    } else if post_residual <= 5 {
        score -= 16.0 ;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64 ;
        score += 44.0 + 3.4 * gap * gap ;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0) ;
        score += 4.0 + 0.85 * excess ;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack ;
        } else {
            score -= 30.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0 ;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64 ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 13.0 ;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0) ;
        }
        // Divisibility bonus: residual exactly divisible by next item promises perfect future reuse.
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0 ;
        }
        // Near-divisible residual is still a good future host.
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0) ;
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0) ;
        }
        // Quasi-perfect slack band: slack just below next item size is nearly a second fit.
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt ;
            score += 5.0 * band * band * (0.5 + progress) ;
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress) ;
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress) ;
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress) ;
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress) ;
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25) ;
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0) ;
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor() ;
            let pocket = slack - m * nxt ;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress) ;
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot consume waste space.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0) ;
        }
        // Triple-host chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress) ;
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0) ;
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 } ;
        }
        // Residual-density control: residuals near the mean are likeliest to strand.
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0)) ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0 ;
        }
        if nxt - pr <= 1.0 {
            score += 6.0 ;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 } ;
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt) ;
        }
        // Near-miss with a large residual wastes proportionally more absolute space.
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0) ;
        }
        // Near-miss scarcity coupling — almost no other bin can host the next item.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress) ;
        }
        if pr < mean_residual * 0.35 && progress > 0.4 {
            score += 4.0 ;
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress) ;
        }
    }

    // Fit tightness reward.
    let fit_ratio = item / bin_residual.max(1) as f64 ;
    score -= 6.0 * fit_ratio ;

    // Open-bin consolidation pressure.
    score += 0.3 * open_bins_count as f64 * (pr / cap) ;

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0 ;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0 ;
        }
        // Late-stage urgency: prefer tighter residuals as stream ends.
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0 ;
        }
        // Global dead-space ratio penalty, sharpened late in the stream.
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3) ;
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0 ;
        }
        if progress > 0.85 && post_residual <= 2 {
            score -= 3.0 ;
        }
        // Stranded-void gradient: residuals just below next item are costliest dead space.
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0 ;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 } ;
        }
        // Endgame squeeze: near the end, prefer bins whose residual stays usable.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0) ;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress) ;
        }
        // Usable-capacity guard — residuals below the smallest plausible next item are pure loss.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0 ;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5) ;
        }
        // Mid-stream consolidation: penalize residuals far from the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0) ;
            }
        }
        // Small-residual endgame dividend: tiny leftovers are near-certain future fills.
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0) ;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            // Large item with few alternatives: prefer a fresh bin.
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            // Very large item nearly exhausts a fresh bin: pull toward it.
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0 ;
            }
            // Late stage: avoid opening a bin whose leftover can't host next item.
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // Opening fresh bin is fine when all fitting bins would leave large dead space.
            if fitting_bins_count > 0 && mean_residual > 0.0 {
                let worst_case = item + mean_residual ;
                if worst_case > cap * 0.95 && progress < 0.7 {
                    score -= 6.0 ;
                }
            }
            // Many open bins with large residuals — discourage adding another.
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            // Mid-stream fresh-bin brake.
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0 ;
            }
            // Late stream: prefer keeping existing bins in play.
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0 ;
            }
            // Fresh-bin divisibility promise (perfect reuse of the fresh leftover).
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0)) ;
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor() ;
                    let pocket = fresh_left - m * nxt ;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0 ;
                    }
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs() ;
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2) ;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0) ;
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0 ;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) as f64 > nxt.max(20.0) * 2.0 {
                score -= 5.0 ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: penalize large residuals super-linearly,
    // more so late in the stream (waste matters more as stream matures).
    let norm_pr = pr / cap;
    let waste_penalty = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 30.0 * waste_penalty;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tightness = (-4.0 * norm_pr).exp();
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead coupling: bonus if next item fits into the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - 0.5 * progress);
        } else {
            // Penalize residuals that strand just above the next item size.
            let gap = (pr - nxt) / cap;
            score += 8.0 * (-20.0 * gap).exp();
        }
    }

    // New-bin candidate: penalize mildly, less so early or when open bins are full-ish.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 20.0 - 10.0 * progress - 6.0 * avg_fill;
    } else {
        // Favor bins whose residual is below the mean residual (denser bins).
        let denseness = ((mean_residual - pr) / cap).clamp(-1.0, 1.0);
        score -= 5.0 * denseness;
    }

    // Mild preference to keep the number of open bins in check late in stream.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);

    // Cubic interaction: residual^3 scaled by progress for late-stage waste aversion.
    score += 4.0 * norm_pr * norm_pr * norm_pr * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
