                }
            }
            // Fresh-bin triple-promise — compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0)) ;
                }
            }
            // Mean-residual alignment for fresh leftovers.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs() ;
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2) ;
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor() ;
                    let pocket = fresh_left - m * nxt ;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0 ;
                    }
                }
            }
            // Fresh-bin pull for large items that would strand a big dead chunk elsewhere.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0) ;
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0 ;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: residue classes modulo 10
    let item_class = item_size % 10;
    let post_class = post_residual % 10;

    // Reward placements whose post-residual belongs to a "harmonic" class
    // that is likely to be filled by the next item (modulo alignment).
    if next_item_size > 0 {
        let next_class = next_item_size % 10;
        if post_residual >= next_item_size {
            // next item fits exactly in the post-residual class
            if post_residual == next_item_size {
                score -= 40.0;
            } else if post_class == next_class {
                score -= 12.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    } else {
        // last item: prefer minimal leftover
        score -= 5.0;
    }

    // Penalize post-residuals in "awkward" classes (small unusable slivers)
    let awkward = matches!(post_class, 1 | 2 | 3 | 4 | 5) && post_residual < 10;
    if awkward {
        score += 15.0;
    }

    // Fraction-of-capacity harmonics: prefer post_residual near multiples of 25
    let quarter = (post_residual as f64 / 25.0).round() * 25.0;
    let deviation = (post_residual as f64 - quarter).abs();
    score += deviation * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (mean_residual / cap + 1.0);
        let bonus = 20.0 * progress - crowding * 2.0;
        // Base penalty so new bins are opened only when residuals are fragmented
        score += 45.0 - bonus;
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Prefer tight fits overall
    score -= (item_size as f64 / cap) * 8.0;

    // Slight preference for bins with residuals above the mean (balance)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

