        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: residual-entropy damping — residuals whose slack is a poor multiple of nxt
        // but still above nxt*2 lose compaction value; push selection toward tighter hosts.
        if slack > nxt * 2.0 && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let rem = slack - m * nxt;
            if rem > 0.5 && rem < nxt - 0.5 && m <= 6.0 {
                score += 2.0 * (1.0 - rem / nxt.max(1.0)) * (0.3 + 0.7 * progress);
            }
        }
        // NEW: scarcity-aware tightness — when few bins can host the next item,
        // a residual that hosts it exactly is worth much more.
        if slack == 0.0 && fitting_bins_count <= 2 && progress > 0.2 {
            score -= 6.0 * (1.0 - progress) + 3.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: stranded-small guard — tiny residuals below nxt that no future small item
        // will likely reclaim are pure dead weight; penalize proportionally to pr/nxt.
        if progress > 0.5 && pr < nxt * 0.4 && pr > 0.0 {
            score += 2.5 * (1.0 - pr / (nxt * 0.4).max(1.0)) * (progress - 0.5) * 2.0;
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: dead-space compounding — residuals above half capacity that cannot host
        // the next item compound waste; escalate penalty with progress.
        if nxt > 0.0 && pr < nxt && waste_ratio > 0.5 && progress > 0.3 {
            score += (3.0 + 5.0 * progress) * (waste_ratio - 0.5) * 2.0;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin quadruple promise — a fresh leftover fitting nxt four times
            // tightly is a near-zero-waste seed; reward it strongly mid-stream.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 && progress < 0.85 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 4.0 * nxt && fresh_left - 4.0 * nxt <= nxt * 0.4 {
                    score -= 6.0 * (1.0 - (fresh_left - 4.0 * nxt) / (nxt * 0.4).max(1.0));
                }
            }
            // NEW: fresh-bin waste floor — if no open bin can host the item and the fresh
            // leftover would strand more than mean_residual, prefer consolidating instead.
            if fitting_bins_count > 0 && progress > 0.6 && mean_residual > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > mean_residual * 1.5 && fresh_left < nxt {
                    score += 5.0;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Reward exact fit strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space penalty scaled by wasted capacity relative to next item.
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin unless it's genuinely useful.
    if bin_residual == bin_capacity {
        // Late in stream or many open bins: prefer consolidation.
        score += 15.0 * progress + 2.0 * open_bins_count as f64;
        // But if mean residual is high (fragmented bins), a fresh bin may be fine.
        score -= mean_residual * 0.15;
        // If next item is huge and this bin would be nearly emptied by it, favor new bin.
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 * 9 / 10 {
            score -= 20.0;
        }
    }

    // Slight preference for bins below mean residual (consolidating emptier bins).
    score += (bin_residual as f64 - mean_residual) * 0.08;

    // Early stream: be a bit more willing to open bins (explore); later: pack tight.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let nxt = next_item_size as f64 ;
    let item = item_size as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let is_new_bin = bin_residual == bin_capacity ;
    let cap = bin_capacity as f64 ;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 } ;
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 } ;
    let stranded = if pr > 0.0 && pr < item_size as f64 { 1.0 } else { 0.0 } ;

    // Tight-fit ladder: exact and near-exact leftovers strongly rewarded.
    if post_residual == 0 {
        score -= 66.0 ;
    } else if post_residual <= 2 {
        score -= 32.0 ;
    } else if post_residual <= 5 {
        score -= 16.0 ;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64 ;
        score += 44.0 + 3.4 * gap * gap ;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0) ;
        score += 4.0 + 0.85 * excess ;
    }

    // Lookahead: reward leftovers that can host the next item, scaled by slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack ;
        } else {
            score -= 30.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0 ;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64 ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 13.0 ;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0) ;
        }
        // Divisibility bonus: residual exactly divisible by next item promises perfect future reuse.
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0 ;
        }
        // Near-divisibility bonus, stronger early when consolidation matters most.
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        // Scarcity coupling: few bins can host the next item — keep hosting capacity alive.
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0) ;
        }
        // Mid-slack dead-space brake, sharpened late in the stream.
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0) ;
        }
        // Mean-residual pull: residuals above mean with slack below nxt are promising hosts.
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0)) ;
        }
        // Quasi-perfect slack band: slack just below next item size is nearly a second fit.
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt ;
            score += 5.0 * band * band * (0.5 + progress) ;
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress) ;
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress) ;
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress) ;
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress) ;
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25) ;
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0) ;
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor() ;
            let pocket = slack - m * nxt ;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress) ;
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot consume waste space.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0) ;
        }
        // Triple-host chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress) ;
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0) ;
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 } ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0 ;
        }
        if nxt - pr <= 1.0 {
            score += 6.0 ;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 } ;
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt) ;
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0) ;
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio ;
        }
        // Near-miss dead space is worse when many bins could host the next item instead.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0) ;
        }
        // Near-miss with a large residual wastes proportionally more absolute space.
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0) ;
        }
        // Near-miss scarcity coupling — almost no other bin can host the next item.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress) ;
        }
        if pr < mean_residual * 0.35 && progress > 0.4 {
            score += 4.0 ;
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress) ;
        }
    }

    // Fit tightness reward.
    let fit_ratio = item / bin_residual.max(1) as f64 ;
    score -= 6.0 * fit_ratio ;

    // Open-bin consolidation pressure.
    score += 0.3 * open_bins_count as f64 * (pr / cap) ;

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0 ;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0 ;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap) ;
        }
        // Late-stage urgency: prefer tighter residuals as stream ends.
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0 ;
        }
        // Global dead-space ratio penalty, sharpened late in the stream.
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3) ;
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0 ;
        }
        // Stranded-void gradient: residuals just below next item are costliest dead space.
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0 ;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 } ;
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0) ;
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0) ;
            }
        }
        // Endgame squeeze: near the end, prefer bins whose residual stays usable.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0) ;
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0 ;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress) ;
        }
        // Usable-capacity guard — residuals below the smallest plausible next item are pure loss.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0 ;
        }
        // Mean-band homing — residuals near mean residual are predictable hosts.
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress) ;
        }
        // Large stranded residual with many alternatives — mild pull away.
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0 ;
        }
        // Mid-band residual gradient — small-but-not-tiny residuals are semi-usable.
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8 ;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5) ;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5) ;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            // Large item with few alternatives: prefer a fresh bin.
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            // Very large item nearly exhausts a fresh bin: pull toward it.
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0 ;
            }
            // Late stage: avoid opening a bin whose leftover can't host next item.
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // Perfect-fill promise: fresh bin leaves nothing at all when an exact-fit
            // residual exists elsewhere is handled above; here reward a fresh bin
            // only when no residual at all can be preserved.
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0 ;
            }
            // Early consolidation: fresh bin fine when item exceeds mean residual.
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0 ;
            }
            // Opening fresh bin is fine when all fitting bins would leave large dead space.
            if fitting_bins_count > 0 && mean_residual > 0.0 {
                let worst_case = item + mean_residual ;
                if worst_case > cap * 0.95 && progress < 0.7 {
                    score -= 6.0 ;
                }
            }
            // Many open bins with large residuals — discourage adding another.
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            // Mid-stream fresh-bin brake.
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0 ;
            }
            // Late stream: prefer keeping existing bins in play.
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0 ;
            }
            // Fresh-bin divisibility promise (perfect reuse of the fresh leftover).
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0)) ;
                }
            }
            // Fresh-bin dead-pocket guard — refuse fresh bins whose leftover
            // strands just under a small multiple of the next item.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor() ;
                    let pocket = fresh_left - m * nxt ;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0 ;
                    }
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs() ;
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2) ;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0) ;
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0 ;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0 ;
            }
            // Single-host stranding: only one fitting bin and it nearly hosts nxt.
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0 ;
                if would_strand {
                    score -= 3.0 + 4.0 * progress ;
                }
            }
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let nxt = next_item_size as f64 ;
    let item = item_size as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let is_new_bin = bin_residual == bin_capacity ;
    let cap = bin_capacity as f64 ;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 } ;
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 } ;
    // Mutated: stranded now also flags residuals that cannot host the next item (lookahead-coupled).
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 } ;

    // Tight-fit ladder: exact and near-exact leftovers strongly rewarded.
    if post_residual == 0 {
        score -= 66.0 ;
    } else if post_residual <= 2 {
        score -= 32.0 ;
    } else if post_residual <= 5 {
        score -= 16.0 ;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64 ;
        score += 44.0 + 3.4 * gap * gap ;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0) ;
        score += 4.0 + 0.85 * excess ;
    }

    // Lookahead: reward leftovers that can host the next item, scaled by slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack ;
        } else {
            score -= 30.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0 ;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64 ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 13.0 ;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0) ;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0 ;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0) ;
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0) ;
        }
        // Borrowed: high residual with sub-nxt slack is a strong future host.
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0)) ;
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt ;
            score += 5.0 * band * band * (0.5 + progress) ;
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress) ;
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress) ;
        }
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress) ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress) ;
        }
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25) ;
            }
        }
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0) ;
        }
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor() ;
            let pocket = slack - m * nxt ;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress) ;
            }
        }
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0) ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress) ;
        }
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0) ;
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 } ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0 ;
        }
        if nxt - pr <= 1.0 {
            score += 6.0 ;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 } ;
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt) ;
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0) ;
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio ;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0) ;
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0) ;
        }
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress) ;
        }
        if pr < mean_residual * 0.35 && progress > 0.4 {
            score += 4.0 ;
        }
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress) ;
        }
    }

    // Fit tightness reward.
    let fit_ratio = item / bin_residual.max(1) as f64 ;
    score -= 6.0 * fit_ratio ;

    // Open-bin consolidation pressure.
    score += 0.3 * open_bins_count as f64 * (pr / cap) ;

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0 ;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0 ;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap) ;
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0 ;
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3) ;
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0 ;
        }
        // Borrowed: mean-band harmony bonus, early-weighted.
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress) ;
        }
        // Stranded-void gradient: residuals just below next item are costliest dead space.
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0 ;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 } ;
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0) ;
        }
        // Borrowed: large-but-stranded residual with many alternatives is less costly.
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0 ;
        }
        // Borrowed: soft gradient on the 7-15 residual band, sharpened late.
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8 ;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5) ;
        }
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs() ;
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0) ;
            }
        }
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0) ;
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0 ;
        }
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress) ;
        }
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0 ;
        }
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5) ;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            // Borrowed: a fresh bin with an exact-fit existing alternative is heavily penalized.
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0 ;
            }
            // Borrowed: fresh bin promising when item aligns with mean residual.
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0 ;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0 ;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0 ;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0 ;
            }
            // Borrowed: fresh bin when residual structure mirrors nxt is promising.
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5 ;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            // Borrowed: large item late with residual smaller than item — fresh bin wins.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0 ;
            }
            // Borrowed: single fitting bin that would strand a near-miss — fresh bin preferred.
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0 ;
                if would_strand {
                    score -= 3.0 + 4.0 * progress ;
                }
            }
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0) ;
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0 ;
                }
            }
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0 ;
            }
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor() ;
                    let pocket = fresh_left - m * nxt ;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0 ;
                    }
                }
            }
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0)) ;
                }
            }
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs() ;
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2) ;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr + 0.6 * norm_pr * norm_pr);

    // Penalize large dead space more as stream progresses
    score += 25.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) strongly
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.4 + 0.6 * progress);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: favor bins whose post_residual can still hold the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - progress);
    }

    // New-bin candidate: prefer it only late in stream or when fit is very poor
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * progress + 0.05 * mean_residual * (1.0 - progress);
    }

    // Slight preference for bins deviating favorably from mean residual
    score += 0.1 * (mean_residual - bin_residual as f64).abs() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder (refined: steeper cliff below 16).
    if post_residual == 0 {
        score -= 68.0;
    } else if post_residual <= 2 {
        score -= 34.0;
    } else if post_residual <= 5 {
        score -= 17.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 46.0 + 3.6 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.9 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 50.0 - 1.6 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 20.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 14.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: residual-divisibility dividend — leftover exactly divisible by nxt keeps hosting forever.
        if nxt >= 1.0 && slack > nxt * 2.0 && (slack as u32) % next_item_size.max(1) == 0 {
            score -= 4.0 * (1.0 - progress * 0.5);
        }
        // NEW: dead-space after nxt placement vs. mean — if leftover exceeds mean residual mid-stream, it's a stranded island.
        if progress > 0.4 && mean_residual > 0.0 && slack > mean_residual * 1.5 && slack > nxt {
            score += 2.0 * (slack / mean_residual.max(1.0) - 1.5).min(2.0) * (0.5 + progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: tiny stranded residual that can never host a future item — hard penalty grows with progress.
        if progress > 0.5 && pr < nxt * 0.3 && pr > 0.0 {
            score += 3.0 * (1.0 - pr / nxt.max(1.0)) * (progress - 0.5) * 2.0;
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: dead-space tax scaled by how little of the bin the whole stream has consumed.
        if progress > 0.6 && dead_ratio > 0.15 && nxt > 0.0 && pr < nxt {
            score += 5.0 * dead_ratio * (progress - 0.6) * 3.0;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin endgame promise — leftover after placing item still hosts nxt late in the stream.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.7 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= nxt && fresh_left - nxt <= 2.0 {
                    score -= 5.0 * (1.0 - (fresh_left - nxt) / 3.0);
                }
            }
            // NEW: prefer fresh bin when all fitting bins would leave dead chunks below nxt.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.55 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let best_existing = mean_residual;
                if best_existing > 0.0 && best_existing >= item
                    && (best_existing - item) < nxt * 0.4 && fresh_left >= nxt * 0.9 {
                    score -= 4.0 * (1.0 - progress);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a non-linear boost.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Harmonic classes: penalize post_residual that is unusable for common size classes.
    // Sizes 1..100; dead space = post_residual < smallest plausible next item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // nearly dead space
    }

    // Modulo / integer-division thresholds on post_residual: residual classes
    // divisible into chunks of 25 or 20 are more reusable.
    let r = post_residual;
    if r >= 20 && (r % 25 == 0 || r % 20 == 0) {
        score -= 8.0;
    }
    if r > 0 && r < 20 && r % 10 != 0 {
        score += 10.0; // awkward remainder class
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin if this fit is poor
    // and the next item is large.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 40;
        let next_big = next_item_size > bin_residual && next_item_size > 50;
        if poor_fit || next_big {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        if diff <= 5 {
            score -= 18.0;
        } else if diff <= 15 {
            score -= 8.0;
        }
    }

    // Early in the stream, keep bins open with balanced residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        let balance = (bin_residual as f64 - mean_residual).abs();
        score += balance * 0.15;
    }

    // Penalize many open bins slightly to encourage consolidation.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: residual-harvest gradient — after placing nxt, how much of the leftover can the
        // mean-sized future item consume? Leftovers far below mean_residual are stranded capital.
        if progress > 0.4 && mean_residual > 0.0 && slack > 0.0 {
            let harvest = (slack / mean_residual.max(1.0)).floor();
            let leftover = slack - harvest * mean_residual;
            if harvest == 0.0 && leftover < mean_residual {
                score += 2.0 * (1.0 - leftover / mean_residual.max(1.0)) * (0.5 + progress);
            } else if harvest >= 1.0 && leftover <= 2.0 {
                score -= 2.0 * (1.0 - leftover / 3.0) * (0.4 + progress);
            }
        }
        // NEW: exact-multiple dividend — residual that nxt consumes to near-zero is compaction gold.
        if slack > 0.0 && slack <= 1.0 && progress > 0.3 {
            score -= 6.0 * (1.0 - progress * 0.3);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: salvage forecast — a stranded residual close to mean_residual may absorb a future
        // mean item, so soften the penalty when the stream is homogeneous.
        if mean_residual > 0.0 && pr >= mean_residual * 0.85 && pr < mean_residual * 1.15 && progress < 0.8 {
            score -= 3.0 * (1.0 - ((pr - mean_residual) / mean_residual.max(1.0)).abs() / 0.15).max(0.0);
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: cumulative-waste gradient — penalize residuals that are neither near-zero nor
        // nxt-consumable, scaled by how many other bins could absorb this item instead.
        if progress > 0.3 && nxt > 0.0 {
            let absorbable = pr >= nxt && (pr - nxt) <= nxt as f64 * 0.35;
            if !absorbable && pr > 6.0 {
                let severity = if pr < nxt { (nxt - pr) / nxt.max(1.0) } else { ((pr - nxt) % nxt.max(1.0)) / nxt.max(1.0) };
                score += (1.0 + 2.5 * progress) * severity * if fitting_bins_count > 1 { 1.0 } else { 0.4 };
            }
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin mean-harvest promise — a fresh leftover that the mean-sized future
            // item consumes almost exactly is preferred over one leaving odd pockets.
            if fitting_bins_count > 0 && mean_residual > 0.5 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let k = (fresh_left / mean_residual).floor();
                let rem = fresh_left - k * mean_residual;
                if k >= 1.0 && rem <= 2.0 {
                    score -= 4.0 * (1.0 - rem / 3.0) * (0.5 + progress);
                } else if k >= 1.0 && rem > mean_residual - 3.0 {
                    score += 3.0 * (rem - (mean_residual - 3.0)) / 3.0 * (0.4 + progress);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals that are too small to hold any plausible item are "dead space".
    // Penalize them heavily with a quadratic term in the dead zone.
    let dead_zone: f64 = 9.0; // smallest item could be ~1; gaps below this are near-unusable
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        let depth = dead_zone - post_residual as f64;
        score += 40.0 + 8.0 * depth * depth;
    }

    // Reward very tight fits (post_residual near zero but not creating tiny gap).
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual as f64 >= dead_zone {
        // usable gap: mild reward proportional to how well the item matched
        score -= 5.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // --- Lookahead coupling: prefer bins whose leftover can host the next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-friendly: leftover fits next item -> reward
            score -= 10.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else if post_residual > 0 {
            // leftover cannot host next item -> mild penalty, scaled by how close
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 * (1.0 - miss / next_item_size as f64);
        }
    }

    // --- Last-chance pressure: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current bins are badly fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Base cost of a fresh bin (wasteful unless open bins are poor hosts)
        score += 20.0;
        // If many open bins already fit the item, opening a new one is bad.
        score += 6.0 * fitting_bins_count as f64;
        // If open bins are nearly full on average, a new bin is more acceptable.
        score -= 0.3 * mean_residual;
        // Large items near capacity justify a fresh bin more.
        score -= 0.15 * item_size as f64;
        let _ = fragmentation;
    } else {
        // Prefer using already-open bins: mild pressure against proliferation.
        score += 0.05 * open_bins_count as f64;
        // Prefer bins whose residual is closest to the item (best fit flavor).
        score += 0.2 * (bin_residual - item_size) as f64;
    }

    // --- Stream progression: late in the stream, consolidate more aggressively ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: residual that survives as an exact multiple of nxt is a compaction seed — reward it.
        if slack > 0.0 && nxt >= 1.0 && (post_residual as f64 / nxt).fract() < 1e-6 && post_residual as f64 <= cap * 0.5 {
            score -= 4.0 * (1.0 - progress * 0.5);
        }
        // NEW: penalize slack that is a near-miss for the next-next typical size band.
        if slack > nxt && nxt >= 1.0 && mean_residual > 0.0 {
            let gap_to_mean = (slack - mean_residual).abs();
            if gap_to_mean < 2.0 && fitting_bins_count > 1 {
                score -= 2.0 * (1.0 - gap_to_mean / 2.0);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: a residual just below nxt that equals a small item's likely size — keep it cheap to strand.
        if pr >= 1.0 && pr <= 4.0 && nxt - pr > 4.0 && progress < 0.6 {
            score -= 2.5;
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: residual that can host nxt plus mean_residual is doubly usable — reward.
        if nxt >= 1.0 && mean_residual > 0.0 && pr >= nxt + mean_residual && pr - (nxt + mean_residual) <= 3.0 {
            score -= 3.0 * (1.0 - (pr - (nxt + mean_residual)) / 4.0);
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin exact-fill promise — leftover exactly equals nxt, a guaranteed perfect fill.
            if fitting_bins_count > 0 && nxt >= 1.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt && (fresh_left / nxt).fract() < 1e-6 && fresh_left <= cap * 0.5 {
                    score -= 4.0 * (1.0 - progress * 0.4);
                }
            }
            // NEW: fresh-bin anti-waste — avoid opening when the leftover would be a tiny unusable sliver.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < 3.0 {
                    score += 3.0;
                }
            }
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let nxt = next_item_size as f64 ;
    let item = item_size as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let is_new_bin = bin_residual == bin_capacity ;
    let cap = bin_capacity as f64 ;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 } ;
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 } ;
    let stranded = if pr > 0.0 && pr < item_size as f64 { 1.0 } else { 0.0 } ;

    // Tight-fit ladder: exact and near-exact leftovers strongly rewarded.
    if post_residual == 0 {
        score -= 66.0 ;
    } else if post_residual <= 2 {
        score -= 32.0 ;
    } else if post_residual <= 5 {
        score -= 16.0 ;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64 ;
        score += 44.0 + 3.4 * gap * gap ;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0) ;
        score += 4.0 + 0.85 * excess ;
    }

    // Lookahead: reward leftovers that can host the next item, scaled by slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack ;
        } else {
            score -= 30.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0 ;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0 ;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64 ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 13.0 ;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0) ;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0 ;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress) ;
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0) ;
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0) ;
        }
        // High residual with tight next-fit: keep it as a host (borrowed from best).
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0)) ;
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt ;
            score += 5.0 * band * band * (0.5 + progress) ;
