            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs() ;
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2) ;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 };
    let stranded = if pr > 0.0 && pr < item { 0.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 };

    // Tight-fit ladder.
    if post_residual == 0 {
        score -= 66.0;
    } else if post_residual <= 2 {
        score -= 32.0;
    } else if post_residual <= 5 {
        score -= 16.0;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64;
        score += 44.0 + 3.4 * gap * gap;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0);
        score += 4.0 + 0.85 * excess;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 48.0 - 1.5 * slack;
        } else if slack < 12.0 {
            score -= 38.0 - 0.6 * slack;
        } else {
            score -= 30.0 - 0.15 * slack;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 18.0;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) <= 2 {
            score -= 12.0;
        }
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt * 0.5 {
            score -= 4.0 + 0.05 * open_bins_count as f64;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) <= 2 {
            score -= 8.0;
        }
        if slack == 0.0 {
            score -= 13.0;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0);
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) == 0 && post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        if nxt > 0.0 && post_residual % next_item_size.max(1) != 0
            && post_residual % next_item_size.max(1) <= 2 {
            score -= 4.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 && slack <= 4.0 {
            score -= 6.0 * (1.0 - slack / 5.0);
        }
        if slack > 12.0 && slack < nxt * 2.0 {
            score += (0.25 + 0.2 * progress) * (slack - 12.0);
        }
        if pr > mean_residual * 1.2 && slack < nxt {
            score -= 4.0 * (1.0 - slack / nxt.max(1.0));
        }
        if slack > 0.0 && nxt > 0.0 && slack < nxt {
            let band = 1.0 - slack / nxt;
            score += 5.0 * band * band * (0.5 + progress);
        }
        if slack > 0.0 && slack <= 2.0 {
            score -= 3.0 * (1.0 - slack / 3.0) * (1.0 + progress);
        }
        if slack > 6.0 && slack < 14.0 && nxt > slack {
            score += 2.0 * (slack - 6.0) * (0.4 + progress);
        }
        // Dead-space surviving after the next item is pure waste.
        if slack > 0.0 && slack < nxt && dead_ratio > 0.1 {
            score += 4.0 * dead_ratio * (1.0 + progress);
        }
        // Chain-lookahead — reward residuals able to host next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress);
        }
        // Mean-band harmony — residuals close to mean residual keep future options open.
        if progress > 0.3 && mean_residual > 0.0 && slack >= nxt {
            let band = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if band < 0.25 {
                score -= 2.5 * (1.0 - band / 0.25);
            }
        }
        // Slack-harmonic — slack leaving a second near-perfect host is doubly valuable.
        if slack > nxt && nxt >= 1.0 && slack % nxt.max(1.0) <= 2.0 && fitting_bins_count <= 3 {
            score -= 3.5 * (1.0 - (slack % nxt.max(1.0)) / 3.0);
        }
        // Dead-pocket gradient — penalize slack sitting just below a small multiple of nxt.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor();
            let pocket = slack - m * nxt;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress);
            }
        }
        // Absolute dead-space floor — large residuals the next item cannot fully consume.
        if slack > nxt * 1.5 && dead_ratio > 0.2 {
            score += (2.0 + 3.0 * progress) * dead_ratio * (slack / nxt.max(1.0) - 1.5).min(3.0);
        }
        // Multi-host future chain — residual hosting nxt three times tightly is a compaction magnet.
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= nxt * 0.4 {
            score -= 5.0 * (1.0 - (post_residual - 3 * next_item_size) as f64 / (nxt * 0.4).max(1.0)) * (0.5 + progress);
        }
        // Waste-lock penalty — slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0);
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 };
        }
        // NEW: exact-fill cascade — residual that the next item consumes to exactly zero is a perfect seal.
        if slack == 0.0 && post_residual == next_item_size {
            score -= 9.0 * (0.5 + progress);
        }
        // NEW: half-dead guard — residual that cannot host nxt even once after this placement,
        // and is too small for typical future items, is nearly permanent waste.
        if slack > 0.0 && slack < nxt && slack < mean_residual * 0.5 && progress > 0.35 {
            score += (2.0 + 4.0 * progress) * (1.0 - slack / nxt.max(1.0));
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr);
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0;
        }
        score += 9.0 * dead;
        if pr < mean_residual * 0.5 {
            score += 6.0;
        }
        if pr >= nxt * 0.5 && pr < nxt {
            score += 5.0;
        }
        if nxt - pr <= 1.0 {
            score += 6.0;
        }
        if nxt - pr <= 3.0 {
            score += if fitting_bins_count <= 2 { 4.0 } else { -2.5 };
        }
        if pr >= nxt * 0.6 && fitting_bins_count > 1 {
            score -= 4.0 * (pr / nxt);
        }
        if nxt - pr <= 6.0 && dead_ratio > 0.2 {
            score += 4.0 * dead_ratio * (1.0 - (nxt - pr) / 7.0);
        }
        if nxt - pr <= 2.0 && dead_ratio > 0.25 {
            score += 3.0 * dead_ratio;
        }
        if nxt - pr <= 8.0 && fitting_bins_count > 2 {
            score += 1.5 * (1.0 - (nxt - pr) / 9.0);
        }
        if nxt - pr <= 5.0 && dead_ratio > 0.3 && progress > 0.4 {
            score += 5.0 * dead_ratio * (1.0 - (nxt - pr) / 6.0);
        }
        // Near-miss scarcity coupling — stranding a near-miss when few bins can host nxt is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress);
        }
        // Near-miss recovery value — a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress);
        }
        // NEW: stranded-residual salvage check — a residual just below nxt that another open bin
        // could still absorb later deserves a milder penalty.
        if nxt - pr <= 8.0 && fitting_bins_count > 2 && open_bins_count > 4 && progress < 0.7 {
            score -= 2.0 * (1.0 - (nxt - pr) / 9.0);
        }
    }

    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    if post_residual > 0 {
        let waste_ratio = pr / cap;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        }
        if stranded > 0.0 {
            score += 25.0;
        }
        score += 6.0 * dead * progress;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0;
        }
        if progress > 0.4 && pr > cap * 0.35 && nxt > pr {
            score += 8.0 * (pr / cap);
        }
        if progress > 0.85 && post_residual <= 3 {
            score -= 7.0;
        }
        if pr > mean_residual * 0.9 && pr < mean_residual * 1.1 && nxt > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3);
        }
        if nxt > 0.0 && post_residual < next_item_size && nxt - pr <= 10.0 {
            let closeness = 1.0 - (nxt - pr) / 10.0;
            score += (2.0 + 6.0 * progress) * closeness
                + if fitting_bins_count <= 2 { 3.0 * closeness } else { 0.0 };
        }
        if progress > 0.7 && post_residual <= 4 && nxt > pr {
            score -= 4.0 * (1.0 - pr / 5.0);
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0;
        }
        if nxt > 0.0 && pr < nxt && pr > cap * 0.4 && fitting_bins_count > 2 {
            score -= 3.0;
        }
        if pr >= 7.0 && pr <= 15.0 {
            score += (1.5 + 4.0 * progress) * (1.0 - (pr - 7.0) / 8.0).abs() * 0.8;
        }
        if pr <= 3.0 && item >= bin_residual as f64 - 3.0 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Mid-stream consolidation: keep residuals near the mean band.
        if progress > 0.35 && progress < 0.85 && mean_residual > 0.0 {
            let dev = ((pr - mean_residual) / mean_residual.max(1.0)).abs();
            if dev > 0.5 && nxt > 0.0 && pr < nxt {
                score += 3.0 * (dev - 0.5).min(1.0);
            }
        }
        // Endgame squeeze: prefer bins whose residual stays usable near the end.
        if progress > 0.9 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 4 {
            score -= 5.0 * (1.0 - (pr - nxt) / 5.0);
        }
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 3.0;
        }
        // Low-variance preference — gently favor small residuals mid-stream.
        if progress > 0.5 && mean_residual > 0.0 && pr < mean_residual * 0.6 && nxt > 0.0 && pr < nxt {
            score -= 2.0 * (1.0 - pr / mean_residual.max(1.0)) * (progress - 0.5);
        }
        // Usable-capacity guard — residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0;
        }
        // Exact-fill dividend — residual consumed by next item to within 1 unit late.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 4.0 * (0.5 + progress);
        }
        // NEW: dead-space liquidity — a residual exactly equal to a plausible future item
        // (near the mean residual) is recoverable, not waste; soften the penalty.
        if mean_residual > 0.0 && pr >= 3.0 && (pr - mean_residual).abs() <= 2.0 && progress > 0.4 && progress < 0.85 {
            score -= 2.5 * (1.0 - (pr - mean_residual).abs() / 3.0);
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8;
        if good_fit_exists {
            score += 55.0;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 };
            score -= 10.0 + 0.05 * mean_residual - late;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0;
            }
            if fitting_bins_count > 0 && post_residual == 0 {
                score += 70.0;
            }
            if progress < 0.5 && fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual * 0.9 {
                score -= 4.0;
            }
            if progress > 0.7 && fitting_bins_count > 0 {
                score += 12.0;
            }
            if progress >= 0.3 && progress <= 0.7 && fitting_bins_count >= 2 && item <= cap * 0.35 {
                score += 9.0;
            }
            if fitting_bins_count > 0 && item >= cap * 0.85 {
                score -= 6.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && item > mean_residual
                && mean_residual > 0.0 && (mean_residual - nxt).abs() < 4.0 {
                score -= 3.5;
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0;
            }
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.5
                && item > cap * 0.5 && mean_residual < item {
                score -= 4.0;
            }
            if fitting_bins_count == 1 && nxt > 0.0 && progress > 0.4 {
                let would_strand = mean_residual > 0.0
                    && mean_residual < nxt
                    && nxt - mean_residual <= 6.0;
                if would_strand {
                    score -= 3.0 + 4.0 * progress;
                }
            }
            // Fresh-bin pull for large items whose placement elsewhere strands a big dead chunk.
            if fitting_bins_count > 0 && progress > 0.5 && item > cap * 0.45 {
                let stranded_chunk = (mean_residual - item).max(0.0);
                if stranded_chunk > nxt * 1.2 && stranded_chunk < mean_residual * 0.6 {
                    score -= 6.0;
                }
            }
            // Open a fresh bin when the item is large and would strand a big residual.
            if fitting_bins_count > 0 && item > cap * 0.5
                && (bin_residual - item_size.min(bin_residual)) > nxt.max(20.0) * 2.0 {
                score -= 5.0;
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 };
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0);
                }
            }
            // Fresh-bin chain promise — residual hosts next item twice with tight slack.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress);
                }
            }
            // Fresh-bin dead-pocket guard.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left > nxt {
                    let m = (fresh_left / nxt).floor();
                    let pocket = fresh_left - m * nxt;
                    if m >= 1.0 && m <= 4.0 && pocket > nxt - 3.0 {
                        score += 4.0 * (pocket - (nxt - 3.0)) / 3.0;
                    }
                }
            }
            // Fresh-bin triple-promise — leftover fitting nxt three times tightly is a compaction seed.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0));
                }
            }
            // Mean-residual alignment — keep fresh leftovers in the homogeneous band.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs();
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2);
                }
            }
            // NEW: fresh-bin quadruple promise — a residual hosting nxt four times tightly
            // is a near-perfect compaction seed; pull harder than the triple case.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.35 && progress < 0.85 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64;
                if fresh_left >= 4.0 * nxt && fresh_left - 4.0 * nxt <= nxt * 0.4 {
                    score -= 6.0 * (1.0 - (fresh_left - 4.0 * nxt) / (nxt * 0.4).max(1.0)) * (0.6 + progress);
                }
            }
            // NEW: fresh-bin rescue — when every open bin would strand a residual just below
            // nxt (unusable for the next item), a fresh bin is the compaction-preserving move.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 && open_bins_count > 2 {
                let all_stranding = mean_residual > 0.0 && mean_residual < nxt && nxt - mean_residual <= 5.0;
                if all_stranding && item <= cap * 0.6 {
                    score -= 5.0 * (1.0 - (nxt - mean_residual) / 6.0) * (0.5 + progress);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let tightness = post / cap;

    // Base: prefer minimal post residual, with a non-linear (quadratic) penalty
    // that grows super-linearly for larger wasted space.
    let mut score = post + 60.0 * tightness * tightness;

    // Smooth stream-progress coupling: later in the stream, waste is more costly,
    // so amplify the penalty on residual space as progress -> 1.
    score += 40.0 * tightness * (progress * progress);

    // Coupling with mean residual: if this bin's post-residual is far below the
    // mean residual, we are consolidating space well; reward it.
    score -= 25.0 * (mean_residual - post) / cap;

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 18.0 * (1.0 - post / cap);
    }
    // If the next item almost fits (within a small gap), slightly penalize leaving
    // an awkward dead space.
    if next_item_size > 0 && (next_item_size as f64) > post && (next_item_size as f64) - post <= 10.0 {
        score += 8.0 * ((next_item_size as f64) - post) / 10.0;
    }

    // Last-chance bin: strongly reward using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: penalize opening a fresh bin, more so when other bins fit,
    // and less so when the stream is early (keeping bins open for future items).
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).sqrt());
        score += 70.0 + 30.0 * (1.0 - progress) - 10.0 * open_pressure.min(3.0);
        // If this bin is the only fitting option, soften the new-bin penalty.
        if fitting_bins_count == 1 {
            score -= 45.0;
        }
    }

    // Mild penalty for very full bins late in stream is already covered;
    // add small diversity term to break ties smoothly.
    score += 0.001 * (open_bins_count as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let nxt = next_item_size as f64 ;
    let item = item_size as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let is_new_bin = bin_residual == bin_capacity ;
    let cap = bin_capacity as f64 ;
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 } ;
    let dead_ratio = if pr > 0.0 { pr / cap } else { 0.0 } ;
    let min_item = if item_size > 0 { item_size as f64 } else { 1.0 } ;
    let stranded = if pr > 0.0 && pr < min_item { 1.0 } else if pr > 0.0 && nxt > pr { 1.0 } else { 0.0 } ;

    if post_residual == 0 {
        score -= 62.0 ;
    } else if post_residual <= 2 {
        score -= 30.0 ;
    } else if post_residual <= 5 {
        score -= 14.0 ;
    } else if post_residual < 16 {
        let gap = (16 - post_residual) as f64 ;
        score += 42.0 + 3.3 * gap * gap ;
    } else if post_residual < 24 {
        let excess = (pr - mean_residual).max(0.0) ;
        score += 4.0 + 0.8 * excess ;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        if slack < 5.0 {
            score -= 47.0 - 1.5 * slack ;
        } else if slack < 12.0 {
            score -= 37.0 - 0.6 * slack ;
        } else {
            score -= 29.0 - 0.15 * slack ;
        }
        if fitting_bins_count == 1 && !is_new_bin {
            score -= 17.0 ;
        }
        if slack > 0.0 && slack < 3.0 && nxt > 0.0 && pr > mean_residual * 1.6 {
            score += 6.0 ;
        }
        if post_residual >= 2 * next_item_size {
            score -= 8.0 ;
        }
        if slack == 0.0 {
            score -= 13.0 ;
        }
        if post_residual >= 2 * next_item_size && slack <= nxt + 3.0 {
            score -= 10.0 ;
        }
        if post_residual >= 3 * next_item_size && (post_residual - 3 * next_item_size) as f64 <= 2.0 {
            score -= 8.0 ;
        }
        if slack >= 1.0 && slack <= 6.0 && mean_residual > 0.0 {
            score -= 3.0 * (1.0 - slack / 7.0) ;
        }
        if slack > 4.0 && mean_residual > 1.0 && slack >= mean_residual * 0.9 {
            score -= 2.5 ;
        }
        if slack > mean_residual * 2.5 && slack > 14.0 {
            score += 0.35 * (slack - mean_residual * 2.5) ;
        }
        // Chain-lookahead: residual hosting next item twice with tight second slack.
        if post_residual >= 2 * next_item_size && (post_residual - 2 * next_item_size) as f64 <= nxt {
            score -= 3.0 * (1.0 - (post_residual - 2 * next_item_size) as f64 / nxt.max(1.0)) * (0.6 + progress) ;
        }
        // Waste-lock: slack neither tight nor reusable mid-stream becomes permanent dead space.
        if slack > nxt * 1.2 && progress > 0.45 {
            let lock = (slack - nxt * 1.2) / nxt.max(1.0) ;
            score += (1.0 + 2.0 * progress) * lock.min(2.0) * if fitting_bins_count <= 2 { 1.4 } else { 0.7 } ;
        }
        // Dead-pocket gradient: slack just below a small multiple of nxt is stranded space.
        if slack > nxt && nxt >= 1.0 {
            let m = (slack / nxt).floor() ;
            let pocket = slack - m * nxt ;
            if pocket > nxt - 3.0 && m >= 1.0 && m <= 4.0 {
                score += 3.0 * (pocket - (nxt - 3.0)) / 3.0 * (0.4 + progress) ;
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (nxt - pr) ;
        if fitting_bins_count <= 1 && !is_new_bin {
            score += 10.0 ;
        }
        if nxt - pr <= 4.0 && fitting_bins_count > 1 {
            score += 5.0 ;
        }
        if pr > mean_residual * 1.3 {
            score += 7.0 ;
        }
        score += 9.0 * dead ;
        if pr < mean_residual * 0.5 {
            score += 6.0 ;
        }
        if pr < mean_residual * 0.35 && progress > 0.4 {
            score += 4.0 ;
        }
        // Near-miss scarcity: stranding a near-miss with few hosts is costly.
        if nxt - pr <= 6.0 && fitting_bins_count <= 2 && progress > 0.25 {
            score += 3.0 * (1.0 - (nxt - pr) / 7.0) * (0.5 + progress) ;
        }
        // Near-miss recovery value: a stranded residual may still be filled later.
        if nxt - pr <= 10.0 && nxt - pr > 6.0 && mean_residual > 0.0 && (nxt - pr) < mean_residual {
            score -= 2.0 * (1.0 - (nxt - pr) / 10.0) * (1.0 - progress) ;
        }
    }

    if post_residual > 0 {
        let waste_ratio = pr / cap ;
        if progress > 0.6 && waste_ratio > 0.25 {
            score += 10.0 * waste_ratio * (progress - 0.6) * 5.0 ;
        }
        if progress > 0.8 && post_residual < 6 {
            score -= 5.0 ;
        }
        if stranded > 0.0 {
            score += 25.0 ;
        }
        score += 6.0 * dead * progress ;
        if nxt > pr && nxt - pr <= 2.0 {
            score += 4.0 ;
        }
        if post_residual < 16 && nxt > 0.0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 > mean_residual * 0.8 {
            score += 3.0 ;
        }
        if progress > 0.9 && pr > 0.0 && pr < mean_residual.max(1.0) {
            score -= 4.0 ;
        }
        // Endgame squeeze: prefer residuals that host the next item tightly near the end.
        if progress > 0.85 && nxt > 0.0 && pr >= nxt && (pr - nxt) as u32 <= 2 {
            score -= 4.0 ;
        }
        // Exact-fill dividend late in the stream.
        if nxt > 0.0 && pr >= nxt && pr - nxt <= 1.0 && progress > 0.5 {
            score -= 3.0 * (0.5 + progress) ;
        }
        // Usable-capacity guard: residuals below the next item are pure loss late.
        if progress > 0.55 && nxt > 0.0 && pr < nxt && pr > 4.0 {
            score += 1.5 * (pr / nxt.max(1.0)) * (progress - 0.55) * 2.0 ;
        }
        // Waste growth: large dead ratio penalized increasingly.
        if waste_ratio > 0.3 {
            score += (2.0 + 8.0 * progress) * (waste_ratio - 0.3) ;
        }
    }

    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 8 ;
        if good_fit_exists {
            score += 55.0 ;
        } else {
            let late = if progress > 0.75 { 6.0 } else { 0.0 } ;
            score -= 10.0 + 0.05 * mean_residual - late ;
            if progress < 0.3 && open_bins_count > 2 {
                score += 4.0 ;
            }
            if progress < 0.5 && fitting_bins_count > 0 && mean_residual > 0.0 && pr > mean_residual * 2.0 {
                score -= 7.0 ;
            }
            if item > mean_residual * 1.8 && progress < 0.6 {
                score -= 4.0 ;
            }
            if item > cap * 0.4 && fitting_bins_count <= 1 {
                score -= 5.0 ;
            }
            if progress > 0.85 && nxt > 0.0 && bin_capacity - post_residual < next_item_size {
                score += 8.0 ;
            }
            if fitting_bins_count > 0 && mean_residual > 0.0 {
                let worst_case = item + mean_residual ;
                if worst_case > cap * 0.95 && progress < 0.7 {
                    score -= 6.0 ;
                }
            }
            if open_bins_count > 6 && mean_residual > cap * 0.3 {
                score += 5.0 ;
            }
            // Fresh-bin chain promise: leftover hosts next item twice tightly.
            if fitting_bins_count > 0 && nxt > 0.0 && progress > 0.3 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 2.0 * nxt && fresh_left - 2.0 * nxt <= 3.0 {
                    score -= 4.0 * (1.0 - (fresh_left - 2.0 * nxt) / 4.0) * (0.5 + progress) ;
                }
            }
            // Avoid opening a fresh bin that strands a residual just below next item size.
            if fitting_bins_count > 0 && nxt > 0.0 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left > 0.0 && fresh_left < nxt && nxt - fresh_left <= 6.0 {
                    score += 4.0 * (1.0 - (nxt - fresh_left) / 7.0) ;
                }
            }
            // Fresh-bin divisibility promise.
            if fitting_bins_count > 0 && nxt > 0.0
                && (bin_capacity - item_size.min(bin_capacity)) % next_item_size.max(1) == 0
                && item <= cap * 0.6 && progress > 0.35 && progress < 0.7 {
                score -= if fitting_bins_count <= 2 { 6.0 } else { 3.0 } ;
            }
            // Fresh-bin triple-promise: leftover hosts next item three times tightly.
            if fitting_bins_count > 0 && nxt >= 1.0 && progress > 0.4 && progress < 0.9 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                if fresh_left >= 3.0 * nxt && fresh_left - 3.0 * nxt <= nxt * 0.5 {
                    score -= 5.0 * (1.0 - (fresh_left - 3.0 * nxt) / (nxt * 0.5).max(1.0)) ;
                }
            }
            // Mean-residual alignment for fresh leftovers.
            if fitting_bins_count > 0 && mean_residual > 0.0 && progress > 0.45 {
                let fresh_left = (bin_capacity - item_size.min(bin_capacity)) as f64 ;
                let band = ((fresh_left - mean_residual) / mean_residual.max(1.0)).abs() ;
                if band < 0.2 {
                    score -= 3.0 * (1.0 - band / 0.2) ;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a small residue
    // (1..=5) is nearly unusable; penalize it heavily.
    let dead = if post_residual > 0 && post_residual <= 5 {
        40.0 - (post_residual as f64) * 4.0
    } else {
        0.0
    };
    score += dead;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 align
    // with the coarse item grid, making them reusable. Reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Half-capacity class (residual near 50) is a valuable "second item" slot.
    if post_residual >= 40 && post_residual <= 60 {
        score -= 8.0;
    }

    // Integer-division threshold: does the NEXT item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chainable bin: reward, more so for tight chains.
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 20.0 - chain_tightness * 0.3;
        } else {
            // Next item cannot follow: penalize proportionally to overshoot class.
            let overshoot = (next_item_size - post_residual) as f64;
            score += (overshoot / 10.0).floor() * 3.0;
        }
        // If next item exactly consumes the residual, that's ideal.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer it strongly
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are badly fragmented or scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // Penalize new bins generally; discount the penalty late in the stream
        // or when mean residual is high (open bins are full-ish).
        let mut new_bin_penalty = 35.0 * (1.0 - progress * 0.5);
        new_bin_penalty -= fragmentation * 30.0;
        if open_bins_count == 0 {
            new_bin_penalty = -100.0; // must open a bin
        }
        score += new_bin_penalty;
    }

    // Mild preference for fuller bins overall (low residual wins ties).
    score += (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Coupling: large items prefer bins whose residual is close to item size.
    let fit_slack = (bin_residual - item_size) as f64;
    score += fit_slack * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver (< min item size)
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure, zero waste
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0; // still usable by any future item
    } else {
        // mid-range gaps: mild penalty growing with gap size beyond a sweet spot
        score += 0.15 * (post_residual as f64 - 20.0).max(0.0);
    }

    // Reward tightness relative to residual (best-fit flavor with a twist).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across too many bins unless fit is excellent.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln() * (6.0 + 4.0 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // creates a gap that blocks the known next item
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 15.0 + 5.0 * (open_bins_count as f64).ln() };
        score += pressure;
    }

    score
}

